window.__D("text/likkutei-sichot/c015",{"p":[[1301550143,"ראש\" הו\"ע היראה (סתם), וריב\"ל, ה­סובר דקאי על יראת בושת, ביטול בתכ­לית (\"חרדת קדש\") — לשיטתייהו אזלי:\nבמשנה סוף סוטה נמנו כמה דברים שבטלו \"משמת\" תנא פלוני, וביניהם \"משמת רבי בטלה. . יראת חטא\", ובגמ' שם \"א\"ר נחמן<sup data-n=\"577\">37</sup> לא תיתני יראת חטא דאיכא אנא\". ונת' במ\"א<sup data-n=\"578\">38</sup> שכוונת ר\"נ היא, שא\"א לומר שנתבטלה לגמרי מדת יראת חטא, שהרי א\"א בלאו הכי [עד שגם בדורות הירודים ביותר, ואפילו בדרא דעקבתא דמשיחא (המתואר בגמ' שם) ישנה מדת יראת חטא — אלא שהיא דרגא פחותה ביראה].\nוע\"ז אמר ר\"נ \"דאיכא אנא\" — ש­הייתה אצלו דרגא זו דיראת חטא סתם, כמסופר בגמ'<sup data-n=\"579\">39</sup> ש\"אימי' דרנב\"י אמרי לה כלדאי בריך גנבא הוה, לא שבקתי' גלויי רישי' אמרה לי' כסי רישיך כי היכי דתיהוו לך אימתא דשמיא כו' יומא חד כו' נפל גלימא מעילוי' רישי'. . אלמי' יצרי' כו'\" — היינו ש(בתחילת עבודתו) היתה דרגת יראתו באופן שהוזקק לגלימא (מזכיר תמידי), ודרגא זו ביראת חטא א\"א שתתבטל (\"לא תיתני יראת חטא\"), ושייכת לכל או\"א מישראל בכל מקום ובכל זמן.\nוגם כאן אזיל לשיטתי', שה\"כובד ראש\" הנדרש מכאו\"א מישראל לתפלה אינה דרגא נעלית ביראה (שאינה שווה לכל נפש), אלא היא יראה סתם, וכנ\"ל.\nוריב\"ל דס\"ל ש\"כובד ראש\" הוא (לא יראה (יראת חטא), אלא) \"חרדת קדש\" תכלית הביטול — לשיטתי' אזיל, שס\"ל<sup data-n=\"580\">40</sup> \"ענוה גדלה מכולן\" (מכל המעלות שנמנו בברייתא דר' פינחס בן יאיר<sup data-n=\"581\">41</sup>), כולל גם יראת חטא, כי לדעתו עיקר המעלה הוא הביטול והשפלות, וכמבואר בזה<sup data-n=\"582\">42</sup> ש\"ענוה גדולה מכולן\" קאי על ענוה שהיא ביטול בעצם — ולכן ס\"ל בנדו\"ד שזוהי מעלת ה\"כובד ראש\" שצ\"ל ב­תפלה, \"חרדת קודש\".\nויש להוסיף, שגם בזה שריב\"ל ס\"ל שכובד ראש נוגע לעצם החפצא דתפלה (כנ\"ל) — לשיטתו אזיל, שאמר<sup data-n=\"583\">43</sup> \"בא וראה כמה גדולים נמוכי הרוח לפני הקב\"ה. . מי שדעתו שפלה מעלה עליו הכתוב כאילו הקריב כל הקרבנות כולם שנאמר<sup data-n=\"584\">44</sup> זבחי אלקים רוח נשברה\".\nדהנה \"תפלה (ש)היא במקום עבו­דה\"<sup data-n=\"585\">45</sup>, אלא שבזה גופא, הרי \"תפלות כנגד תמידין תקנום\"<sup data-n=\"586\">46</sup> (שהן רק עולות, המכפרות על מ\"ע לחוד<sup data-n=\"587\">47</sup>), משא\"כ ע\"י השפלות \"מעלה עליו הכתוב כאילו הקריב כל הקרבנות כולם\". שמזה מובן, שכאשר אדם משפיל עצמו בתפלתו, ה\"ז פועל עילוי שלא בערך בתפלתו<sup data-n=\"588\">48</sup>,",[["577","37","היינו ר' נחמן בר יצחק (רש\"י מגילה כח, ב). ובמ\"א נת' (לקו\"ש חי\"ג ע' 31 הערה 15) שגם להתוס' שס\"ל שסתם ר\"נ הוא ר\"נ בר יעקב (תוד\"ה אנא גיטין לא, ב) — ר\"נ דסוף סוטה הוא ר' נחמן בר יצחק. ע\"ש. וכ\"ה גירסת הע\"י שם."],["578","38","שיחות ערב חה\"ש וחה\"ש תשל\"ה. ועוד."],["579","39","שבת קנו, ב. וראה לקו\"ש שם (ע' 31 ואילך) — באו\"א."],["580","40","ע\"ז כ, ב."],["581","41","ע\"ז שם. סוף סוטה. ועוד. — וראה לקמן הערה 62."],["582","42","ראה לקו\"ת מטות פא, סע\"ד ואילך. לקו\"ש שם ע' 36 ואילך."],["583","43","סוטה ה, ב. סנהדרין מג, ב."],["584","44","תהלים נא, יט."],["585","45","ל' רש\"י ברכות כאן ד\"ה עבדו."],["586","46","ברכות כו, ב (מאמר ריב\"ל)."],["587","47","ראה אגה\"ת פי\"א (ק, ב) \"והתמיד שהוא קרבן עולה מכפר על מ\"ע בלבד\"."],["588","48","ולהעיר מהמשך מאמר ריב\"ל \"ולא עוד אלא שאין תפלתו נמאסת\" — המדגיש ג\"כ פעולת השפלות בענין התפלה (אלא שזהו בנוגע להנפעל, שתפלתו תתקבל). וכבר שקו\"ט במפרשים, מהו החי­דוש ב\"ולא עוד אלא שאין תפלתו נמאסת\", דמשמע שזהו חידוש יותר גדול מ\"הקריב כל הקרבנות כולם\". ואכ\"מ."]]],[1301550144,"שאינה רק \"עבודה\" של קרבן עולה לחוד, אלא עבודה של \"כל הקרבנות כולם\".\nוי\"ל שלדעת ריב\"ל זהו תוכנו של כובד ראש, שבא לפעול שתפלת האדם תהי' כנגד כל הקרבנות כולן<sup data-n=\"589\">49</sup>, ומובן, שלזה דרושה דרגא נעלית ביותר בהכ­נעה ושפלות, יראת בושת כנ\"ל.\nו. ויש להוסיף ביאור בשיטת ריב\"ל ב\"כובד ראש\", ע\"פ פירוש הרב המגיד<sup data-n=\"590\">50</sup>, ד\"אין עומדין כו' אלא מתוך כובד ראש. . אל תתפלל בשביל דבר שחסר לך. . תתפלל על הכבידות שיש בראש. . בשכינה כביכול\"; \"שיהי' כל כוונת תפלתו להשפיע בשכינת עוזו. . כובד ראש היינו כובד של רישא דכל רישין\"<sup data-n=\"591\">51</sup>.\nולכאורה צ\"ע<sup data-n=\"592\">52</sup>, שהרי זהו היפך גדר התפלה ע\"פ הלכה, שענינה בקשת צרכי האדם דוקא<sup data-n=\"593\">53</sup>? וי\"ל הביאור בזה<sup data-n=\"592\">52</sup>, ש­כוונת הה\"מ היא שצריך האדם להיות בדרגא נעלית בעבודת ה', שבטל לגמרי קמי' ית', ועד שכל מציאותו אינה אלא ביטולו לה'. ובמילא זוהי \"בקשת צרכיו\" — כי אינו צריך כלום לעצמו, וכל דאגתו וצרכיו אינם אלא \"צורך גבוה\", שיתמלא רצון השכינה. ולכן מתפלל על \"כובד\" וחסרון השכינה כביכול, \"רישא דכל רישין\".\nוי\"ל שזוהי דרגת ריב\"ל שנכנס<sup data-n=\"595\">54</sup> חי לגן עדן, שענין כזה — שהגוף הגשמי יעלה לגן עדן — הוא תוצאה מזה שהאדם בטל כ\"כ לגבי קדושתו ית' עד שדברים גשמיים אינם תופסים מקום אצלו כלל, וגופו עם כל עניניו אינם אלא כלי לנשמתו (שהיא \"חלק אלקה ממעל ממש\"<sup data-n=\"596\">55</sup>), ולכן גוף כזה יכול להכנס חי לגן עדן (מקום הרוחניות).\nוזהו שס\"ל לריב\"ל ש\"כובד ראש\" היינו דרגת יראת בושת, שהוא ביטול בתכלית; ואז תפלתו היא מתוך \"כובד ראש\" — \"רישא דכל רישין\", כנ\"ל.\nז. ע\"פ כל הנ\"ל יש לבאר פלוגתת הבבלי והירושלמי (הנ\"ל סעיף א) — שהבבלי מסיק שהלימוד הוא מ\"עבדו גו' ביראה\", ובירושלמי הובאו למסקנא ב' הלימודים (\"השתחוו גו' בהדרת קודש\" ו\"עבדו גו' ביראה\"):\nבבל הוא מצב של גלות, שאין שם גילוי הקדושה, ועד שגם על תלמוד בבלי אמרו<sup data-n=\"597\">56</sup> \"במחשכים<sup data-n=\"598\">57</sup> הושיבני\", מצב של חושך והעלם והסתר — ולכן ב­תלמוד בבלי מסיק (כדעת רנב\"י) דילפי­נן \"כובד ראש\" מ\"עבדו את ה' ביראה\",",[["589","49","אלא שצע\"ק לשון המשנה \"אין עומדין להתפלל אלא מתוך כובד ראש\", דמשמע שזהו ענין לעיכובא בעצם ענין התפלה."],["590","50","או\"ת ד\"ה אין עומדין (קח, ג). שם ר\"פ ויגש (יט, ג). וראה ד\"ה אין עומדין במאמרי אדה\"ז ואוה\"ת על מרז\"ל הנ\"ל הערה 18 ובהנסמן במ\"מ שם. וכן בשאר מקומות שצויינו בהערה הנ\"ל."],["591","51","ולהעיר משנות אליהו (להגר\"א) ברכות שם בפי' המשנה \"שיכונו את לבם לאביהם שבשמים\" — \"פי' שאסור לכוין בתפלה לצורך עצמו אך להתפלל שיהיו כל ישראל בתכלית השלימות ויהי' נשלם כנסת ישראל למעלה, אבל לא לצורך עצמו\"."],["592","52","וראה בארוכה לקו\"ש חכ\"ג ע' 217 ואילך. וראה לקו\"ש חי\"ט ע' 293 ואילך."],["593","53","ראה רמב\"ם הל' תפלה פ\"א ה\"ב­ד. ספהמ\"צ להצ\"צ שרש מצות התפלה בתחלתו. וש\"נ."],["592","52","וראה בארוכה לקו\"ש חכ\"ג ע' 217 ואילך. וראה לקו\"ש חי\"ט ע' 293 ואילך."],["595","54","כתובות עז, ב."],["596","55","ל' התניא רפ\"ב."],["597","56","סנהדרין כד, א."],["598","57","איכה ג, ו."]]],[1301550145,"דהיינו יראת חטא (כנ\"ל בארוכה), כי במצב של \"בבל\" (חושך) מודגש שא\"א לתבוע מאיש ישראל יותר מדרגא זו ביראת ה'<sup data-n=\"599\">58</sup>;\nמשא\"כ בתלמוד ירושלמי — תורת א\"י<sup data-n=\"600\">59</sup>, ששם \"עיני ה\"א בה מרשית השנה ועד אחרית שנה\"<sup data-n=\"601\">60</sup>, יותר קל להגיע למדריגות נעלות יותר ביראת ה'<sup data-n=\"602\">61</sup>, ולכן הובאה שם גם דעת ריב\"ל<sup data-n=\"603\">62</sup> (ואדרבה, דיעה זו הובאה לראשונה) שילפינן לה מ\"השתחוו לה' בהדרת קודש, בחרדת קודש\"<sup data-n=\"604\">63</sup>.\nויש לומר, דזה שהילקוט (עה\"פ השתחוו גו') מביא רק דעת ריב\"ל, הוא לפי שבחלק המדרש שבתורה — ש\"רוב סודות התורה. . גנוזים באגדות\"<sup data-n=\"605\">64</sup> — מודגש התוכן הפנימי של \"כובד ראש\", ולכן יש מקום להכריע (רק) כדעת ריב\"ל, ש\"כובד ראש\" היינו הביטול ד\"חרדת קודש\" (ועד ל\"כובד ראש\" לפי פירוש הרב המגיד\" — \"כובד ראש\" — \"רישא דכל רישין\").\nויש לומר, שמצד פנימית הנשמה שבכאו\"א, ביכולתו של כאו\"א להגיע גם לדרגא זו, עכ\"פ \"שמץ מנהו ואפס קצהו\",\nואזי התפלה נשמעת, שנשפע כביכול \"בשכינת עוזו\", ש\"ימולא. . לעילא\"<sup data-n=\"606\">65</sup> החסרון העיקרי — זה ד\"שכינתא ב­גלותא\", ע\"י קיום היעוד<sup data-n=\"607\">66</sup> \"ושב ה\"א את שבותך\", \"שהקב\"ה שב עמהן\", בגאולה האמיתית והשלימה, במהרה בימינו ממש.\n<span data-k=\"q\">(משיחת י\"ג תמוז תשל\"ה) </span>",[["599","58","ולהעיר, שר' נחמן הי' מחסידי דבבל (פרש\"י מגילה שבהערה 37. וראה לקו\"ש חי\"ג ע' 32 הערה 21)."],["600","59","ראה שערי אורה ד\"ה בכ\"ה בכסלו פנ\"ד ואילך. סה\"מ תש\"ח ע' 121 ואילך. ועוד."],["601","60","עקב יא, יב."],["602","61","וראה בארוכה לקו\"ש בהעלותך תש\"נ — ע\"ד החילוק בין סיום מס' סוטה בבבלי ובירושלמי. ע\"ש."],["603","62","ולהעיר, שלפי שיטת (וגירסת) התוס' (ע\"ז כ, ב), ס\"ל להירושלמי שברייתא דר' פינחס קאי בשיטת ריב\"ל ד\"ענוה גדולה מכולן\" (משא\"כ להבבלי) — ראה לעיל סעיף ה (ולקו\"ש חי\"ג שנסמן שם)."],["604","63","ולהעיר, שגם הלימוד מ\"עבדו את ה' ביראה\" הובא בירושלמי (לא בשם רנב\"י, אלא) בשם ר' יוסי בר חנינא (שבבבלי הובא משמו הלי­מוד מ\"ואני גו' ביראתך\"). וי\"ל שלהירושלמי \"עבדו גו' ביראה\" אינה יראת חטא (כדעת רנב\"י) אלא מדריגה נעלית ביראה."],["605","64","הל' ת\"ת לאדה\"ז פ\"ב ס\"ב (ע\"פ ספרי פרשתנו יא, כב. רמב\"ן בסהמ\"צ מ\"ע ז). וראה גם הקדמת הרמב\"ם לפיהמ\"ש (ד\"ה אח\"כ ראה)."],["606","65","או\"ת שם ר\"פ ויגש."],["607","66","נצבים ל, ג. מגילה כט, א. ועוד. פרש\"י עה\"פ."]]],[1301550146,"<h3>שיחה א</h3>\nא. כתב הרמב\"ם<sup data-n=\"608\">1</sup> \"פירות הנלקחות בכסף מעשר שני אינן נפדין בריחוק מקום אלא א\"כ נטמאו באב הטומאה אלא יעלו הן עצמן ויאכלו בירושלים\", וממשיך בה\"ב \"זה חומר בלקוח בכסף מעשר מפירות מעשר עצמן\".\nוכ' הרדב\"ז דמקור דין זה הוא ב­משנה דמעשר שני<sup data-n=\"609\">2</sup>: הלקוח בכסף מעשר שני שנטמא יפדה רבי יהודה אומר יקבר אמרו לו לר\"י ומה אם מע\"ש עצמו ש­נטמא הרי הוא נפדה הלקוח בכסף מע\"ש שנטמא אינו דין שיפדה א\"ל לא אם אמרתם במע\"ש עצמו שכן הוא נפדה ב­טהור ברחוק מקום<sup data-n=\"610\">3</sup> תאמרו בלקוח ב­כסף מעשר שאינו נפדה בטהור<sup data-n=\"611\">4</sup> ברחוק מקום.\nוכותב הרדב\"ז: למדנו שהלקוח ב­כסף מעשר שני אינו נפדה ברחוק מקום לדברי הכל<sup data-n=\"612\">5</sup> וזהו שכתב רבינו זה חומר בלקוח בכסף וכו' שאין נפדין ברחוק מקום אלא א\"כ נטמאו. . ואשכחנא בכמה דוכתי דטפל חמור מן העיקר.\nוהנה מ\"ש הרדב\"ז שדין זה דומה להא דאשכחן בכמה דוכתי דטפל חמור מן העיקר, מקורו בגמ' זבחים<sup data-n=\"613\">6</sup>, דאיתא שם שמצינו טפל חמור מן העיקר בדין פדיון מע\"ש — \"והרי מעשר דהוא נפדה ואילו לקוח בכסף מעשר אינו נפדה דתנן הלקוח בכסף מעשר שנטמא יפדה ר\"י אומר יקבר\" (אלא שאח\"כ נדחית בגמ' דוגמא זו, כדלקמן סעיף ה).\nאמנם בדברי הגמ' (שבדין פדיון מע­שר מצינו טפל חמור מן העיקר) יש שני פירושים — מתאים לב' גירסאות בגמ':\nא) לגירסת ופירוש רש\"י<sup data-n=\"614\">7</sup> (וכן הוכיחו בתוס'<sup data-n=\"615\">8</sup> מתוספתא) — הראי' היא מדעת ר' יהודה, דהלקוח בכסף מעשר שנטמא אינו נפדה (אלא \"יקבר\"), ואילו מעשר שני שנטמא נפדה אפי' בירושלים, אלמא דטפל חמור מן העיקר.\nב) \"אית<sup data-n=\"616\">9</sup> ספרים דגרסי הכא נטמא אין לא נטמא לא ומייתי ראי' מרבנן דטפל חמור מעיקר\", כלומר, הראי' היא מלקוח בכסף מעשר טהור, שהדין הוא שאינו נפדה אפי' חוץ לירושלים (דרק אם נטמא יפדה), משא\"כ מעשר עצמו (אפילו טהור) נפדה חוץ לירושלים.\nולכאורה כ\"ה דעת הרמב\"ם [לפירוש הנ\"ל שברדב\"ז, שלדעת הרמב\"ם הוי דין זה בכלל \"טפל חמור מן העיקר\"] — שהרי ברמב\"ם כאן מפורש, שהחומר שבלקוח בכסף מעשר לגבי מעשר עצמו הוא בנוגע לפדיית פירות טהורים (והיי­נו אליבא דרבנן, כנ\"ל).",[["608","1","הל' מעשר שני ונטע רבעי פ\"ז ה\"א."],["609","2","פ\"ג מ\"י."],["610","3","ובפרט את\"ל ש\"כי לא תוכל שאתו\" (פר­שתנו יד, כד) הוא לא לעכובא, כ\"א שדבר הכתוב בהווה. — ראה לקמן רס\"ב ורס\"ג."],["611","4","ברדב\"ז שם ליתא תיבה זו."],["612","5","וכן כתב הרמב\"ם בפיהמ\"ש מע\"ש שם. ובתוד\"ה רבי יהודה (פסחים לח, א) בסופו כ' דהוא מדרבנן. אבל ראה תוס' הרשב\"א (להר\"ש משאנץ) פסחים שם. וראה לקמן בפנים. ואכ\"מ."],["613","6","מח, סע\"ב ואילך. וראה אור שמח כאן, שה­רמב\"ם כיון להא דזבחים."],["614","7","ד\"ה והרי מעשר וד\"ה אינו נפדה."],["615","8","ד\"ה והרי מעשר. ועד\"ז בר\"ש מע\"ש שם."],["616","9","ל' התוס' שם. ועד\"ז בר\"ש שם."]]],[1301550147,"והנה בהסברת טעמו של רש\"י (וד­עימי') שס\"ל שהראי' בגמ' אינה מדעת רבנן (שהלכה כמותן), כ\"א רק מדעת ר\"י — כתבו בתוס'<sup data-n=\"615\">8</sup>, ד\"האי (שפירות ה­לקוחים במעות מעשר אין לפדות חוץ לירושלים, משא\"כ פירות מעשר עצמם) לא מיקרי טפל חמור מן העיקר דמעשר עצמו טהור נפדה ברחוק מקום כדי ליקח (לפדות) בדמים בירושלים בקר וצאן כו' אבל אם לקח פירות בו חוץ לירושלים כדי לאוכלם בירושלים לא יפדה כמו שלא הי' פודה מה שהי' לוקח בירושלים\" [וכ\"כ הרדב\"ז שם (בפירושו השני) ד\"הרי<sup data-n=\"618\">10</sup> זה כאילו קנאם בירו­שלים דלא חזו לפדיי'. . (ומסיים) וטעם זה מספיק אפי' למ\"ד דלא מחמרינן בטפל טפי מן העיקר\"].\nועפ\"ז, את\"ל שהרמב\"ם ס\"ל שיש בדין זה (שפירות הלקוחים אינם נפדים כמו מעשר עצמו) משום \"טפל חמור מן העיקר\", עכצ\"ל שלא ס\"ל להך סברא שפירות שנלקחו במעות מעשר \"הרי זה כאילו קנאם בירושלים\".\nב. ויש לבאר סברת הפלוגתא בהק­דם גדר פדיון מעשר שני, שיש לבארו בכמה אופנים:\nא) דהוי היתר לגברא, כפשטות ה­כתובים<sup data-n=\"619\">11</sup> \"וכי ירבה ממך הדרך כי לא תוכל שאתו גו' ונתתה בכסף וצרת הכסף בידך והלכת אל המקום גו'\". דאף ש(עיקר) מצות מע\"ש היא לאכול<sup data-n=\"620\">12</sup> את פירות המעשר עצמם בירושלים<sup data-n=\"621\">13</sup>, מ\"מ כאשר יש טורח לאדם להביא את ה­פירות לירושלים (\"כי ירבה ממך הדרך גו'\"), הותר לו לפדות הפירות בכסף, ולקנות בכסף זה פירות בירושלים ולאכלם שם.\nב) פדיון פירות מע\"ש אינו בגדר היתר להגברא, אלא דכך היא מצות<sup data-n=\"622\">14</sup> מע\"ש מעיקר הדין, דכאשר \"ירבה ממך הדרך כי לא תוכל שאתו גו'\" אמרה תורה שפודים הפירות בכסף כו'. כלו­מר: התורה קבעה מלכתחילה שני או­פנים בקיום מצות מע\"ש<sup data-n=\"623\">15</sup>: א) הבאת הפירות עצמם לירושלים, ב) פדיון ה­פירות והבאת הכסף לירושלים ע\"מ לקנות שם פירות כו' ולאכלם כו'<sup data-n=\"624\">*15</sup>.\nובזה גופא י\"ל בשני אופנים:\nא) דין פדיון מע\"ש הוא פרט בהדין הכללי דאכילת פירות מע\"ש בירושלים,",[["615","8","ד\"ה והרי מעשר. ועד\"ז בר\"ש מע\"ש שם."],["618","10","וכ\"ה הל' בר\"ש שם (ולא כל' התוס')."],["619","11","פרשתנו יד, כד­כה."],["620","12","ראה בארוכה מנ\"ח (מצוה תמב), דאין מ\"ע לאכול מע\"ש בירושלים כ\"א ל\"ת ד\"לא תוכל לאכול בשעריך גו'\". ואשר כן מוכח מהרמב\"ם דלא מנה במנין המצות מ\"ע לאכול מע\"ש בירושלים (ומנה רק ההפרשה — במ\"ע קכח). עיי\"ש בארוכה. וברמב\"ן בסהמ\"צ בסוף חלק המ\"ע הוסיף המצוה שנצטוינו לאכול מע\"ש ובכורות בירושלים. ואכ\"מ."],["621","13","כמ\"ש (שם, כג) ואכלת לפני ה\"א וגו'. רמב\"ם רפ\"ב מהל' מע\"ש."],["622","14","להעיר מתוד\"ה אמר (מכות יט, ב), דלפני שיראה פני הבית אף ד\"ליכא לאו אבל עשה איכא דכתיב וצרת הכסף בידך אבל בלא פדי' לא\" (ועד\"ז הוא בריטב\"א שם). וראה כס\"מ שם פ\"ב ה\"ו, דהביא תוס' הנ\"ל בביאור דעת הרמב\"ם. ואכ\"מ."],["623","15","וכדמוכח גם מזה ש\"אפי' בפסיעה אחת חוץ לחומה\" פודין אותו (מכות שם). ויתירה מזו, גם אם הי' הוא בפנים ומעשרו בחוץ, ואפי' הי' אוחז בקנה — מותר לפדותו שם בצד החומה (רמב\"ם שם פ\"ב ה\"ח), ולא אמרינן שצריך להכניסו בפנים ולקיים מצותו בשלימות."],["624","*15","להעיר מלשון רש\"י שופטים כ, ו ד\"ה ולא תחללו — בנוגע לנטע רבעי (ש\"דינו להאכל בירושלים לבעליו כמעשר שני לכל דבר\" — ל' ה­רמב\"ם בהכותרת להל' מע\"ש ונטע רבעי ושם רפ\"ט) — \"שהפירות טעונין לאכלן בירושלים או לחללן בדמים ולאכול הדמים בירושלים\"."]]],[1301550148,"כלומר: המצוה דמעשר שני היא — שפירות מע\"ש צריכים להאכל בירו­שלים, ויש שני אופנים לקיים מצוה זו, אם ע\"י הבאת הפירות עצמן, או ע\"י פדיית הפירות בכסף ולקיחת פירות בירושלים (בכסף זה).\nב) דין פדיון פירות מע\"ש בכסף אינו (רק) הכשר מצוה המביא למצות אכילת מע\"ש בירושלים אלא הוא דין בפ\"ע. והיינו, שבפירות מעשר שני יש שני דינים נפרדים (שאינם תלויים זב\"ז): א) הבאת הפירות עצמם לירושלים ואכי­לתם שם. ב) דין פדי', דפירות הנמצאים בריחוק מקום מירושלים יש מצוה לפ­דות פירות אלו — \"ונתתה בכסף וצרת הכסף בידך\" (וכדמשמע גם מזה שקבעו ברכה מיוחדת על פדיית פירות מע\"ש<sup data-n=\"625\">16</sup>, הרי שפדיית מע\"ש אינה (רק) הכשר למצות הבאתו ואכילתו בירושלים).\nג. ויש לומר, שלפי שלשת אופנים אלו יש להסביר את חילוקי הטעמים בדין דהלקוח בכסף מעשר שני אינו נפדה בריחוק מקום (אף שפירות מעשר שני עצמם נפדים):\nא) בשיטה מקובצת<sup data-n=\"626\">17</sup> כתב \"משום דאמר רחמנא במעשר טהור שפודים אותו חוץ לירושלים היינו בשביל טורח הדרך שחס רחמנא על טרחו כדכתיב כו' וזה שלקח מן הכסף פירות ברחוק מקום כדי לאכלו בירושלים ג\"כ גלה דעתו דאינו חס על טרחו לפיכך אינו נפדה כשהוא טהור\"<sup data-n=\"627\">18</sup>.\nדלטעם זה מוכח שעיקר דין פדיון מע\"ש הוא בגדר היתר להגברא, שבגלל קושי הטרחא חס עלי' רחמנא והותר לו להביא כסף (במקום פירות) לירושלים, ולפיכך, אדם זה שגילה דעתו שאינו חס על טרחו, הרי הוציא את עצמו מהיתר זה.\nב) טעם התוס'<sup data-n=\"615\">8</sup> (כנ\"ל), ד\"מעשר עצמו טהור נפדה ברחוק מקום כדי ליקח בדמים בירושלים בקר וצאן כו', אבל אם לקח בו פירות חוץ לירושלים כדי לאוכלם בירושלים לא יפדה כמו שלא הי' פודה מה שהי' לוקח בירושלים\" (וכמ\"ש הרדב\"ז (כנ\"ל)<sup data-n=\"618\">10</sup> ד\"הרי זה כאילו קנאם בירושלים\").\nולטעם זה, דין פדיון מע\"ש (אינו רק היתר להגברא אלא ש)זהו דין (פדי') בה­פירות, היינו שזהו ממצות מע\"ש ש­\"מעשר עצמו טהור נפדה ברחוק מקום כדי ליקח בדמים בירושלים בקר וצאן כו'\", אלא שדין פדי' זה הוא אך ורק בשביל לקיחת פירות בכסף זה<sup data-n=\"630\">19</sup> — \"ו­נתתה הכסף בכל אשר תאוה נפשך\"<sup data-n=\"631\">*19</sup>, ולכן, לאחרי שקנה פירות בכסף זה (אף חוץ לירושלים) נתקיימה ונגמרה מצות פדי' ושוב אין הפירות נפדים.\n[וכן מפורש בקרית ספר כאן<sup data-n=\"632\">20</sup>, דזה ש\"פירות הנלקחות בכסף מעשר שני אינם נפדים בריחוק מקום כפירות",[["625","16","רמב\"ם שם פ\"ד ה\"ג. ולהעיר מהשגת ה­ראב\"ד שם ה\"ד: והלא מכיון שמברכים על פדיונו מצוה הוא ולמה טומנין את המצוה. וראה לקמן ב­פנים."],["626","17","לזבחים שם (מט, רע\"א) אות א' (נדפס בסוף המס')."],["627","18","וראה גם מלאכת שלמה למשנה מע\"ש שם: כיון דלקח צרכי סעודה מן הכסף וגלי אדעתי' דלא הי' קשה בעיניו להעלותו כו' הלכך קנסוהו דיעלהו ולא מצי פריק לי' דהוי זלזולו של מע\"ש. אלא דשם מפרש כן דברי הר\"ש שם."],["615","8","ד\"ה והרי מעשר. ועד\"ז בר\"ש מע\"ש שם."],["618","10","וכ\"ה הל' בר\"ש שם (ולא כל' התוס')."],["630","19","כמו שהובא בדברי התוס', הר\"ש והרדב\"ז שם."],["631","*19","פרשתנו יד, כו."],["632","20","להמבי\"ט רפ\"ז מהל' מע\"ש. וראה גם תוס' זבחים שם בתחלתו וכן בר\"ש מע\"ש שם. אלא דשם כ' כן בדעת ר\"י. ע\"ש."]]],[1301550149,"מעשר שני עצמו\" הוא מפני \"שכבר נגמר מצותו<sup data-n=\"633\">21</sup> ושוב אינו נפדה\"<sup data-n=\"634\">22</sup>].\nג) לפירוש הא' (ברדב\"ז) בדעת ה­רמב\"ם, דזה שלקוח בכסף מע\"ש אינו נפדה הוי בכלל טפל חמור מן העיקר (ולא כהטעמים דלעיל ש\"האי לא מיקרי טפל חמור מן העיקר\") — י\"ל (כאופן הג' דלעיל) שדין פדיון פירות מע\"ש הוי מצוה בפ\"ע הנגמרת מיד בפדייתם<sup data-n=\"635\">23</sup> (ולא רק הכשר לאכילת פירות מע\"ש בירושלים)<sup data-n=\"636\">24</sup>. ולכן לא שייך לומר דכאשר קנה פירות בכסף זה הוי כאילו קנאם בירושלים ונגמרה מצותו — כי אין הבאת הכסף ולקיחת פירות בירושלים גמר מצות פדי', אלא הוא חלק מהמצוה הכללית דהבאת פירות מע\"ש לירושלים ואכילתם שם (וכנ\"ל, שבמצוה זו יש שני אופנים: להביא פירות מעשר עצמן, או להביא הכסף ולקנות הפירות בירוש­לים). ובמילא, לאחר שפדה פירות מע\"ש מיד נגמרה חובת הפדיון<sup data-n=\"637\">25</sup>, ומעתה חל עליו החיוב הכללי להביא הכסף או הפירות הקנויים בו לירושלים כו' (ע\"ד החיוב להביא פירות מעשר עצמן לירו­שלים), וחובת ההבאה והאכילה לא נגמרה עד לאחרי אכילת פירות בירו­שלים;\nומכיון שאעפ\"כ הפירות הלקוחים אינם נפדים כפירות מע\"ש עצמם, הרי שהטפל חמור מן העיקר.\nד. ובזה יש לבאר גם כוונת הרמב\"ם במ\"ש \"זה חומר בלקוח בכסף מעשר מפירות מעשר עצמן\" — דלכאורה אינו מובן, מה מוסיף הרמב\"ם בדברים אלה על עצם הדין גבי לקוח (שפירות ה­נלקחות בכסף מעשר שני אינם נפדים) שכבר כתבו בהלכה שלפנ\"ז?\nוע\"פ הנ\"ל יש לומר, שבזה בא ה­",[["633","21","ועד\"ז הוא ברע\"ב למשנה מע\"ש שם [אלא שפירש כן בפירות שנטמאו, דלדעת ר\"י \"יקבר — הואיל ונגמר מצותו וקנה פירות ממעות מע\"ש שוב לא יפדה\"]."],["634","22","בקרית ספר אפשר לפרש שכבר נגמר מצותו — היינו מצות פדי' דפירות מע\"ש, והוי מצוה בפ\"ע. אבל בריטב\"א ב\"מ (נג, ב ד\"ה כרבי יהודה) בתירוץ דברי ר\"י \"דהתם (גבי סלעים על דינרין (שם מה, א) דלא דריש כסף ראשון ולא כסף שני אלא כסף כסף ריבה) לא נגמר עדיין מעשה המעשר שעדיין לא נגמר פדיונו לגמרי\", משמע דהוי מכלל מצות מע\"ש, שסיומה הוא הבאתו לירושלים."],["635","23","וי\"ל דע\"פ הנ\"ל יומתק גם מה שמוסיף הרמב\"ם (פ\"ד ה\"ג) ומפרט בהברכה \"אשר קדשנו במצותיו וצונו (על פדיון מע\"ש)\" — ובמקורו (ירושלמי דמאי פ\"א ה\"ד) ליתא (וראה רמב\"ם הל' מעשר ספ\"א) — להדגיש שהוא קיום מצוה בפ\"ע. אבל להעיר דבהעתקת הברכות ברמב\"ם כמה או­פנים: בכמה מקומות מביא כל נוסח הברכה, גם השם ומלכות, לפעמים כנ\"ל \"אשר קדשנו כו'\", ולפעמים רק סיום הברכה — וראה רמב\"ם הל' ברכות פי\"א. ואכ\"מ."],["636","24","ואולי יש לבאר עפ\"ז פסק הרמב\"ם ברפ\"ד, דכאשר פדה פירות מע\"ש בדמיהן, אם לא פירש אלא הפריש מעות בלבד כנגד הפירות דיו ואינו צריך לפרש (כדעת ר' יוסי בפ\"ד דמע\"ש מ\"ז) — כי כיון שדין פדיון הוא בהחפצא דהפירות עצמן, הרי נמצא שהפירות עצמם \"עומדים\" לפדות, אלא שתלוי ברצון הגברא איזה דין ואופן רוצה לקיים בפירות אלו אי להעלותם לאוכלם או לפדות אותם. משא\"כ להפירוש שהוא רק היתר להגברא (כאופן הא' דלעיל) ואינו דין בפירות מע\"ש גופא י\"ל דצריך לפרש מעשיו כי הפירות מצ\"ע אינם עומדים לפדיון. ועפ\"ז יש לבאר מה שבדין הנ\"ל מתחיל הרמב\"ם \"הרוצה לפדות\", ולא התחיל ע\"ד הלשון בכתוב באם לא תוכל להעלותן (וכיו\"ב) אז תיפדה כו', כי א) דין פדיון אינו דין בדמוכרח דוקא, ב) הוי דין בגוף הפירות. אבל לכאורה כ\"ז אפשר לומר גם לאופן הב' הנ\"ל. ועצ\"ע. ואכ\"מ."],["637","25","היינו שבזה נגמרה המצוה שבפירות מע\"ש בריחוק מקום (שהרי לאחרי פדיונם מותרים באכילה בכ\"מ)."]]],[1301550150,"רמב\"ם להדגיש שיש כאן חידוש, שיש חומר בלקוח בכסף מעשר מפירות מע­שר עצמן, היינו שכוונת הרמב\"ם היא להחידוש דטפל חמור מן העיקר, ובזה מגדיר הרמב\"ם הדין דפדיון מע\"ש, ש­הוא כאופן הג' הנ\"ל, שיש כאן משום טפל חמור מן העיקר, כנ\"ל בארוכה.\nה. אמנם עדיין צריך להבין.\nאיך אפשר לומר דס\"ל להרמב\"ם דדין זה (שלקוח בכסף מע\"ש אינו נפדה) יש בו משום \"טפל חמור מן העיקר\" — והרי בגמ' שם<sup data-n=\"638\">26</sup> מסיק שאין להביא ראי' מדין זה ש\"יש טפל חמור מן העיקר\", כי \"התם לא אלימא קדושתי' למיתפס פדיוני'\"<sup data-n=\"639\">27</sup> [והיינו דזה שאין לפדות פי­רות הלקוחים בכסף מעשר אינו מחמת החומר שבהם, אלא אדרבה, משום ש­קדושתם היא קדושה קלה (\"לא אלימא קדושתי'\") שאין ביכולתה להתפיס את דמי הפדיון]?\nבפשטות י\"ל:\n(א) מכיון שאין זה פסק הלכה אלא (רק ע\"ד) טעם הלכה — נקט הרמב\"ם הטעם הפשוט יותר (ע\"ד המבואר בכללי הרמב\"ם<sup data-n=\"640\">28</sup> שכותב דרשה הפשוטה יותר כו').\n(ב) שהרמב\"ם ס\"ל דזה הוי רק קס\"ד בגמרא, אבל למסקנא נקטינן דהוי בכלל טפל חמור מן העיקר<sup data-n=\"641\">29</sup> (כלשון הרדב\"ז \"ואשכחנא בכמה דוכתי<sup data-n=\"642\">30</sup> דטפל חמור מן העיקר\").\nאבל להסביר יותר יש לומר, דזה שכתבו הרמב\"ם כאן הוא משום שתוכן מצות מעשר שני קשור עם כלל זה שמצינו טפל חמור מן העיקר.\nו. נתבאר במ\"א<sup data-n=\"643\">31</sup> החילוק בין בכור למעשר (בהמה), דבכור קדושתו היא מרחם<sup data-n=\"644\">32</sup> ואינה תלוי' בפעולת האדם; משא\"כ קדושת מעשר תלוי' בפעולת האדם, שהאדם מונה את הצאן, ואז נעשה \"העשירי<sup data-n=\"645\">33</sup> (יהי') קדש\"<sup data-n=\"646\">34</sup>, ועד\"ז הוא גם במעשר שני, שחלות \"קדושתו\" היא ע\"י מעשה ההפרשה.\nוהיינו, שבכור הוא קדושה משמיא, ומעשר הוא קדושה הנעשית ע\"י האדם.\nאמנם בפרטיות יש גם במעשר עצמו ב' ענינים: (א) מעשה האדם שהוא המנין (ההפרשה<sup data-n=\"647\">35</sup>), (ב) הקדושה משמיא<sup data-n=\"648\">36</sup> ה­באה לאח\"ז.",[["638","26","זבחים שם (מט, א)."],["639","27","וכן הביא רש\"י טעם זה בכ\"מ בש\"ס (פסחים לח, א. ב\"מ נג, ריש ע\"ב (ד\"ה יקבר). סנהדרין קיג, רע\"א), שזהו הטעם דר\"י שיקבר. וזהו על פי פירושו כאן בזבחים, דהגמ' בא להביא ראי' מר\"י. ובדעת רבנן כתב בפסחים שם, דלקוח בכסף מעשר שנטמא יפדה דאלימא למיתפס פדיונו."],["640","28","יד מלאכי כללי הרמב\"ם אות ד."],["641","29","ראה לקח טוב (להר\"י ענגל) כלל יז בתחלתו, דמזה דקאמר בזבחים שם ואבע\"א כו' \"מוכח בהדיא דס\"ל להאי שינוי' דאפשר לטפל שיהי' חמור מן העיקר דאל\"כ למה לו לאיבע\"א הלא די בתירוץ הראשון\"."],["642","30","אף שבכמה סוגיות איתא דא\"א לטפל שיהא חמור מן העיקר — ראה זבחים סג, א. מנחות צא, ב. בכורות יד, ריש ע\"ב. וראה לקח טוב שם."],["643","31","ראה לקו\"ש חי\"ז ע' 333. וש\"נ."],["644","32","ראה רמב\"ם הל' בכורות פ\"א ה\"ד."],["645","33","בחקותי כז, לב."],["646","34","ראה בפרטיות לקו\"ש שם ע' 333 הערה 10, 11."],["647","35","ראה לשון הרמב\"ם ריש הל' מע\"ש. סהמ\"צ מ\"ע קכח."],["648","36","שהרי האדם רק \"מונה\" (אומר מספר) וקדושה מאן דכר שמי'. ומשמיא נאמר \"העשירי יהי' קודש\". וראה רמב\"ם הל' בכורות פ\"ח ה\"ג \"שה­עשירי מעצמו נתקדש\", שם ה\"ז \"שהעשירי מאליו נתקדש\".\nולהעיר דהאינו יודע מתי שבת מונה ששה ימים והשביעי שבת (שבת סט, ב). ואת\"ל שצ\"ל תפלות וקידוש אומר \"מקדש השבת\" — כי שבת מקדשא וקיימא (ביצה יז, א. רש\"י ד\"ה מקדש השבת — ברכות מט, א)."]]],[1301550151,"ולפי משנת\"ל יש לומר שיש חידוש במעשר שני — שיש בו לא רק מצוה של הפרשה והקדושה הבאה על ידה משמיא, אלא גם מצוה של פדיון (וכנ\"ל, שאין זה רק היתר ויכולת בכדי להביא הפירות לירושלים, כ\"א דהוי (עוד) דין וחיוב בקיום מצות מע\"ש), אשר חלות הקדושה שע\"י הפדיון באה ע\"י הפדי', פעולת האדם.\nוזהו מה שכתב הרמב\"ם שיש \"חומר בלקוח בכסף מעשר מפירות מעשר עצמן\":\n\"פירות מעשר עצמן\" ה\"ז קדושה הבאה משמיא, ואילו ה\"לקוח בכסף מעשר\" ה\"ז קדושה הבאה ע\"י פעולת האדם (שהאדם פדה את המעשר, ויתירה מזו — חילל אח\"כ את המעות על פירות אחרים), וכפי שנמצא האדם ב\"ריחוק מקום\" (דוקא) מירושלים, קדושה נוספת על קדושת שאר ארץ ישראל (כדבר המשנה<sup data-n=\"649\">37</sup>).\nואף שבפשטות הקדושה הבאה מ­שמיא היא קדושה יותר מזו שבאה ע\"י מעשה האדם, וע\"ד ובסגנון רז\"ל מעשה האדם היא \"קב שלו\"<sup data-n=\"650\">38</sup>, קב אחד בלבד, ואינה בערך ל\"תשעה קבים\"<sup data-n=\"650\">38</sup> של חבירו (הקב\"ה, וכמ\"ש רעך ורע אביך אל תעזוב<sup data-n=\"652\">39</sup>), הקדושה הבאה משמיא — מ\"מ יש מעלה ב\"קב שלו\"<sup data-n=\"650\">38</sup>, מעשה האדם דוקא. והטעם לזה, כי \"למעשה ידיך תכסוף\"<sup data-n=\"654\">40</sup>, שרצונו ותאוותו כביכול של הקב\"ה הוא \"לי בנ\"י עבדים\"<sup data-n=\"655\">41</sup>, לעבודת האדם למטה דוקא, אע\"פ שהיא רק \"קב אחד\".\nוכיון שדוקא בקדושה שבאה ע\"י מעשה האדם יש מעלה נוספת כנ\"ל, לכן יש \"חומר בלקוח בכסף מעשר\" לגבי \"פירות מעשר עצמן\" שהיא הקדושה הבאה משמיא. וזהו נוסף על ה\"חומר\" בעצם הוספת הקדושה ע\"י האדם, שע\"י שעבר ושנה והוסיף קדושה ה\"ז לעי­כובא (דבקדשים \"שנה עליו הכתוב לעכב\"<sup data-n=\"656\">42</sup>).\n[וזהו גופא הטעם לזה ש\"אדם רוצה בקב שלו (עבודה שלו) מתשעה קבים של חברו (הקב\"ה)\" — כי דוקא בזה הוא התאווה שלמעלה<sup data-n=\"657\">43</sup>. ומזה נשתלשל (ע\"ד מלכותא דארעא כעין מלכותא דרקיע<sup data-n=\"658\">44</sup>) בנוגע לחברו בבני אדם].\nז. ובזה יש לבאר יותר את הטעם לזה שבדברי הרמב\"ם (לפירוש הא' שברדב\"ז) מודגש הענין ד\"טפל חמור מן העיקר\" גבי פדיון מע\"ש דוקא — כי זהו גם התוכן שב\"כלל\" ד\"אשכחן בכמה דוכתי דטפל חמור מן העיקר\":\n\"עיקר\" היא הקדושה שמשמיא, ו­\"טפל\" — קדושה שע\"י מעשה האדם. ויומתק זה שנק' \"טפל\" לגבי הקדושה שמשמיא, משום שזה שמעשה האדם מקדש—ה\"ז בא משמיא, (בכח התורה —) תורה מן השמים.\nוזהו מה ש\"אשכחן בכמה דוכתי דטפל חמור מן העיקר\", וע\"ד הענין דחמורים דברי סופרים יותר מדברי",[["649","37","כלים פ\"א מ\"ח."],["650","38","ראה ב\"מ לח, א."],["650","38","ראה ב\"מ לח, א."],["652","39","משלי כז, י. וראה שמו\"ר רפכ\"ז. תנחומא יתרו ה. רש\"י שבת לא, א ד\"ה דעלך."],["650","38","ראה ב\"מ לח, א."],["654","40","איוב יד, טו."],["655","41","ויקרא כה, נה."],["656","42","פסחים סא, א. וש\"נ."],["657","43","ראה בארוכה לקו\"ש שם ע' 335 ואילך."],["658","44","ברכות נח, א. וראה שם הלימוד להלכה שברך ר\"ש ברכה בפועל."]]],[1301550152,"תורה<sup data-n=\"659\">45</sup>, אף שדברי סופרים עצמם באים — נלמדים או נרמזים עכ\"פ — בדברי תורה.\nוי\"ל שבלשון \"טפל חמור מן העיקר\" מרומז גם זה שהחומר וכו' במעשה האדם (טפל) לגבי הקדושה הבאה מ­שמיא (עיקר) — אין זה חומר במעשה האדם מצד עצמו, אלא שבא מן העיקר (משמיא).\n(וע\"ד המבואר בענין ולשון יפה כח הבן מכח האב<sup data-n=\"660\">46</sup>, שגם כח זה בהבן שהוא יפה מכח האב, בא ונמשך \"מכח האב\").\nח. ע\"פ הנ\"ל יש לבאר יותר תוכן החילוק בין שני הפירושים שברדב\"ז (בדין שאין פודין פירות הלקוחים בכסף מע\"ש) — (א) משום דאשכחן דטפל חמור מן העיקר, (ב) משום שנחשב כאילו קנאם בירושלים — די\"ל שהם שני ענינים (ושלבים) בהעילוי שבקדושה הבאה ע\"י מעשה האדם לגבי הקדושה שבאה מ­שמיא:\nלפירוש הראשון, שהלקוח בכסף מע\"ש הוא \"טפל\" לגבי פירות מע\"ש עצמם — נמצא, שהקדושה הבאה ע\"י מעשה האדם היא טפל לגבי הקדושה שמשמיא, שהיא ה\"עיקר\"; אלא שכיון ש\"למעשה ידיך תכסוף\", לכן יש \"חומר\" ומעלה במעשה האדם לגבי הקדושה שמשמיא — טפל חמור מן העיקר.\nמשא\"כ לפירוש השני שברדב\"ז (דפירות הלקוחים בכסף מע\"ש \"הרי זה כאילו קנאם בירושלים\") — אין הלקוח בכסף מע\"ש \"טפל\", אלא אדרבה, יש בו העילוי דגמר ושלימות קדושת מע\"ש, \"הרי זה כאילו קנאם בירושלים\" (ששם מתקדשים הפירות באופן (ע\"ד קדושת הגוף) שאא\"פ לפדותם).\nוזהו שלב שני בהעילוי שב\"מעשה ידיך\" של האדם, שבמעשה האדם גופא יש המעלה ד\"קב שלו\" (הקדושה הבאה ע\"י מעשה האדם), וגם ה\"תשעה קבים של חבירו\", שזוהי שלימות העילוי שב­מעשה האדם, שאין כאן שתי קדושות נפרדות, הקדושה שע\"י מעשה האדם וה­קדושה שמשמיא, אלא הן נעשות קדושה אחת,\nוי\"ל כי זה ש\"למעשה ידיך תכסוף\" הוא מפני דישראל וקוב\"ה הם כולא חד, כביכול<sup data-n=\"661\">47</sup>.\nומטעם זה, גם פעולת ומעשה האדם כשהוא \"בריחוק מקום\", והתלוי' (לכ­אורה) לגמרי בהאדם — \"הרי זה כאילו קנאם בירושלים\", \"יראה שלם\"<sup data-n=\"662\">48</sup>, תכלית שלימות הקדושה.\nויש לומר, שענין זה נרמז בשני הקצוות שבמעשר שני בכלל:\nמחד גיסא \"ממון גבוה הוא שנא'<sup data-n=\"663\">49</sup> לה' הוא (ו)לפיכך אינו נקנה במתנה כו' ואין מקדשין בו את האשה ואין מוכרין אותו כו'\"<sup data-n=\"664\">50</sup>, ומאידך — מצות אכילתו היא לא לכהנים או ללויים וכיו\"ב, כ\"א שהבעלים עצמן אוכלים אותו,\nכי במצות מע\"ש מתאחדים ב' ה­קצוות: הקדושה של גבוה, וזה עצמו — בקדושת דמעשה האדם גופא.\n<span data-k=\"q\">(משיחת ש\"פ ראה תשמ\"ה)</span>",[["659","45","ראה סנהדרין פח, ב (במשנה). וראה גם ירושלמי ברכות פ\"א ה\"ד. וש\"נ."],["660","46","שבועות מח, סע\"א (וש\"נ). וראה המשך שמח תשמח תרנ\"ז ע' 93 (סה\"מ תרנ\"ז ע' רסט) ואילך. ועוד."],["661","47","ראה לקו\"ש חי\"ב ע' 75 ואילך."],["662","48","תוד\"ה הר תענית טז, א. וראה תוד\"ה כי מציון ב\"ב כא, א (מספרי). וראה לקו\"ש חט\"ו ע' 234 בהערות."],["663","49","בחקותי כז, ל."],["664","50","רמב\"ם שם פ\"ג הי\"ז."]]],[1301550153,"<h3>שיחה ב</h3>\nא. עה\"פ<sup data-n=\"665\">1</sup> \"כי פתוח תפתח את ידך לו\" מפרש רש\"י \"פתוח תפתח\" — \"אפילו כמה פעמים\", ולאח\"ז עה\"פ<sup data-n=\"666\">2</sup> \"נתון תתן לו\" פירש — \"אפילו מאה פעמים\"<sup data-n=\"667\">3</sup>.\nוהנה בספרי עה\"פ<sup data-n=\"668\">4</sup> לפנינו נאמר ב­שניהם \"מאה פעמים\"<sup data-n=\"669\">5</sup>: \"ומנין שאם פת­חת פעם אחת אתה פותח אפילו מאה פעמים ת\"ל כי פתוח תפתח את ידך לו. . ומנין שאם נתת לו פעם אחת אתה נותן לו אפילו ק' פעמים ת\"ל נתון תתן\"<sup data-n=\"670\">6</sup>.\nובפשטות י\"ל טעם פרש\"י, פשוטו של מקרא — מקרא הראשון מלמדנו רק \"כמה פעמים\", והפסוק השני \"נתון תתן\" — בא להוסיף \"אפילו מאה פעמים\".\nאבל צע\"ק כי בפש\"מ יש לפרש שב­פסוק הראשון (\"כי פתוח תפתח\") מדבר (בעיקר<sup data-n=\"671\">7</sup>) בחיוב צדקה, ובכתוב השני \"נתון תתן\" קאי (בעיקר) במצות גמ\"ח. כי פסוק זה בא בהמשך למ\"ש<sup data-n=\"672\">8</sup> \"השמר לך פן יהי' דבר עם לבבך בליעל לאמר קרבה שנת השבע שנת השמיטה ורעה עינך באחיך האביון ולא תתן לו גו'\", שבנוגע לשנת השמיטה החשש הוא ב­שייכות לגמ\"ח, כמ\"ש לפנ\"ז<sup data-n=\"673\">9</sup> \"וזה דבר השמיטה שמוט כל בעל משה ידו גו' לא יגוש את רעהו גו'\", וע\"ז ממשיך \"נתון תתן אפילו כמה (מאה) פעמים\" גם ב­גמ\"ח<sup data-n=\"674\">10</sup>.\nועד\"ז מצינו במפרשים<sup data-n=\"675\">11</sup> שכתבו שב' הדרשות בספרי צריכי, \"חד לנותן ב­תורת צדקה וחד למלוה בשעת דחקו, וקמ\"ל שגם המלוה בשעת דחקו צדקה תיחשב לו אע\"פ שחוזר ליפרע ממנו\".\n[יש עוד גירסא<sup data-n=\"676\">12</sup> בספרי: \"ומנין שאם פתחת פעם אחת שסופך לפתוח הרבה פעמים ת\"ל כי פתוח תפתח את ידך לו\"<sup data-n=\"677\">13</sup>, ובפסוק נתון תתן \"אין לי אלא פעם אחת מנין אפילו מאה פעמים ת\"ל",[["665","1","פרשתנו טו, ח."],["666","2","טו, יוד."],["667","3","ושינוי הנ\"ל הוא גם בדפוס ראשון ושני וכת\"י רש\"י (שתח\"י). וכן נעתק בנחלת יעקב ואמרי שפר כאן. ועוד.\nבספר דקדוקי רש\"י (באר רחובות) נעתק מ­פרש\"י עה\"פ פתוח תפתח \"אפילו מאה פעמים\". ואולי הוא משיגרא דלישנא, ולא נחית לדייק בזה."],["668","4","וכן ביל\"ש."],["669","5","ראה אמרי שפר כאן, שביאר פרש\"י זה ע\"ד הרמז (והדרוש). ומסיים \"אבל בספרי ובפרק אלו מציאות אמרו גם גבי פתוח תפתח אפילו מאה פעמים\". וכוונתו למה שנאמר בתחלת הסוגיא שם (לא, א) \"השב אפי' ק' פעמים. . שלח אפי' ק' פעמים. . הוכח אפילו ק' פעמים\", שע\"ז קאי כל סוגית הגמ' שם, שבכ\"מ הפעם הב' מרבה עוד דבר, וכ\"ה גם בנוגע ל\"פתוח תפתח\" ו\"נתון תתן\" (לא, ב)."],["670","6","גם בפס\"ז הוא ע\"ד השינוי הנ\"ל בפרש\"י \"הרבה\", \"מאה\". — בפסוק \"פתוח תפתח\" אי' \"ומנין אפילו הרבה פעמים ת\"ל כו'\", ובפסוק \"נתון תתן לו\" \"אפילו נתת לו מאה פעמים עוד תתן לו כל שבא תן לו\". אבל רש\"י נקט בב' המקומות אותו הלשון ממש רק בשינוי מ\"כמה\" ל\"מאה\"."],["671","7","כי מפורש שם גם \"והעבט תעביטנו\", אם לא רצה במתנה תן לו בהלואה (פרש\"י)."],["672","8","טו, ט."],["673","9","פרשתנו שם, ב."],["674","10","אבל י\"ל דקאי גם על צדקה כפשטות הלשון נתינה, \"נתון תתן\" (וראה חזקוני כאן ט­יו\"ד)."],["675","11","ספרי דבי רב בפסוק יוד."],["676","12","גירסת הגר\"א."],["677","13","ובפסיקתא הובאו שני הענינים בזא\"ז: מלמד שהחובה הוא עליו לפתוח ומנין אפילו הרבה פעמים ת\"ל פתוח תפתח, פתחת פעם אחת סופך פותח הרבה פעמים."]]],[1301550154,"נתון תתן\", היינו ש\"פתוח תפתח\" אינו ציווי אלא הבטחה וברכה, \"שאם פתחת פעם אחת שסופך לפתוח הרבה פע­מים\"<sup data-n=\"678\">14</sup>,\nאף שפשיטא שאין זה פשוטו של מקרא.\nומלשון רש\"י בשני הכתובים \"אפילו כמה פעמים\", \"אפילו מאה פעמים\" מובן שמפרש שניהם לציווי, כפש\"מ].\nב. והנה יש מקום לומר, ע\"פ החילוק בתוכן הכתובים: בפסוק \"פתוח תפתח\" נאמר \"די מחסורו אשר יחסר לו\", דאף ש\"אי אתה מצווה להעשירו\"<sup data-n=\"679\">15</sup> מ\"מ צרי­כים ליתן לו כל \"אשר יחסר לו\", \"אפילו סוס לרכוב עליו ועבד לרוץ לפניו\"<sup data-n=\"680\">16</sup> — ובזה חייבים \"אפילו כמה פעמים\", ואילו בפסוק \"נתון תתן\" איירי רק בנתינה לבד — ובזה החיוב \"אפילו מאה פעמים\".\nויש להוסיף טעם בדין זה — כיון שבפסוק \"פתוח תפתח\" מדובר בנתינה מרובה להשלים כל צרכי העני אין מצווין אותו \"מאה פעמים\", שהרי התורה על הרוב תדבר, ודבר הכתוב בהווה<sup data-n=\"681\">17</sup>, שאין נתינה כזו \"מאה פעמים\" כ\"א רק \"כמה פעמים\", שלא יאמר שכיון שכבר נתן לעני די מחסורו אשר יחסר לו יצא יד\"ח; משא\"כ בכתוב \"נתון תתן\" שאין הדגשה זו ד\"די מחסורו אשר יחסר לו\", מפרש רש\"י \"אפילו מאה פעמים\", כי בנתינה סתם, מתנה מועטת<sup data-n=\"682\">18</sup> שייך שתהי' \"אפילו מאה פעמים\".\nאבל עדיין צריך ביאור, דסו\"ס כיון שחיוב נתינה לעני הוא (כבפסוק הא') \"די מחסורו אשר יחסר לו\", הרי מובן שגם מ\"ש \"נתון תתן\" (שבפסוק שלאח\"ז) כולל חיוב הנתינה לצדקה, שמדובר אודותה בפסוק הקודם<sup data-n=\"683\">19</sup>, באופן של \"די מחסורו אשר יחסר לו\".\nג. ונראה לומר בפשטות, בהקדם ה­דיוק בד\"ה דפרש\"י, שבפסוק הא' מעתיק מהכתוב רק התיבות \"פתוח תפתח\", ו­אילו בפסוק הב' העתיק \"נתון תתן לו\" (אף שהלימוד \"אפילו מאה פעמים\" הוא רק מהתיבות \"נתון תתן\").\nויש לומר הביאור בזה: בכתוב ש­לפנ\"ז<sup data-n=\"684\">20</sup> נאמר \"כי יהי' בך אביון גו' לא תאמץ את לבבך ולא תקפץ את ידך מאחיך האביון\", וע\"ז ממשיך \"כי פתוח תפתח גו'\", והפסוק \"נתון תתן\" בא (כנ\"ל) בהמשך להחשש דהיות ש\"קרבה שנת השבע שנת השמיטה ורעה עינך באחיך האביון ולא תתן לו גו'\".",[["678","14","וביראים (השלם סי' קסז<sup data-n=\"e35\">*</sup>) פי' שניהם לענין ברכה: פתוח תפתח אם פתחת פעם אחת סופך לפתוח ק' פעמים לפי שהקב\"ה מספיק לך וממציא לך מעות נתת פעם אחת סופך לתת ק' פעמים שנאמר נתון תתן. וכ\"פ בעמק הנצי\"ב לספרי שהכוונה בשניהם בתורת הבטחה. וראה תועפת ראם ליראים שם."],["679","15","פרש\"י עה\"פ (מספרי עה\"פ. כתובות סז, ב). — כ\"ה (\"להעשירו\") בדפוסים שלפנינו (ובכמה כת\"י רש\"י שתח\"י), כבספרי. ובדפוס א' וב' ורוב כת\"י רש\"י שתח\"י \"לעשרו\" (כבכתובות שם)."],["680","16","פרש\"י שם (מספרי וכתובות שם)."],["681","17","כהובא בפרש\"י כמה פעמים — בפרשתנו (יג, ז. טו, יט). ולפנ\"ז בפ' משפטים (כא, כח. כב, יז. כא. ל). ועוד."],["682","18","להעיר מב\"מ שם (לא, ב) \"נתון תתן אין לי אלא מתנה מרובה מתנה מועטת מנין (\"אם אי אפשר לך ליתן מתנה מרובה\" — רש\"י שם) ת\"ל נתון תתן\"."],["683","19","והרי רש\"י בפירושו עה\"ת לא הביא הא דב\"מ דלמדין מ\"נתון תתן\" ל\"מתנה מועטת\"."],["684","20","טו, ז."],["e35","*","ביראים הנדפס סי' מח: פתוח תפתח אם פתחת מעט סופך לפתוח מאה פעמים שנאמר פתוח תפתח נתון תתן."]]],[1301550155,"ומזה מובן, שהכתוב \"פתוח תפתח\" (הבא אחר האזהרה דאמוץ הלב וקפיצת הידים) עוסק בפתיחת לבו וידו של ה­נותן, משא\"כ הכתוב \"נתון תתן\" מדבר (בעקרו) בנתינה אל העני והלוה.\nולכן דוקא בפסוק \"נתון תתן\" העתיק רש\"י מהכתוב גם תיבת \"לו\" ולא בפסוק \"פתוח תפתח\", להשמיענו, שכאן עיקר ההדגשה היא על הפעולה ב\"לו\" — במקבל הצדקה.\n[ועפ\"ז מובן בפשטות הא דדוקא בפסוק הב' מפרש רש\"י תיבת \"לו\" — \"בינו ובינך\"<sup data-n=\"685\">21</sup> ולא בפסוק \"פתוח תפתח\" (אף שגם בפסוק הא' אין תיבת \"לו\" מוכרחת, שהי' יכול לומר \"כי פתוח תפתח את ידך והעבט תעביטנו די מחסו­רו אשר יחסר לו\")<sup data-n=\"686\">22</sup> — כי רק בפסוק הב' עיקר ההדגשה הוא על הנתינה להמקבל, ולכן מדייק \"לו\" — \"בינו ובינך\", איך צ\"ל אופן הנתינה בפועל \"לו\", להמקבל; משא\"כ בפסוק \"פתוח תפתח\" שהעיקר הוא (לא הנתינה מהנותן למקבל, אלא) פתיחת לבו וידו של הנו­תן, א\"כ אין לדייק בזה תיבת \"לו\" ביחס לאופן הנתינה (ואולי י\"ל שתיבת \"לו\" כאן פירושה \"בשבילו\", שפותח את לבו בשביל העני)].\nולפי זה יש להוסיף: זה שבפסוק \"נתון תתן לו\" פרש\"י \"אפילו מאה פעמים\", ובפסוק \"פתוח תפתח\" כותב \"אפילו כמה פעמים\":\nבכתוב \"פתוח תפתח\" שעיקר ההד­גשה בהציווי אינה על כמות הנתינה למקבל אלא על פתיחת הלב והידים דהנותן, היינו איכות הנתינה מצד הנותן, אין מקום לפרש \"אפילו מאה פעמים\", כי זה מתאים רק כשהמדובר בנתינה להמקבל, שבזה מדגיש הכתוב שמעשה זה צריך להיות \"אפילו מאה פעמים\", אבל לא כ\"כ כשמדובר בתוכן פתיחת הלב והידים של הנותן.\nאלא דשם קמ\"ל \"אפילו כמה פעמים\", דאף שהכתוב מצוה לנותן הצדקה \"פתוח תפתח\", אין מספיק שיהי' זה רק פעם אחת, בפעם הראשונה שנותן הצדקה, אלא על האדם להשתדל שכל פעולה של צדקה תהי' באופן של \"פתוח תפתח את ידך\", היפך דאימוץ הלב וקפיצת הידים<sup data-n=\"687\">23</sup>.\nד. ויש להוסיף ע\"ד ההלכה.\nהנה יש לחקור: אם נתינת הצדקה מתוך חפץ הלב ובסבר פנים יפות הוא חלק מגוף המצוה דצדקה, משא\"כ ב­פחות מזה, אף שקיים המצוה, הרי זה רק ע\"ד חלק קיום המצוה; או שעיקר מצות",[["685","21","כ\"ה בדפוסים שלפנינו. ובדפוס א' וב' ו(רוב) כת\"י רש\"י שתח\"י \"לבינך\" (ע\"ד ל' הספרי \"בינך לבינו\")."],["686","22","עפ\"ז מובן שאין מספיק מה שתירץ ב­משמרת הקודש לפרש\"י כאן."],["687","23","ובפרט שהדרשות שבשני הכתובים מדובר (גם) באותו יום (ראה אבות דר\"נ פ\"ג, ז. ב\"ר פס\"א, ג. וש\"נ. וראה מפרשים שם)<sup data-n=\"e36\">*</sup>, ולכן קשה לומר דיכול לפעול בעצמו \"פתוח תפתח\", שיתן בחפץ לב כו' \"מאה פעמים\", משא\"כ בהנתינה בפועל."],["e36","*","והא דצריך לימוד מיוחד במדרשים הנ\"ל מהכתוב בקהלת (יא, ו) בבוקר זרע את זרעך ולערב אל תנח ידך, דתתן לעני גם בערבית, והרי כבר נלמד מכתוב בתורה שתתן (אפילו כמה פעמים) אפילו מאה פעמים (לא רק לעוד עני גם בערבית), כי א) שם בא לומר טעם והסברה \"כי אינך יודע כו'\". ב) לפמ\"ש ביפה תואר (השלם) לב\"ר שם, דשם איירי שאין עליו עוד חיוב [אם כבר נתן כפי יכולתו, דקאמר שידחוק א\"ע ויתן גם לשני באותו יום (וראה ראשון לציון שבהערה 32), או בחד עניא דחוזר על הפתחים דאין נזקקים לו למתנה מרובה כו' (וראה נחלת יעקב פסוק יא)], משא\"כ לפי הדרשות שבפרשתנו. ועצ\"ע."]]],[1301550156,"הצדקה הוא הנתינה, ובסבר פנים יפות הוא \"מעלה\" נוספת בהנתינה<sup data-n=\"688\">24</sup>.\nוהנה הרמב\"ם בהל' מתנות עניים, בביאור מצות הצדקה, כ'<sup data-n=\"689\">25</sup> \"מצות עשה ליתן צדקה לעניים כפי מה שראוי לעני אם היתה יד הנותן משגת שנאמר כו'\", והולך ומבאר פרטי הדינים בנתינת ה­צדקה ובפרנסת העניים ואופנם. ואחרי כמה פרקים<sup data-n=\"690\">26</sup> מאריך בביאור גודל מעלת הצדקה, שהיא סימן לצדיק זרע אברהם אבינו<sup data-n=\"691\">27</sup>, ואין אדם מעני מן הצדקה<sup data-n=\"692\">28</sup>, ואשר נתינתה צ\"ל בסבר פנים יפות ובשמחה ומתאונן עמו על צרתו<sup data-n=\"693\">29</sup>, והולך ומונה שמונה מעלות בצדקה<sup data-n=\"694\">30</sup>. ובמעלות אלו גופא — בב' מעלות ה­אחרונות (הפחותות) כ'<sup data-n=\"695\">31</sup> \"פחות מזה שיתן לו פחות מן הראוי בסבר פנים יפות. פחות מזה שיתן לו בעצב\". הרי מפורש שגם זה (נתינה בעצב) מצות צדקה —\nובפרט שהרמב\"ם חילקם לב' פרקים (ובהפסק כמה פרקים), ובפרק הא' כש­מבאר גוף המ\"ע לא הזכיר ע\"ד המעלות באופן נתינתה, אלא כתבן בפרק בפ\"ע — הרי שלדעת הרמב\"ם, ה\"מצות עשה\" היא נתינת צדקה לעניים כפי מה שראוי להעניים, היינו דמעשה הנתינה בפועל לפי צורך העני הוא כל גדר המצוה<sup data-n=\"696\">32</sup>, אבל אופני נתינתה והנתינה בספ\"י הן מעלות (נוספות<sup data-n=\"697\">33</sup>) במצות הצדקה<sup data-n=\"698\">34</sup>, ולכן גם כשנותנה בעצב (מפורש בהרמב\"ם ד)קיים מצות צדקה<sup data-n=\"699\">35</sup>.",[["688","24","להעיר גם מאתוון דאורייתא כלל כג. לקו\"ש חכ\"ד ע' 100.\nבסגנון אחר י\"ל: אם עיקר מצות צדקה הוא בעיקר מעשה הנותן או מצד המקבל (וראה צפע\"נ הל' מת\"ע פ\"י ה\"ד). ולכאורה הנפק\"מ בזה (וראה לקמן הערה 38) אם קיים מצות צדקה כשהעני לא רצה לקבל, דבתשובות הרשב\"א (ח\"א סי\"ח) ו­תשובת ר\"י בן פלט (באבודרהם הל' ברכת המצות. ועוד) כתבו בטעם שאין מברכין על מצות צדקה שמא העני לא ירצה לקבל. ובבית הלל ליו\"ד סי' רמח (הובא ביד אברהם לשו\"ע שם ס\"א) דכשהעני לא רצה לקבל יצא מצות צדקה, וכבמשלוח מנות. אבל להעיר שעד\"ז השקו\"ט במשלוח מנות (ראה רמ\"א בשו\"ע או\"ח סתרצ\"ה ס\"ד. פר\"ח שם. שו\"ת חת\"ס או\"ח סקצ\"ו). ואכ\"מ."],["689","25","רפ\"ז."],["690","26","בפ\"י."],["691","27","ה\"א שם."],["692","28","ה\"ב."],["693","29","ה\"ד."],["694","30","ה\"ז ואילך."],["695","31","הי\"ג וי\"ד."],["696","32","ואף שהרמב\"ם לא הביא לענין מצות הצד­קה הכתוב ד\"נתון תתן\"<sup data-n=\"e37\">*</sup> כ\"א \"פתוח תפתח\" (בספר היד שם רפ\"ז. וכן במנין המצות (בריש ס' היד) ובספר המצות מ\"ע קצה), הרי הרמב\"ם אינו מפרש שהכתוב בא בהמשך ללפנ\"ז בשייכות לספ\"י ונתינה בהרגש הלב. ולהעיר שגם לא הביא דרשת \"אפילו מאה (כמה) פעמים\". וראה ראשון לציון (להאוה\"ח) יו\"ד סרמ\"ז ס\"א, דמחלק כמה פרטים במצות ה­צדקה: הא' דאפילו מבלי תובעים אותו מצוה על האדם להפריש מממונו לצדקה כו', והב' שאחר שעישר נכסיו ונתן המעשר אם יש עניים מדחיקים ביותר ציותה תורה פתח תפתח נתן תתן אפילו מאה פעמים כו' ויש בזה מ\"ע."],["697","33","אבל להעיר מקרית ספר להמבי\"ט לרמב\"ם שם \"שמונה מעלות יש בצדקה זו למעלה מזו וכולן מן התורה כו'\"."],["698","34","ולהעיר שבפ\"י גופא הקדים הרמב\"ם (שם ה\"ד) השלילה \"כל הנותן צדקה לעני בסבר פנים רעות כו'\" לפני החיוב \"אלא נותן לו בסבר פנים יפות ובשמחה כו'\"."],["699","35","\"והיינו שצר לו בנתינתו אבל עכ\"פ אינו מראה לו פנים זועפות דא\"כ לא נחשב בשמונה מעלות דהא הפסיד זכותו\" (ש\"ך יו\"ד סרמ\"ט סק\"ט). ומשמע דס\"ל, דמ\"ש הרמב\"ם שם ה\"ד (ועד\"ז בשו\"ע שם ס\"ג) \"כל הנותן צדקה לעני בסבר פנים רעות ופניו כבושות בקרקע אפילו נתן לו אלף זהובים אבד זכותו והפסידה\", אין זה קיום מצות צדקה. אבל צע\"ג — הרי בפועל החי' נפש העני. וראה ברכ\"י יו\"ד שם. פני דוד להחיד\"א פרשתנו אות י­יב. ואכ\"מ."],["e37","*","ראה שבועות כה, א. וברמב\"ם הל' שמיטה ויובל ספ\"ט — הביא הכתוב לענין הלואה. וראה שו\"ע אדה\"ז (חלק חו\"מ) ריש הל' הלואה."]]],[1301550157,"אבל לפי הנ\"ל בפרש\"י, בהחילוק בין\"פתוח תפתח\" ו\"נתון תתן\", דהכתוב \"כי פתוח תפתח\" בא בהמשך להציווי דצדקה \"לא תאמץ את לבבך ולא תקפוץ את ידך\" (כדפרש\"י<sup data-n=\"700\">36</sup> \"יש לך אדם ש­מצטער אם יתן אם לא יתן. . יש לך אדם שפושט את ידו וקופצה כו'\"), שהנתינה תהי' באופן ד\"פתוח תפתח\", ברצון וחשק הלב, בסבר פנים יפות<sup data-n=\"701\">37</sup>; והכתוב \"נתון תתן\" בא להזהיר ולשלול \"ורעה עינך גו' ולא תתן לו\", היינו מעשה הנתינה בפועל — נמצא דראשית ותחלת הציווי על מצות צדקה \"פתוח תפתח\" הוא (לא רק על עצם הנתינה אלא גם) על נתינתה בחפץ הלב.\nוע\"ז פרש\"י \"אפילו כמה פעמים\", דגם נתינת הצדקה באופן זה צ\"ל כמה פעמים — כי זהו עיקר<sup data-n=\"702\">38</sup> מצות הצדקה<sup data-n=\"703\">39</sup>.\nאלא שאח\"כ מוסיף, דגם באדם<sup data-n=\"704\">40</sup> ש­חסר אצלו חפץ הלב עד שיכול להיות אצלו קס\"ד שלא יתן (\"ורעה עינך באחיך האביון ולא תתן לו\"), אעפ\"כ מצווה התורה \"נתון תתן\", והיינו שלא יחסר (עכ\"פ) בהנתינה בפועל. ועפ\"ז מובן מה שממשיך ומוסיף בהכתוב \"ולא ירע לבבך בתתך לו כי בגלל הדבר הזה יברכך ה\"א בכל מעשיך גו'\" — כי המדובר בסוג נותן צדקה שחסר אצלו כ\"כ בחפץ הלב עד שצריך להבטיחו \"כי בגלל הדבר הזה גו'\", שירוויח ויקבל שכר על זה.\nה. ע\"פ הנ\"ל יש לבאר גם הרמז ב\"יינה של תורה\"<sup data-n=\"705\">41</sup> שבפרש\"י, השינוי בין מ\"ש רש\"י עה\"פ \"פתוח תפתח\" — \"",[["700","36","מספרי עה\"פ."],["701","37","להעיר מאברבנאל כאן."],["702","38","ועפ\"ז יל\"ע אם הא ד\"נפלה סלע מידו ומצאה עני ונתפרנס בה הרי הוא מתברך עלי'\" (ספרי ופרש\"י תצא כד, יט. ועד\"ז הוא בתו\"כ ורש\"י ויקרא ה, יז (בסופו)) — שאין כאן מעשה נתינה כלל — האם הוא קיום מצות צדקה, או פרט במצות שכחה המבוארת שם (ודוחק גדול הוא), רק \"מתברך עלי'\", \"הקב\"ה קובע לו ברכה\" (ל' רש\"י ויקרא שם). וצ\"ע."],["703","39","ע\"פ הנ\"ל י\"ל הנפק\"מ בפועל בין ב' הדיעות: לדעת הרמב\"ם טוב יותר ליתן כראוי גם לא בסבר פנים יפות, שזהו עיקר המצוה<sup data-n=\"e38\">*</sup>, ולדעת רש\"י טוב ליתן פחות מהראוי בסבר פנים יפות מליתן כראוי בלא ספ\"י. אבל ראה מהר\"י קורקוס לרמב\"ם שם פ\"י ה\"ז והי\"ד. צפע\"נ הנ\"ל הערה 24. ועצ\"ע."],["704","40","בספרי בפסוק נתן תתן לו \"בינך לבינו מכאן אמרו (שקלים פ\"ה מ\"ו) לשכת חשאין היתה בירושלים\", ועפ\"ז הי' אפשר לפרש להיפך, שדוקא בפסוק זה מבוארת ומרומזת המעלה הכי נעלית בצדקה, כמ\"ש ברמב\"ם (הל' מתנ\"ע פ\"י ה\"ח)<sup data-n=\"e39\">*</sup>. אבל מזה שרש\"י פי' רק \"בינו ובינך\", ואינו מוסיף \"מכאן אמרו\" שבספרי, אף שהביא בפסוקים אלו כו\"כ דרשות הספרי [ובפרט דלשכת חשאין שהיתה במקדש אינה \"בינו ובינך\", אלא<sup data-n=\"e40\">**</sup> במעלה עליונה יותר, ש\"לא ידע למי נתן ולא ידע העני ממי לקח\" (כמ\"ש הרמב\"ם שם)], מוכח קצת, שלא נחית להביא כאן מעלת הצדקה כמו שהיא באופן נעלה."],["705","41","היום יום ע' כד (כט שבט)."],["e38","*","וראה פרישה לטיו\"ד סרמ\"ט בסופו, שכותב ב' דרגות בנתינה בעצב."],["e39","*","שהרי המעלה גדולה שאין למעלה ממנה מהח' מעלות (ה\"ז שם), \"המחזיק ביד ישראל שמך כו'\", אינה צדקה כפשוטה, כי בעיקרו הוא כאשר בא ע\"י הלואה או ע\"י שותפות כו'. ומעלה הנעלית בצדקה כפשוטה היא מ\"ש בה\"ח (\"שהרי זו מצוה לשמה\"). ע\"ש."],["e40","**","וראה ספרי דבי רב לספרי, דההמשך \"מכאן אמרו\" הוא עוד דרגא."]]],[1301550158,"אפילו כמה פעמים\", ומ\"ש בפסוק \"נתון תתן\" — \"אפילו מאה פעמים\".\nובהקדם הפירוש הפנימי במ\"ש רש\"י<sup data-n=\"706\">42</sup> \"יש לך אדם שמצטער אם יתן אם לא יתן\", דלכאורה הול\"ל \"שמצטער בנתינתו\" וכיו\"ב [וכן בהמשך הלשון<sup data-n=\"706\">42</sup> \"יש לך אדם שפושט את ידו וקופצה\", דגם כאן הול\"ל \"יש לך אדם שקופץ את ידו מליתן\" וכיו\"ב]?\nוי\"ל דכוונת רש\"י כאן לרמז שמדובר בסוג נעלה ביותר בנתינת צדקה, הבא ע\"י בחירה חפשית בתכלית, וזהו \"שמצ­טער אם יתן אם לא יתן\", שנמצא במצב של צער ומלחמה דב' הנפשות, יצר טוב ויצר הרע<sup data-n=\"708\">43</sup>, שהיצ\"ט רוצה ליתן הצדקה והיצה\"ר אינו רוצה שיתן<sup data-n=\"709\">44</sup>, והאדם בוחר בנתינת הצדקה באופן ד\"פתוח תפתח\", פתיחה דכל כחות נפשו, עד שורש נפשו שהיא \"חלק אלקה ממעל ממש\"<sup data-n=\"710\">45</sup>, ש­ממנה הוא אמיתית כח הבחירה שבישר­אל, ד\"הן האדם הי' כאחד ממנו\"<sup data-n=\"711\">46</sup>, ולכן אין מי שמעכב על ידו כמו הקב\"ה שאין מעכב בידו<sup data-n=\"712\">47</sup>.\nוהנה זה שלמדין מ\"פתוח תפתח\" ו\"נ­תון תתן\" — אפילו מאה פעמים, מבואר ברמב\"ם<sup data-n=\"713\">48</sup> ומובא במפרשים כאן<sup data-n=\"714\">49</sup> שהוא לפי שנאמר בלשון של \"מקור\"<sup data-n=\"715\">50</sup> — \"פתוח\", \"נתון\", וה\"מקור<sup data-n=\"716\">51</sup> נופל על ה­מעט וההרבה ולפיכך חייב מצד שהוא מקור כו' אפילו אלף<sup data-n=\"717\">52</sup> פעמים\", ד\"ענין<sup data-n=\"718\">53</sup> המקור — שכולל הרבה עד אין סוף, וזהו \"מאה פעמים\" כי כן דרך הגמרא כאשר תרצה לומר סך אין קץ אמרה מאה פעמים\".\nונת' במ\"א<sup data-n=\"719\">54</sup> הטעם לזה בפנימיות הענינים, כי עשי' מצד עצמה היא במדי­דה והגבלה, וגם כשהעשי' באה מצד כחות נפשו שכלו ומדותיו, שאז עשייתו היא בחיות, מ\"מ הרי היא בהגבלה, לפי שגם שכל ומדות של האדם הן מוגבלים. אבל כאשר העשי' באה מהרצון שבנפש, וכ\"ש וק\"ו כשבאה מצד עצם הנפש שאין בו שום הגבלה — הרי זה פועל גם על כח העשי' שיהי' בלי הגבלות.\nוזהו הטעם שציווי בלשון \"מקור\" מורה \"אפילו מאה פעמים\", כי ציווי סתם ה\"ז קשור בכח המעשה של האדם (שהציווי הוא על עשייתו), משא\"כ כאשר הציווי נאמר בלשון של \"מקור\" פירושו שעשי' זו באה מה\"מקור\", מרצון נפשו שהוא מקור כל הכחות, ולכן היא \"אפילו מאה פעמים\", כי ע\"י עצם הנפש בטלים כל ההגבלות.\nאבל אע\"פ שבכללות \"מאה פעמים\" מורה על העדר ההגבלה, מ\"מ מזה גופא",[["706","42","ועד\"ז בספרי."],["706","42","ועד\"ז בספרי."],["708","43","ראה פרש\"י ואתחנן ו, ה (ממשנה ברכות נד, א)."],["709","44","ראה באר בשדה כאן."],["710","45","תניא רפ\"ב."],["711","46","בראשית ג, כב. וראה רמב\"ם הל' תשובה רפ\"ה."],["712","47","ראה לקו\"ת אמור לח, ב."],["713","48","בפיהמ\"ש (הובא בתוי\"ט) פ\"ב דב\"מ מ\"ט; חולין פי\"ב מ\"ג — בלשונות הכתובים \"השב תשיבם\", \"שלח תשלח. . וזולתם מן המקראות\"."],["714","49","ראה בהנסמן בהערה הבאה."],["715","50","וראה נחלת יעקב על פרש\"י כאן, דמ­פרש\"י כאן \"משמע דמכפל לשון דייק\". ובפרט שרש\"י לא פירש שאר הלשונות שנאמרו בלשון \"מקור\" שהובאו בגמ' שם, דפי' \"אפילו מאה פעמים\". וראה דקדוקי רש\"י (באר רחובות), מלאכת הקודש ובאר בשדה בפרש\"י."],["716","51","פיהמ\"ש חולין שם."],["717","52","כ\"ה (\"אלף\") בפיהמ\"ש להרמב\"ם חולין שם — ובגמ' שם (ובב\"מ) \"מאה\". ולהעיר דבספרי פרשתנו כאן (טו, ח) יש גירסא \"אפילו אלף פעמים\" (ראה ספרי הוצאת האראוויץ­פינקלשטיין)."],["718","53","דקדוקי רש\"י שם."],["719","54","ראה לקו\"ש ח\"ט ע' 140. ועוד."]]],[1301550159,"שאומרים מספר מוגבל \"מאה פעמים\", משמע שיש לזה איזו הגבלה.\n[וכמבואר בלקו\"ת<sup data-n=\"720\">55</sup>, דמספר \"מאה\" מורה על השלימות דהשתלשלות, דה­השתלשלות נחלקת בכללות למספר עשר — עשר ספירות, עשר כחות הנפש וכו', ושלימותן, כאשר כ\"א מהן כלול מעשר, הוא מספר מאה, וכמו שהביא מחדא\"ג מהרש\"א בפירוש מחז\"ל<sup data-n=\"721\">56</sup> \"אינו דומה שונה פרקו מאה פעמים לשונה פרקו מאה ואחד\", ד\"מספר<sup data-n=\"722\">57</sup> מאה מגיע עד נפש רוח ונשמה שהן בחי' יחידות עשירות מאות כו', אבל השונה פ\"א יותר מזה הוא חלק אלקה ממעל\"],\nמשא\"כ הלשון \"כמה פעמים\", שלא נאמר בו מספר מסויים, ה\"ז יכול לכלול הן מעט הן הרבה ונופל על איזה מספר שיהי', וזה רומז גם על העדר הגבלה, למעלה מהשתלשלות.\nוזהו מהחילוקים בין פרש\"י על \"פתוח תפתח\" — \"אפי' כמה פעמים\" לפירושו על \"נתון תתן\" — אפילו מאה פעמים\":\nגם \"נתון תתן\" נאמר בלשון של \"מקור\", כי מעשה המצוה של איש ישראל באיזה מצב שהוא — הרי כפי פסק הרמב\"ם הידוע<sup data-n=\"723\">58</sup>, יש בו ה\"מקור\" — אמיתיות ופנימיות רצונו ש\"רוצה הוא לעשות כל המצות ולהתרחק מן ה­עבירות\" [ובפרט מעשה הצדקה ד\"חייבין אנו להזהר במצות צדקה יותר מכל מצות עשה שהצדקה סימן לצדיק זרע אברהם אבינו כו' ואין כסא ישראל מתכונן ודת האמת עומדת אלא בצדקה שנאמר<sup data-n=\"724\">59</sup> בצדקה תכונני\"<sup data-n=\"725\">60</sup>].\nאבל כיון שאין זה בא וחודר בכחות נפשו עד למעשה, כי בחיצוניות ובגלוי אפשרי אצלו מצב של \"ורעה עינך באחיך האביון גו'\", ויש צורך להודיע לו שהוא לטובתו<sup data-n=\"726\">61</sup> \"בגלל הדבר הזה יברכך ה\"א גו'\" כנ\"ל, ולכן הרמז וה­פעולה שבא מן המקור הוא \"אפילו מאה פעמים\" שהוא מספר מסויים ומוגבל.\nאבל כאשר האדם בוחר בנתינת ה­צדקה מצד מקור נפשו, וזה מאיר אצלו בגלוי — \"פתוח תפתח\" בכל כחות נפשו עד לכח העשי' שלו — מרומז זה בהלשון \"כמה פעמים\" למעליותא — בלי שום הגבלה כלל.\nוע\"י קיום מצות הצדקה, ובפרט בימי חודש אלול שבהם מרבים בצדקה<sup data-n=\"727\">62</sup>, וכמבואר בר\"ת דאלול<sup data-n=\"728\">63</sup> \"איש<sup data-n=\"729\">64</sup> לרעהו ומתנות לאביונים\", וצירוף שם הוי' המאיר בחודש אלול יוצא<sup data-n=\"730\">65</sup> מהס\"ת של הכתוב<sup data-n=\"731\">66</sup> \"וצדקה תהי' לנו כי\"\n— זוכים כל אחד ואחת להכתב ולהחתם בספרן של צדיקים גמורים, עד — לגאולה האמיתית והשלימה<sup data-n=\"732\">67</sup>, ד\"אין<sup data-n=\"725\">60</sup> ישראל נגאלין אלא בצדקה שנאמר<sup data-n=\"734\">68</sup> ציון במשפט תפדה ושבי' בצדקה\" — בקרוב ממש.\n<span data-k=\"q\">(משיחת ש\"פ ראה תשמ\"ג)</span>",[["720","55","פרשתנו כב, ג."],["721","56","חגיגה ט, ב."],["722","57","ל' הלקו\"ת שם."],["723","58","ספ\"ב דהל' גירושין."],["724","59","ישעי' נד, יד — הפטרת פרשתנו."],["725","60","רמב\"ם רפ\"י מהל' מתנות עניים."],["726","61","ראה רש\"י כאן — טו, יא."],["727","62","ראה בארוכה לקמן ע' 89 ואילך."],["728","63","ספר ערוגת הבושם בשם ספר אמרכל."],["729","64","אסתר ט, כב."],["730","65","משנת חסידים מס' אלול פ\"א מ\"א."],["731","66","ואתחנן ו, כה."],["732","67","להעיר מאוה\"ח כאן פסוק ז: ובדרך רמז ירמוז להעיר הערה גדולה כו'."],["725","60","רמב\"ם רפ\"י מהל' מתנות עניים."],["734","68","ישעי' א, כז."]]],[1301550160,"<h3>שיחה א</h3>\nא. המ\"ע דנתינת צדקה מפורשת בפרשתנו<sup data-n=\"735\">1</sup> \"כי יהי' בך אביון גו' לא תאמץ את לבבך גו' פתוח תפתח גו'\" (כמ\"ש הרמב\"ם<sup data-n=\"736\">2</sup> והחינוך<sup data-n=\"737\">3</sup>).\nוע\"פ הידוע<sup data-n=\"738\">4</sup> שכל הפרשיות שבתורה יש להן קשר עם הזמן שבו קורין אותן, מובן, שיש שייכות מיוחדת בין מצות הצדקה לחודש אלול — שהרי לעולם קורין פ' ראה בסמיכות לראש חודש<sup data-n=\"739\">5</sup> אלול (בשבת מברכים החודש אלול, או — כקביעות שנה זו (תשמ\"ח) — בראש חודש אלול), כלומר, שבחודש אלול יש להרבות במצות הצדקה יותר מבשאר ימות השנה.\nויש למצוא מקור לזה מדיוק לשון הרמב\"ם בהלכות תשובה<sup data-n=\"740\">6</sup> — בענין עשרת ימי תשובה — וז\"ל:\n\"אע\"פ שתקיעת שופר בראש השנה גזירת הכתוב רמז יש בו<sup data-n=\"741\">7</sup> כלומר עורו ישינים כו' והטיבו דרכיכם כו' צריך כל אדם שיראה עצמו כו' חציו זכאי כו' עשה מצוה אחת הרי הכריע את עצמו ואת כל העולם כולו לכף זכות וגרם לו ולהם תשועה והצלה כו' ומפני ענין זה נהגו כל בית ישראל להרבות בצדקה ובמעשים טובים ולעסוק במצות מראש השנה ועד יום הכפורים יתר מכל השנה, ונהגו כולם לקום בלילה בעשרה ימים אלו ולהתפלל בבתי כנסיות בדברי תחנונים ובכיבושין עד שיאור היום\".\nומזה שהוציא הרמב\"ם המנהג \"להר­בות בצדקה\" מן הכלל ד\"מעשים טובים ולעסוק במצות\", ועוד זאת, שהקדימו לשאר הענינים, מוכח, דאע\"פ שבימים אלו צ\"ל התחזקות בכל עניני תורה ומצות, הנה לכל לראש צריכים \"להר­בות בצדקה\".\nומזה יש ללמוד מעין זה בענין חודש אלול, כיון שהוא מעין עשרת ימי תשובה בכמה ענינים: (א) אלול הוא חודש התשובה<sup data-n=\"742\">8</sup>, בדוגמת עשרת ימי תשובה, (ב) כמו שעשרה ימים אלו הם הכנה לה\"חתימה\" דיום הכפורים (כ­מבואר במפרשים<sup data-n=\"743\">9</sup>, שזהו הטעם שמרבים בצדקה וכו' בימים אלו, כי \"הבינוני<sup data-n=\"744\">10</sup> תולין אותו עד יום הכפורים אם עשה תשובה נחתם לחיים\") — כמו כן כל",[["735","1","טו, ז ואילך."],["736","2","סהמ\"צ ומנין המצות (בריש ס' היד) מ\"ע קצה. הל' מת\"ע רפ\"ז. ובמנין המצות הביא למקור המצוה רק הכתוב דפרשתנו (טו, ח) \"פתוח תפתח\". וגם בסהמ\"צ ובהל' מתנות עניים זהו פסוק הא' שמביא (ועד\"ז בהל\"ת, הביא בסהמ\"צ, מנין המצות (ל\"ת רלב) והל' מת\"ע (שם ה\"ב) רק הכתוב ד\"לא תאמץ גו'\")."],["737","3","מצוה תעח, תעט."],["738","4","של\"ה חלק תושב\"כ ריש פ' וישב."],["739","5","ראש — שבו כלולים כל ימי החודש והוא מנהיג אותם (לקו\"ת ר\"ה נג, ד. נח, סע\"א. ועוד)."],["740","6","פ\"ג ה\"ד."],["741","7","בו — כ\"ה בדפוסים שראיתי, אבל בכו\"כ כת\"י (והתימנים בתוכם) בה (ראה רמב\"ם ספר המדע — ירושלים, תשכ\"ד)."],["742","8","ראה מהרי\"ל ריש הל' ימים נוראים. ל\"ת להאריז\"ל תצא עה\"פ (כא, יג) ובכתה גו' ירח ימים. טואו\"ח ר\"ס תקפא. לקו\"ת ד\"ה אני לדודי (פרשתנו לב, א ואילך). ועוד."],["743","9","ראה מרכבת המשנה להר\"א אלפנדארי על הרמב\"ם שם. וכמובן מהמשך לשון הרמב\"ם בה\"ג וד'. וראה גם לח\"מ ומל\"מ שם ה\"ד."],["744","10","רמב\"ם שם סוף ה\"ג."]]],[1301550161,"חודש אלול הוא הכנה לה\"כתיבה\" (תחילת הדין) דראש השנה. (ג) ויתירה מזו: כל מ' יום מר\"ח אלול עד אחרי יום הכפורים הם המשך וחפצא אחת של ימי תשובה, כמבואר בב\"ח<sup data-n=\"745\">11</sup> \"מקרא<sup data-n=\"746\">12</sup> אני לדודי ודודי לי ר\"ת אלול וס\"ת עולה מ' כנגד מ' יום מר\"ח אלול ועד יום ה­כפורים כי באלו מ' ימי [יום] התשובה מקובלת כו' דודו קרוב לקבל תשובה מאהבה\",\nדמזה מובן, שע\"ד שבעשי\"ת ישנו ענין מיוחד \"להרבות בצדקה\", כך גם בחודש אלול, שראשית ההתחזקות בעניני תומ\"צ שבחודש זה צ\"ל בענין הצדקה, \"להרבות בצדקה\". וי\"ל שזה נרמז ג\"כ בזה שהצירוף דשם הוי' שמאיר בחודש אלול יוצא<sup data-n=\"747\">13</sup> מס\"ת של \"וצדקה<sup data-n=\"748\">14</sup> תהי' לנו כי\".\nויש להבין: במה שונה מצות צדקה משאר כל עניני תורה ומצות, שלכן ה­התחזקות בחודש אלול (ועשרת ימי תשובה) היא בענין הצדקה דוקא?\nב. לכאורה י\"ל — שזהו משום שנתינת הצדקה מכפרת חטא, וכמ\"ש<sup data-n=\"749\">15</sup> וחטאך בצדקה פרוק, וכמו שהאריך אדה\"ז באגה\"ת<sup data-n=\"750\">16</sup>.\nועפ\"ז יש לבאר דיוק הלשון \"להר­בות בצדקה\", דלכאורה ע\"פ הלכה בצדקה ישנו שיעור<sup data-n=\"751\">17</sup>: חיוב השווה — מעשר, חומש למצוה מן המובחר, אבל לא יותר מזה, וכמ\"ש הרמב\"ם<sup data-n=\"752\">18</sup> \"כל המפזר כו' אל יפזר יותר מחומש\", אלא שכאן כיון שקאי בצדקה שהיא לפדיון הנפש, הרי \"אין לחוש משום אל יבזבז יותר מחומש דלא מקרי בזבוז בכה\"ג מאחר שעושה לפדות נפשו כו'\"<sup data-n=\"753\">19</sup>, וזהו שמדייק הרמב\"ם \"להרבות בצדקה\" ולא קבע שיעור לצדקה זו — כי בצדקה זו אין שיעור<sup data-n=\"754\">20</sup>.\nאבל לכאורה דוחק לפרש כן, שהרי הרמב\"ם מפרט המנהג \"להרבות\" — \"ב­צדקה ובמעשים טובים ולעסוק במצות\", ולא נראה לומר שיש כאן שני ענינים שונים: ריבוי צדקה בתור חלק ממעשה התשובה, וריבוי מע\"ט ומצוות כדי ל­הכריע מאזני הדין לכף זכות, ומסתבר שאינו מבאר כאן אלא בהכרעת מאזני הדין לכף זכות<sup data-n=\"755\">21</sup>. ושגם באותו הסוג דמעשים טובים ועסק המצות שכוונתו להכריע המאזניים לכף זכות יש הדגשה ומעלה בריבוי הצדקה.\nג. ויובן זה בהקדם דיוק הרמב\"ם שם — שכתב אודות מנהג הריבוי בתפלה ותחנונים בלילה בבבא בפ\"ע (\"ונהגו",[["745","11","או\"ח שם סד\"ה והעבירו."],["746","12","שה\"ש ו, ג."],["747","13","משנת חסידים מס' אלול פ\"א מ\"ד."],["748","14","ואתחנן ו, כה."],["749","15","דניאל ד, כד (ושם: וחטיך)."],["750","16","פ\"ג."],["751","17","ראה רמב\"ם סוף הל' ערכין וחרמין (הובא בסמוך). פיה\"מ להרמב\"ם פאה רפ\"א. טושו\"ע יו\"ד ר\"ס רמט."],["752","18","סוף הל' ערכין וחרמין."],["753","19","אגה\"ת שם."],["754","20","ולהעיר מלשון הרמב\"ם לעיל (פ\"ב ה\"ד) \"ועושה צדקה כפי כחו\". אבל שם המדובר ב\"דרכי התשובה\", הנהגת בע\"ת לאחרי שכבר עשה תשובה. ועצ\"ע."],["755","21","ודוחק לפרש שכל סיום הלכה זו \"ומפני ענין זה נהגו כו' להרבות בצדקה ובמעשים טובים כו'\" תוכנו רק ענין התשובה (שמדבר אודותה בסוף ה\"ג לפנ\"ז \"והבינוני תולין אותו עד יום הכפורים אם עשה תשובה נחתם לחיים\") — כי אז הול\"ל (ע\"ד לשון הרמ\"א ואדה\"ז — או\"ח סתר\"ג) \"ויש לכל אדם לחפש ולפשפש (ולמשמש) במעשיו ולשוב מהם בעשי\"ת\"."]]],[1301550162,"כולם לקום בלילה וכו'\") — דלכאורה הול\"ל בבבא אחת, \"להרבות בצדקה וכו' ולקום בלילה וכו'\".\nויש לומר הביאור בזה:\nבכללות קבלת צרכי האדם מהקב\"ה ישנם שני אופנים, וכדאיתא בגמ'<sup data-n=\"756\">22</sup> עה\"פ<sup data-n=\"757\">23</sup> \"שמעו אלי אבירי לב הרחוקים מצדקה\", \"כל העולם כולו נזונין בצדקה והם נזונין בזרוע\": א) \"כל העולם\" מקבלים צרכיהם מהקב\"ה רק בתורת צדקה וחסד השם, ולא בזכות שבידם, כי אינם ראוים לזה מצד מעשיהם, ב) צדיקים \"נזונין בזרוע, בזכות שבידם וקרי להו רחוקים מצדקתו של הקב\"ה\"<sup data-n=\"758\">24</sup>, כי נזונים בזכות מעשיהם הטובים.\nובעבודת ה', שני אופנים אלו הם (בכללות) בהתאם להחילוק בין תפלה ועסק התורה ומצוות: ענין התפלה הוא בקשה ותחנון, \"תחנונים ידבר רש\"<sup data-n=\"759\">25</sup>, שהקב\"ה ירחם עליו וימלא משאלותיו אף שאינו ראוי לכך, ובלשון חז\"ל<sup data-n=\"760\">26</sup> \"מתנת חנם\"; אבל על ידי עסק התורה ומצות מקבל האדם את צרכיו (לא בתור צדקה, אלא) ע\"פ דין, כמו שהובטחנו בתורה<sup data-n=\"761\">27</sup> \"אם בחוקותי תלכו ואת מצותי תשמרו גו' ונתתי גשמיכם בעתם גו'\"<sup data-n=\"762\">28</sup>.\nועפ\"ז, כשהקב\"ה דן את האדם, ו\"שוקלין זכיות האדם ועונותיו\"<sup data-n=\"763\">29</sup>, הרי הדעת נותנת שכשדנים אותו לזכות אין זה מפני רחמים וצדקה, אלא לפי מצבו<sup data-n=\"764\">30</sup>.\nולכן הוי אמינא, שבעשרת ימי תשובה צ\"ל עיקר ההדגשה על הוספה במצוות ומע\"ט כדי לזכות בדין, ואין מקום לבקשת רחמים, שיהי' \"בצדקה\", לפנים משורת הדין.\n[ואע\"פ שבענין תפלה מצינו ש\"אע\"פ שיש להם לצדיקים לתלות במעשיהם הטובים אין מבקשים מאת המקום אלא מתנת חנם\"<sup data-n=\"765\">31</sup> — זה מתאים רק בנוגע לתפלה ובקשה, שאין צריכים לתבוע מאת הקב\"ה כ\"א לבקש מאתו ית'<sup data-n=\"766\">32</sup>, בדרך מתנת חנם (אף שיכולים לתלות במעשיהם הטובים)<sup data-n=\"767\">33</sup>. משא\"כ כשהמדובר בדין, שהקב\"ה שוקל זכיות האדם כו' ושופט אותו ע\"פ מעשיו, אין מקום לערב בזה בקשת רחמים וצדקה כו'<sup data-n=\"768\">34</sup>].",[["756","22","ברכות יז, ריש ע\"ב."],["757","23","ישעי' מו, יב."],["758","24","פרש\"י שם ד\"ה והם נזונין."],["759","25","משלי יח, כג."],["760","26","ספרי ודב\"ר ר\"פ ואתחנן. פרש\"י שם."],["761","27","ר\"פ בחוקותי."],["762","28","ולהעיר מביאור הרמב\"ם בהל' תשובה (פ\"ט) ע\"ד היעודים גשמיים שבתורה."],["763","29","ל' הרמב\"ם שם פ\"ג ה\"ג."],["764","30","ואף שכללות ענין התשובה הוא מרחמיו וחסדיו של הקב\"ה ולא משורת הדין (ראה חבור התשובה להמאירי מאמר א' פ\"א (ובפירושו לאבות פ\"ג מי\"ח). עיקרים מ\"ד פכ\"ה. וכמו שאומרים כמ\"פ בסליחות, ופשיטא בשייכות להתשובה בכל שנה ושנה — ראה אגה\"ת פי\"א) — הרי נת\"ל שבהלכה זו, שהרמב\"ם כותב \"ומפני ענין זה נהגו כל בית ישראל להרבות כו'\" כהמשך ישר ל\"יראה עצמו. . חציו זכאי כו'\" משמע שכאן אין המדובר (רק על ענין התשובה), אלא על הדין והמשפט, והוא מכריע א\"ע (ממצב של שקול) לכף זכות."],["765","31","ל' רש\"י ר\"פ ואתחנן. וראה ספרי ודב\"ר שם. וראה בהנסמן בהערה 33."],["766","32","וראה שו\"ע אדה\"ז או\"ח סצ\"ח ס\"ה."],["767","33","ראה בארוכה לקו\"ש חכ\"ד ע' 29 ואילך."],["768","34","דמטעם זה אומרים בעשרה ימים אלו המלך הקדוש ולא הא­ל הקדוש, המלך המשפט ולא מלך אוהב צדקה ומשפט, \"לפי שבימים הללו הקב\"ה מראה מלכותו לשפוט את העולם\" (שו\"ע אדה\"ז או\"ח סתקפ\"ב ס\"א, מרש\"י ברכות יב, ריש ע\"ב). ואם אמר מלך אוהב צדקה ומשפט במקום המלך המשפט ונזכר לאחר שסיים תפלתו י\"א דחוזר לראש התפלה \"משום דיש הפרש בין מלך אוהב צדקה ומשפט להמלך המשפט דבכל השנה הצדקה עיקר ולכך הקדימוהו למשפט אבל בימים הללו המשפט עיקר ולכך אין מזכירין צדקה כלל\" (שו\"ע אדה\"ז שם ס\"ב, מט\"ז או\"ח סקי\"ח סק\"ב)."]]],[1301550163,"וקמ\"ל הרמב\"ם, שנוסף על המנהג להרבות בעניני זכות (צדקה ומע\"ט ו­מצוות) נהגו ישראל גם \"לקום בלילה. . ולהתפלל. . בדברי תחנונים. . עד ש­יאור היום\"<sup data-n=\"769\">35</sup>. וי\"ל שזה גופא שזוכים בדין ע\"פ שורת הדין הוה בגדר \"צדקה\" מלמעלה, לפי שאין מעשה בני אדם (הנבראים) תופסים מקום אצלו ית' (כמש\"נ<sup data-n=\"770\">36</sup> \"אם צדקת מה תתן לו גו'\"), ועוד זאת, שגם עשיית מעשים טובים (על ידי האדם) היא בכוחו של הקב\"ה, כמש\"נ<sup data-n=\"771\">37</sup> \"מי הקדימני ואשלם גו'\"<sup data-n=\"772\">38</sup>. ולכן זה גופא שהקב\"ה (משפיל את עצמו כביכול ו)דן את האדם ומחשיב את מעשיו הטובים לזכותו משום כך בדין, ה\"ז חסד וצדקה מאתו ית' וצריך ע\"ז תחנונים כו'.\nולכן חילק הרמב\"ם מנהגים אלו בב' בבות, כי הם שני ענינים נפרדים ב­פעולתם של ישראל לזכות בדין: בבא הא' הם הדברים שבנ\"י עושים כדי להכריע כף המאזניים, ובבא הב' — התפלה ותחנונים, כי בשביל זה גופא שדברים אלו יכריעו לכף זכות זקוקים לרחמי הקב\"ה כנ\"ל.\n[ויש לומר, שזהו גם הטעם לשינוי הלשון בשתי הבבות — בבבא הא' \"נהגו כל בית ישראל\", ובבבא הב' \"נהגו כולם\" — דמשמע קצת, דענין הב' מה שנהגו לקום כו' היא הנהגה פשוטה לכולם, יותר מענין הא'<sup data-n=\"773\">39</sup>. וע\"פ הנ\"ל מובן, כי בקשת רחמים הוא שייך לכאו\"א מישראל, גם אלה שלא הוסיפו (כ\"כ) במצות ומעשים טובים (שלא היו יכולים להוסיף וכיו\"ב), ולאידך גם אלה שהוסיפו במצות ומעשים טובים יתר מכל השנה נוהגים להוסיף בבקשת רחמים (\"דברי תחנונים\"), כי גם הם צריכים לידע ולהרגיש שזכותם בדין היא בגדר צדקתו של הקב\"ה, שצריכים לבקשות ותחנונים על זה].\nובזה יש לבאר גם מה שהוציא הרמב\"ם בבבא הא' \"ולהרבות בצדקה\" מן הכלל, והקדימו לשאר הענינים — כי בריבוי הצדקה מודגש ג\"כ שהאדם מרגיש שצריך לזכות בדין רק מחמת צדקתו של הקב\"ה, שלכן מרבה בצדקה כדי שהקב\"ה יתנהג עמו ג\"כ באופן של צדקה מדה כנגד מדה. כלומר, זה שהאדם מרגיש שכל מה שזוכה מלמעלה הוי בגדר צדקה ומתנת חנם צריך להתבטא לא רק בתפלתו, אלא גם ב­מעשיו שכוונתם הטיית כף המאזניים של הדין לטובה ע\"פ הדין, גם בהם צריך להדגיש שזהו לפנים משורת הדין כלפי מעלה.\nד. ביאור השייכות ד\"צדקה\" לה­משפט דר\"ה בעומק יותר (וע\"פ פנימיות הענינים):\nבהגדרת מהות העבודה של ראש השנה ארז\"ל<sup data-n=\"774\">40</sup> שאמר הקב\"ה \"אמרו לפני",[["769","35","דדוחק לומר שכוונתו בזה (רק) לענין התשובה והצעקה (ראה רמב\"ם לעיל פ\"ב ה\"ו. ובמגדל עוז כאן) או וידוי ובקשת מחילה דא\"כ הו\"ל להקדימו תחילה, לפני זה ש\"נהגו כל בית ישראל להרבות בצדקה ובמעשים טובים כו'\"."],["770","36","איוב לה, ז."],["771","37","איוב מא, ג. ויק\"ר פכ\"ז, ב."],["772","38","דכללות הענין דבאתעדל\"ת אתעדל\"ע הוא רק מפני שכן עלה ברצונו ית' (לקו\"ת שמע\"צ פג, ב. שה\"ש יב, א. ועוד. וראה בארוכה המשך ר\"ה תש\"ג פ\"ו ואילך. לקו\"ש חכ\"ד שם. וש\"נ)."],["773","39","אף שאולי יש לומר שכאן מקצר בלשונו וכ' \"ונהגו כולם\", היינו \"כל בית ישראל\"."],["774","40","ר\"ה טז, א. לד, ב."]]],[1301550164,"בר\"ה מלכיות זכרונות ושופרות, מלכיות כדי שתמליכוני עליכם, זכרונות כדי שיעלה זכרוניכם לפני לטובה, ובמה בשופר\".\nועל פי זה נת' בכ\"מ, שעיקר עבודת ראש השנה היא הכתרת הקב\"ה למלך על ישראל (\"שתמליכוני עליכם\")<sup data-n=\"775\">41</sup>, ועי\"ז למלך על העולם כולו.\nואין זה סתירה להמפורש שר\"ה ויוהכ\"פ הם ימי הדין, כי תרווייהו איתנהו בי': מצד הקב\"ה, אמיתית תוכנם של ימים אלה הוא שמכתירים אותו למלך, דבר הנוגע בעיקר (כביכול) להקב\"ה, וכהלשון \"אמרו לפני כו' כדי שתמליכוני עליכם\", שהקב\"ה מבקש זה מבנ\"י, כי זהו דבר הנוגע לו; ומצד הנבראים, וכפי שהקב\"ה כביכול השפיל את עצמו להיות יושב ודן כל באי ה­עולם, הרי הם ימי דין ומשפט ששוקלין זכיות האדם ועונותיו.\nולפי זה י\"ל דזה שצריך להיות ריבוי במע\"ט וכו' הוא מצד הענין הב' שבימים אלה, אבל מצד הקב\"ה עצמו, כמו שהוא למעלה מלהיות מלך על עם, הרי אין מקום בכלל לדין ומשפט של העם, שזהו דוקא כאשר יושב על כסא מלכותו ודן את העם. ובכדי לפעול ענין זה שהקב\"ה ישפיל עצמו להיות מלך על עם, ה\"ז על ידי שנרגש אצל העם ביטולם השלם, שגם כאשר מצד \"חשבון\" הזכיות וה­עונות האדם הוא צדיק וזוכה בדין (ופשיטא שעשה תשובה כדבעי), מ\"מ הרי הוא מתפלל בתחנונים, ויתירה מזו, הוא מרבה בצדקה, בכדי לזכות לצדקתו של הקב\"ה — שזה מביא \"שתמליכוני עליכם\"<sup data-n=\"776\">42</sup>.\nה. כשם שהוא בהדגשה וב\"היכל המלך\"<sup data-n=\"777\">43</sup> בעשרת ימי תשובה, עד\"ז הוא בזעיר אנפין (ב\"שדה\"<sup data-n=\"777\">43</sup>) גם בהעבודה ד­חודש הרחמים והסליחות — חודש אלול, שגם בו ישנם ב' ענינים אלו:\nמצד אחד הרי הוא חודש הרחמים והסליחות עד ש\"יש מי שמרבין לומר סליחות ותחנונים מר\"ח אלול ואילך\"<sup data-n=\"779\">44</sup> (בדוגמת דברי הרמב\"ם לעשרת ימי תשובה), ומאידך גיסא זה נוגע לזכות בדין. וכמודגש בלשון הטור<sup data-n=\"780\">45</sup> \"וכל המוסיף לבקש רחמים זכות הוא לו\", דלכאורה ה\"ז תרתי דסתרי, דבקשת רחמים תוכנה שאף שאין לו זכיות מבקש שהקב\"ה ירחם עליו, שהוא ההיפך ד\"זכות הוא לו\". אלא שהדרך לזכות בימים אלו היא על ידי שנרגש אצלו שתמיד זקוק לבקש רחמים מאת הקב\"ה שיתן לו צדקה ומתנת חנם.\nוכן לאידך גיסא, שגם בזה שמוסיפים בהעבודה דתשובה ומע\"ט [כמשנ\"ת כמ\"פ<sup data-n=\"781\">46</sup> הרמז לזה — שבר\"ת ד\"אלול\"",[["775","41","ראה רס\"ג (הובא באבודרהם) שענין ה­ראשון במצות תק\"ש הוא \"שאנו ממליכים עלינו את הבורא\". וראה לקו\"ש ח\"ד (ע' 1146 ואילך. ע' 1354 ואילך. וש\"נ). ובכ\"מ."],["776","42","וי\"ל שזוהי השייכות לתחילת ההלכה (ד') ברמב\"ם שכ' \"אע\"פ שתק\"ש בר\"ה גזירת הכתוב רמז יש בו כו'\" — ענין התשובה, שמה שהקדים הרמב\"ם \"גזירת הכתוב\", ענין שלמעלה מטעם, הוא לפי שאמיתית ענין תק\"ש הוא הענין דתמליכוני עליכם, השייך ל\"נתאווה הקב\"ה\", שלמעלה מטעם (כמשנ\"ת במ\"א — ראה לקו\"ש חי\"ד ע' 124)."],["777","43","ראה לקו\"ת פרשתנו ד\"ה אני לדודי (לב, ב ואילך) — נת' בלקו\"ש ח\"ד ס\"ע 1342 ואילך. ועוד."],["777","43","ראה לקו\"ת פרשתנו ד\"ה אני לדודי (לב, ב ואילך) — נת' בלקו\"ש ח\"ד ס\"ע 1342 ואילך. ועוד."],["779","44","ל' הטור או\"ח ר\"ס תקפא. וראה גם חבור התשובה להמאירי (מאמר ב' פ\"א). אבודרהם בסדר תפלת ר\"ה. ועוד."],["780","45","או\"ח שם."],["781","46","ראה לקו\"ש ח\"ב ע' 396. ח\"ט ע' 299. ובכ\"מ."]]],[1301550165,"נרמזים כל שלשת העמודים דתורה עבודה וגמ\"ח, וכן עבודת התשובה וענין הגאולה] — בזה גופא צריכה להיות ההקדמה דלהרבות בצדקה, כמרומז (כנ\"ל ס\"א) בהצירוף דשם הוי' של חודש אלול, היוצא מס\"ת \"וצדקה תהי' לנו כי\".\nועל ידי הנהגה זו, זוכה כל אחד להכתב ולהחתם בספרן של צדיקים גמורים, ועד שלפני ר\"ה יודעים שהם זוכים בדין — לכתיבה וחתימה טובה ל­שנה טובה ומתוקה בטוב הנראה והנגלה.\n<span data-k=\"q\">(משיחת ו' תשרי תשל\"ח)</span>"],[1301550166,"<h3>שיחה א</h3>\nא. בנוגע לתקיעת שופר בחודש אלול הורה כ\"ק מו\"ח אדמו\"ר (כפי שנדפס ב\"היום יום\"), \"שבמשך היום (א' דר\"ח) תוקעים להתלמד, ומתחילים לתקוע אחר התפלה מיום ב' דר\"ח\"<sup data-n=\"782\">1</sup>. ולכאורה צ\"ב מאי האי ד\"תוקעים להתלמד\" במשך יום א' דר\"ח, דלכאורה בכל אופן אינו מובן: אם אינו יודע לתקוע פשיטא שצריך להתלמד (ומאי קמ\"ל) ואח\"כ גם יתקע באותו היום; ובאם יודע מכבר — שוב אין צורך לתקוע (ביום א' דר\"ח כדי) \"להתלמד\"? בפשטות י\"ל, שכוונת כ\"ק מו\"ח אדמו\"ר היא להכריע בין הדיעות מתי מתחילים התקיעות דאלול — אם בא' דר\"ח אלול (ל' מנחם אב) או ביום ב' דר\"ח (א' אלול)<sup data-n=\"782\">1</sup> — ובזה ההכרעה, שהחיוב דתקיעות דאלול מתחיל מב' דר\"ח, אלא שכדי לצאת ידי האומרים שמתחילים מא' דר\"ח, \"תוקעים להת­למד\", היינו שתוקעים, אבל לא בתור חיוב, אלא רק להתלמד בלבד. אבל צריך ביאור הלשון \"תוקעין להתלמד\", ולא בפשטות — תוקעין ולא תקיעה של מנהג, חובה וכיו\"ב. ולכן נראה, שיש ענין מיוחד בתקיעה שהיא \"להתלמד\" בלבד, ותקיעה זו שייכת ליום א' דר\"ח אלול, כדלקמן. ב. והנה ע\"פ משנת\"ל בהסברת ההנהגה ד\"תוקעין להתלמד\" — יש לחקור בקביעות דא' ר\"ח אלול שחל בשבת (כמו בשנה זו<sup data-n=\"e2\">*</sup>), שא\"א לתקוע: את\"ל שהמנהג לתקוע להתלמד הוא בתור הכשר להתקיעות הבאות אח\"כ (מיום ב' דר\"ח) — הסברא נותנת, שבקביעות כזו, מתלמדים בערב ר\"ח; אבל ע\"פ משנת\"ל ש(עיקר) הכוונה דהתקיעה של יום זה (א' דר\"ח), היא לצאת ידי הדיעות שזהו זמן התחלת התקיעות דאלול (כי אז הוא התחלת המ' יום האחרונים שעלה משה להר)<sup data-n=\"784\">2</sup>, הרי אין ענין לתקיעה זו בערב ר\"ח אלול. ועפ\"ז בקביעות כזו — חסרה ההתחלה ד\"תוקעין להתלמד\". אבל בפשטות י\"ל שאין בזה חסרון — כי הוא כמו כל שבת שבחודש אלול, שאין בו כל תקיעה. ובפנימיות הענין, מובן הוא ע\"פ ביאור רבינו הזקן<sup data-n=\"785\">3</sup> בהא שאין תוקעים בראש השנה שחל להיות בשבת, שהטעם הפנימי לכך הוא, מפני שביום השבת אין צורך בתקיעת שופר (במדינה), כי מה שפועלים על ידי תקיעת שופר, נפעל בדרך ממילא על ידי השבת עצמה (שהיא מיקדשא ו­קיימא); והוא הדין בנדו\"ד, התקיעות דחודש אלול, דמה שהתקיעות היו צריכות לפעול בשבת זו, נפעל בדרך ממילא על ידי השבת עצמה.",[["782","1","הדיעות בזה ראה נו\"כ הטושו\"ע או\"ח סתקפ\"א."],["782","1","הדיעות בזה ראה נו\"כ הטושו\"ע או\"ח סתקפ\"א."],["784","2","ראה מ\"א שם סק\"ב. ובארוכה — בהשלמת הר\"נ מדובראוונא לשו\"ע אדה\"ז סתקפ\"א (בקו\"א)."],["785","3","ד\"ה להבין המשנה. . יו\"ט של ר\"ה בלקו\"ת דרושי ר\"ה (נו, א ואילך); סידור שער התקיעות (רמ, ג ואילך). ובכמה דרושי רבותינו נשיאינו."],["e2","*","תשמ\"ח — שנת הדפסת השיחה. המו\"ל."]]],[1301550167,"והטעם בפשטות: התקיעות דחודש אלול באות להזהיר את העם לעשיית תשובה<sup data-n=\"786\">4</sup>, והרי ארז\"ל דשבת אותיות תש\"ב<sup data-n=\"787\">5</sup>, והיינו שעצם יום השבת מביא האדם לידי תשובה [אלא שהתשובה דיום השבת היא מדריגה נעלית ביותר, \"תשובה עילאה\", שלמעלה מהזכרת עונות כו', כמשנ\"ת בארוכה באגרת התשובה<sup data-n=\"788\">6</sup> ובכ\"מ]. אבל ע\"פ הנ\"ל (סוף סעיף א') אין גלאַטיק (חלק) לבאר כן בנוגע להתקיעה דא' דר\"ח אלול — כי אין הטעם לתקיעה זו<sup data-n=\"789\">7</sup> כדי להזהיר לתשובה, אלא, כמפורש בלשון כ\"ק מו\"ח אדמו\"ר — כדי \"להתלמד\", ואיך יתכן לומר, שהשבת (מצד עצמה) פועלת ה\"להתלמד\"? ג. ויש לומר הביאור בזה, בהקדם ביאור רבינו הזקן<sup data-n=\"790\">8</sup> בהמנהג שתוקעים ביום הכפורים אחר נעילה תקיעה אחת — שתקיעה זו היא ע\"ד התקיעה ב\"שופר גדול\" דלעת\"ל, דתקיעות דר\"ה (שהם מאה קולות, ובכמה מיני קולות, תקיעה שברים תרועה) הן \"שופר\" סתם, אבל התקיעה הגדולה שתוקעים בסיום וחותם הימים נוראים, לאחרי תפילת נעילה דיוהכ\"פ, שהיא תקיעה אחת פשוטה, הרי היא תכלית העילוי דתק\"ש — מעין ה\"תקיעה גדולה\" דלעת\"ל. ביאור הדבר: מבואר בכ\"מ<sup data-n=\"791\">9</sup> שתוכנה הפנימי של תקיעה בשופר הוא — קלא פנימאה של הנשמה, שהיא צעקה פנימית ו\"פשוטה\", \"קול פשוט\" דוקא. [וזהו הביאור (הפנימי) בההלכה<sup data-n=\"792\">10</sup> \"כל הקולות כשרים בשופר\" — כי עיקר ענין השופר הוא קול פשוט דוקא, ולכן אין נוגע \"ציור\" הקול, אלא עצם קול השופר]. וזהו ענין ה\"תקיעה אחת\" שתוקעים לאחרי תפילת נעילה, שהיא תקיעה אחת פשוטה, כי ענינה הצעקה הפנימית מעצם הנשמה שהיא למעלה מכל ענין של \"ציור\", אפילו מה\"ציור\" שבתשר\"ת דר\"ה שגם זה נק' קול פשוט לגבי קולות של כלי נגינה<sup data-n=\"793\">11</sup> [אלא שכדי להגיע לקול פשוט זה דיוהכ\"פ, צריכים להקדים תקיעת מאה קולות דר\"ה, ועי\"ז באים אח\"כ לתכלית העילוי בשופר, תקיעה אחת שבנעילת יוהכ\"פ]. ד. והנה ע\"פ הידוע בענין \"כלל ופרט וכלל\", דכשם שישנו ה\"כלל\" שבא לאחרי הפרטים, כך ישנו ה\"כלל\" שבא לפני וכהקדמה להפרטים, כן הוא גם בעניננו, שכשם שלאחרי פרטי מאה הקו­לות דר\"ה באים לה\"כלל\" ותוכנו הכללי של שופר — תקיעה אחת פשוטה (קול פשוט דוקא) של נעילת יום הכפורים, הנה עד\"ז הוא בהתחלת מ' הימים<sup data-n=\"794\">12</sup>,",[["786","4","רא\"ש ר\"ה (בסופה), ראבי\"ה שם (סתקמ\"ב) וטור ר\"ס תקפא — בשם פדר\"א (פמ\"ו. וראה הגהות הרד\"ל שם סק\"כ)."],["787","5","אגה\"ת פ\"י."],["788","6","שם. וראה לקו\"ש חי\"ד ע' 146."],["789","7","אף שבכלל כל תקיעה מעוררת לתשובה וכמש\"נ (עמוס ג, ו) אם יתקע גו' ועם לא יחרדו."],["790","8","לקו\"ת ר\"ה ס, ג."],["791","9","ראה משל הבעש\"ט בהמשך וככה תרל\"ז פ\"ע (הובא ונת' לקמן ע' 183 ואילך). וראה דרושי ר\"ה בלקו\"ת, סידור (שער התקיעות), אוה\"ת, וב­דרושי רבותינו נשיאינו שלאח\"ז."],["792","10","ר\"ה כז, ב. רמב\"ם הל' שופר פ\"א ה\"ז. טושו\"ע (ודאדה\"ז) סתקפ\"ו ס\"ו (סי\"ח)."],["793","11","ראה סידור שם רמב, ב."],["794","12","להעיר מרוקח סק\"ח שתוקעין כל מ' יום מר\"ח אלול עד יוהכ\"פ, ולכמה דיעות (ע\"פ פדר\"א שם) שתוקעין (רק) בר\"ח אלול ובמוצאי יו\"כ (שבלי הלקט סוף הל' יו\"כ סשכ\"ב. ועוד) — הובאו ברד\"ל לפדר\"א שם (אות יח)."]]],[1301550168,"שקודם העבודה בפרטי ענין תקיעת שופר (גם דחודש אלול, שתוקעים י' קולות<sup data-n=\"795\">13</sup>) — צ\"ל נקודת ההתחלה, ה\"כלל\" שלפני הפרטים, שבו מודגש תוכנם הכללי של הפרטים הבאים אח\"כ<sup data-n=\"796\">14</sup>. דיש לומר שזהו ש\"תוקעין להתלמד\" — שזהו בדוגמת וע\"ד התקיעה אחת שתוקעים בסיום הארבעים יום, וכפי שרואים בפשטות, דכאשר מתחילים לתקוע כדי להתלמד, הרי התחלת ההת­למדות היא, שיוצא קול פשוט (ואח\"כ לומדים פרטי הקולות, דתקיעה שברים תרועה) — כי היא נקודת ענין של \"כל הקולות\" דשופר, הקול פשוט שלמעלה מהמאה קולות דר\"ה. ה. וע\"פ הנ\"ל, שאין הכוונה ב­\"תוקעין להתלמד\" רק ההתלמדות כיצד לתקוע כפשוטו (שזה יכולים לעשות גם לפני א' דר\"ח אלול), אלא בעיקר — התחלת הענין דצעקת הנשמה, קול פשוט — יובן גם בנוגע לקביעות כזו שא' דר\"ח אלול חל בשבת, דאע\"פ שא\"א לתקוע כפשוטו, מ\"מ, תוכן הענין ד\"תוקעין להתלמד\" יכולים ולכן גם צריכים גם ביום השבת, ו­כאשר האדם עובד עבודתו בהתאם לתוכן הפנימי דיום השבת, שבת אותיות תש\"ב, שהיא תשובה עילאה כנ\"ל, הרי מגיע לקול פשוט, מעצם נשמתו. אבל באם ידע בנפשו שמאיזה סיבה שתהי' לא עבד עבודה זו בשבת זו — צריך לעשותה כנ\"ל. ויש לומר, דכאשר חל א' דר\"ח אלול ביום השבת, הרי כשם ששבת אהני לענין ר\"ח<sup data-n=\"797\">15</sup>, כן הוא לאידך, שסגולת היום דא' ר\"ח אלול (היום שעלה משה להר, לדיעה זו שמתחילין לתקוע בא' דר\"ח אלול) \"אהני\", שהתשובה עילאה דיום השבת (בכלל) תהי' באופן נעלה יותר, עד לצעקה פנימית מעצם נשמתו, עד מעין ה\"שופר גדול\" דלעתיד לבא.\n<span data-k=\"q\">(משיחת א' דר\"ח אלול תשמ\"ב)</span>",[["795","13","ב\"ח או\"ח סתקצ\"ב (ע\"פ הערוך). וכ\"ה מנהג חב\"ד. ועוד."],["796","14","ועד\"ז הוא במשך כל היום: כלל — מודה אני כו' שהיא הודאה פשוטה; אח\"כ עבודה במשך היום בתפלה ותורה — עבודה פרטית; ולאח\"ז בסוף היום הכלל שלאחרי עבודה הפרטית — ק\"ש שעל המטה, וחותמה \"בידך אפקיד רוחי\". ואף שבגלוי כלל הראשון הוא הודאה כללית דאפשר לאמרה גם קודם נט\"י בידים טמאות כו' (ראה שו\"ע אדה\"ז או\"ח ס\"א ס\"ה (ובמהד\"ב — שם ס\"ו. סידור אדה\"ז בתחלתו)) — הרי ידוע הטעם לזה בפנימיות הענינים, לפי שהוא שייך להכלל שלמעלה מפרטים, שאין טומאה יכולה להגיע לשם (ראה \"היום יום\" יא שבט. ונת' בקונטרס ענינה של תורת החסידות סי\"א ואילך)."],["797","15","ראה זבחים צא, א."]]],[1301550169,"<h3>שיחה א</h3>\nא. בפרש\"י ריש פרשתנו: שופטים ושוטרים שופטים דיינים הפוסקים את הדין, ושוטרים<sup data-n=\"798\">1</sup> הרודין את העם אחר מצותן<sup data-n=\"799\">2</sup> שמכין וכופתין במקל וברצועה עד שיקבל עליו את דין השופט.\nוכתבו במפרשים<sup data-n=\"800\">3</sup>, ד\"מה שהוסיף [רש\"י, ששופטים הם דיינים] הפוסקים את הדין אע\"ג דידוע שכל דיין פוסק את הדין כדי לבאר לך למה הוצרך לומר עוד שוטרים ולפיכך פירש שזה הדיין אינו עושה רק פסק הדין ותו לא דאינו כופה אותו, ושוטר הוא שכופה ורודהו לקיים מצות השופט\".\nאבל צ\"ב<sup data-n=\"801\">4</sup>: גם ענינו של \"שוטר\" — ואפילו בשייכות למשפט — כבר ידוע<sup data-n=\"802\">5</sup> לעיל בפ' דברים<sup data-n=\"803\">6</sup> \"ואקח את ראשי שבטיכם אנשים חכמים גו' ושוטרים לשבטיכם\", והיינו שנוסף על מינוי ה\"שופטים\" (\"אנשים חכמים גו'\"), נתמנו גם \"שוטרים לשבטיכם\"<sup data-n=\"804\">7</sup>, וכפרש\"י שם \"ושוטרים מניתי עליכם לשבטיכם, אלו הכופתין והמכין ברצועה ע\"פ הדיינין\" — ומה טעם הוזקק רש\"י לפרשו כאן עוד פעם?\nוביותר תמוה — שדוקא כאן, בפעם השני', מאריך רש\"י יותר מבפירושו בפ' דברים: שם כ' בקיצור \"אלו הכופתין והמכין ברצועה ע\"פ הדיינין\", וכאן מוסיף: א) בתחילת הפירוש — \"הרודין<sup data-n=\"805\">8</sup> את העם\" (שבפשטות כוונתו לפרש שתיבת \"שוטר\" כאן היא מלשון רדי'<sup data-n=\"806\">9</sup>). ב) ובסוף הפירוש — \"עד שיקבל עליו את דין השופט\".\nגם יש כמה שינויים בלשון רש\"י: (א) בפ' דברים כתב \"ע\"פ הדיינין\", וכאן \"אחר מצותן\"<sup data-n=\"807\">10</sup>. (ב) בפ' דברים כתב \"הכופתין והמכין\", וכאן מהפך הסדר —",[["798","1","בדפוסי רש\"י הנפוצים תיבת \"ושוטרים\" היא באותיות גדולות — ד\"ה חדש. אבל לכאורה הוא טה\"ד, והד\"ה שבפרש\"י הוא \"שופטים ושוטרים\", ואח\"כ מפרש החילוק ביניהם — \"שופטים דיינים כו' ושוטרים הרודין כו'\"."],["799","2","בכמה כת\"י רש\"י שתח\"י (וכן בדפוס שני) ליתא התיבות \"את. . מצותן\". וראה לקמן הערה 8, 10."],["800","3","גו\"א כאן. וראה דבק טוב, הואיל משה (באר היטב) ועוד כאן."],["801","4","נוסף לזה שתי' הגו\"א (בטעם שהוצרך רש\"י לפרש \"שופטים\") אינו מובן, לכאורה, שהרי כיון שענין השופטים ידוע, הי' מספיק לכתוב רק הפירוש של \"שוטרים\" כדי להודיע מהי ההוספה ב\"שוטרים\" על \"שופטים\"."],["802","5","ועפ\"ז נשלל לכאורה מ\"ש במפרשים (דבק טוב. הואיל משה. שפ\"ח. וראה באר מים חיים (לאחי המהר\"ל)) שכוונת רש\"י שלא תטעה ש\"שוטר\" כאן פירושו כבפ' בהעלותך (יא, טז) \"זקני העם ושוטריו\", או כהשוטרים הממונים על המלחמה (פרשתנו כ — ה. ח. ט)<sup data-n=\"e41\">*</sup>, אלא מלשון רדי' (וראה גם רש\"י שמות ה, ו. שם, יט) — שהרי לאחרי שכבר פי' רש\"י בפ' דברים דשוטרים (גבי משפט) \"אלו הכופתין כו'\", שוב אין מקום לטעות כזו."],["803","6","א, טו."],["804","7","וצ\"ע ברע\"ב כאן."],["805","8","בכמה כת\"י רש\"י (שתח\"י) \"אדם שמכה כו'\". ואולי הוא ט\"ס שנחלף להם מ\"רודים\" ל\"אדם\" (ע\"ד הגירסא בדפוס שני \"הרודים שמכים כו'\")."],["806","9","ראה לעיל הערה 5."],["807","10","בהנסמן בהערה 8, ליתא תיבות אלו."],["e41","*","ולהעיר מלשון \"שוטר\" שבפרש\"י ח\"ש (כג, י) \"מנוהו שוטר עליהם\". ואכ\"מ."]]],[1301550170,"\"שמכין וכופתין\"<sup data-n=\"808\">11</sup>. (ג) בפ' דברים נקט רק \"ברצועה\", וכאן מוסיף \"במקל וב­רצועה\"<sup data-n=\"809\">12</sup>.\nב. ולכן נראה לומר, דלפרש\"י ה­\"שוטרים\" דהכא וה\"שוטרים\" דפ' דברים לאו היינו הך, אלא הם שני סוגי שוט­רים:\nבפ' דברים קאי ב\"שוטרים\" שהם המוציאים בפועל את הוראת הב\"ד, שהשופטים פוסקים מהו העונש, וה­שוטרים הם המענישים בפועל.\nובפרשתנו קאי בשוטרים שענינם לאיים על הנדון שיקבל עליו את דין השופט. היינו לא ביצוע הוראת הב\"ד, אלא לכפות את הנדון שהוא יקבל על עצמו לקיים הוראת הב\"ד (כגון מי שפסקו הב\"ד שחייב לשלם ממון לחבירו ואינו רוצה לשלם, שהשוטרים כופים אותו לשלם הממון)<sup data-n=\"810\">13</sup>.\nובזה מבוארים חילוקי הלשונות בין שני פירושי רש\"י הנ\"ל:\nבפ' דברים כותב שהשוטרים הם \"הכופתין והמכין כו' על פי הדיינין\", היינו, שהם מקיימים בפועל את הוראות פי הדיינין, ולכן כתב \"אלו הכופתין והמכין ברצועה\" — בהתאם לסדרו של עונש מלקות, שבתחילה כופתין את הנלקה<sup data-n=\"811\">14</sup>, ואח\"כ מכים אותו ברצועה.\nמשא\"כ בפרשתנו כותב רש\"י שהשוט­רים הם \"הרודין את העם. . עד שיקבל עליו את דין השופט\", שזהו האופן השני שבשוטרים — שכופים את בעל הדין (\"רודין את העם\"), \"עד שיקבל עליו את דין השופט\". ולכן לא כתב כאן \"על פי הדיינין\" אלא \"אחר מצותן\", היינו שאין ענינם (רק) לבצע הוראת הב\"ד (\"פי הדיינין\") אלא לכפות את הנדון לקבל עליו ציווי<sup data-n=\"812\">15</sup> (ומרות) השופטים (בכלל), ואם אינו רוצה לקבל עליו את ציווי השופט — הרי השוטרים \"מכין וכופתין כו' עד שיקבל עליו את דין השופט\".\nובזה מובן גם הטעם לשאר השינויים בלשון רש\"י:\nא) בפרשתנו כ' \"מכין וכופתין\" (ולא כבפ' דברים — \"הכופתין והמכין\") — כי כאן הכוונה לכפיית הנדון לקבל עליו את הדין, ולכן מונה רש\"י שני אופני הכפי' מן הקל אל הכבד \"מכין (ואם אין זה מועיל —) וכופתין\" (היינו שאוסרים אותו כו').\nב) בפ' דברים נקט רק \"רצועה\" ולא",[["808","11","בדפוס א' וב' וכל כת\"י שתח\"י, ליתא תיבות אלו [ורק בהנסמן בהערה 8 — \"שמכה\" (שמכים)]. וכן ליתא ב(ל' רש\"י שהועתק ב)סמ\"ג עשין צז בתחלתו. אבל בדפוסי רש\"י הנפוצים הוא כבפנים. וגירסא זו כבר היתה לפני הבאר מים חיים ונחלת יעקב. וכן משמע בגו\"א.\n— בבאמ\"ח שם מפרש, ש\"במקל\" \"מוסב אל ומכין\", ו\"ברצועה\" \"מוסב אל וכופתין, ר\"ל שקוש­רין אותם ברצועה\". אבל אין זה מתרץ הטעם לשינוי הסדר, כי אם לכתוב \"וכופתין ומכין ברצועה וב­מקל\". ואכ\"מ."],["809","12","והרי מכין (גם) ברצועה, כפרש\"י דברים שם. ובספרי דברים שם \"המכין ברצועה\". וראה הנסמן בהערה 16."],["810","13","ראה גם רש\"י סנהדרין טז, ב ד\"ה שוטרים. וראה לקמן ס\"ה, שזוהי גם דעת הרמב\"ם."],["811","14","ראה רש\"י מכות כב, ב ד\"ה על העמוד. — וכן מובן בפשטות, שקודם שמלקין את האדם צריכים לכופתו שלא יפול כו' כיון שהוא \"מוטה\" (מכות שם. הובא גם ברש\"י תצא כה, ב)."],["812","15","ע\"פ המבואר בפנים מתורץ בפשטות מדוע לא כ' רש\"י \"אחר הוראתן\" (ראה השקו\"ט ברא\"ם כאן) — כי אין המדובר בקיום הוראת השופט, אלא האיום על הנידון שיקבל עליו ציווי השופט (ובפרט ע\"פ המבואר לקמן ס\"ג, שגם עשיית המשפט (ולא רק ההוראה) שייכת להשופט)."]]],[1301550171,"\"מקל\" — כי עונש מלקות הוא ברצועה<sup data-n=\"813\">16</sup> ולא הכאה במקל<sup data-n=\"814\">17</sup>; משא\"כ בפרשתנו שהכוונה לשוטרים \"הרודין את העם\" שייראו מהשופט ויקבלו עליהם את דין השופט, צריכים (לפעמים) גם מקל. ואדרבה — רש\"י מקדים \"מקל\" כי זהו סימן של \"רדי'\"<sup data-n=\"815\">18</sup>.\n— אלא שע\"פ כהנ\"ל יש להבין בגופו של ענין: מהו ההכרח (בפשש\"מ) דצ\"ל שני סוגי שוטרים: (המסופר בפ' דברים) \"אלו הכופתין כו' על פי הדיינין\" ושוט­רים (דפרשתנו) \"הרודין את העם. . עד שיקבל עליו את דין השופט\"<sup data-n=\"816\">19</sup>?\nג. ויש לומר הביאור בזה:\n\"שופט\" בתורה (בדרך הפשט) אינו רק דיין הפוסק את הדין, אלא גם זה ה­מבצע את הדין בפועל<sup data-n=\"817\">20</sup>, וכמפורש לעיל בסוף פ' בלק<sup data-n=\"818\">21</sup>, שאמר משה \"אל שופטי ישראל הרגו איש אנשיו\". ומפורש ב­רש\"י שם \"הרגו איש אנשיו — כל אחד ואחד מדייני ישראל הי' הורג שנים כו'\". וכן לקמן בעונש מלקות מפורש בקרא<sup data-n=\"819\">22</sup> \"והפילו השופט והכהו וגו'\".\nועפ\"ז מובן שא\"א לפרש ש\"שוטרים\" כאן הם המבצעים את גזר הדין בפועל (כבפ' דברים) — שהרי זה נכלל בהציווי ד\"שופטים. . תתן לך\".\nואינו דומה ל\"ושוטרים לשבטיכם\" דפ' דברים, שפרש\"י שהי' מינוי בפ\"ע<sup data-n=\"820\">23</sup> על \"הכופתין והמכין. . על פי הדיינין\" — כי בכתוב שם לא נקראו הדיינים בשם \"שופטים\"<sup data-n=\"821\">24</sup> (כ\"א כנאמר \"ואקח את ראשי שבטיכם אנשים חכמים וידועים ואתן אותם ראשים עליכם שרי אלפים גו'\"), ומובן דמש\"נ אח\"כ \"ושוטרים לשבטיכם\" יכול להתפרש על אלה ה­מוציאים בפועל את הוראות הדיינים<sup data-n=\"822\">25</sup> (ושניהם בשם \"שופטים\" יקראו — וכולם נכללו במש\"נ בכתוב שלאח\"ז<sup data-n=\"823\">26</sup> \"ואצוה את שופטיכם בעת ההיא גו' ושפטתם צדק גו'\").\nמשא\"כ בפרשתנו שנאמר \"שופטים ושוטרים תתן לך\", הרי שה\"שוטרים\" אינם בכלל \"שופטים\" —",[["813","16","משנה מכות שם. וראה רש\"י סנהדרין ז, ב ד\"ה רצועה (הובא לקמן בפנים ס\"ה)."],["814","17","ברש\"י סנהדרין שם ד\"ה מקל (הובא לקמן שם), דמכת מרדות היא במקל. ולהעיר מעונשי ב\"ד כשהשעה צריכה לכך (רמב\"ם הל' סנהדרין ספכ\"ד) שאפשר בכמה אופנים. אבל מובן שרש\"י נקט דוגמא מעונש מלקות שבקרא, שהיא ברצועה."],["815","18","כלשון רש\"י ויחי (מט, י) \"רודין את העם בשבט\". וברש\"י וילך (לא, ז) \"טול מקל כו'\". וראה ע\"ז מא, א."],["816","19","במשכיל לדוד כאן ד\"הוה מצי לפרש המכים למי שנתחייב מלקות או מכת מרדות ע\"פ הדיינים אלא משום דהכא לפי הענין בדיני ממונות מיירי כדכתיב לא תכיר פנים ולא תקח שוחד וכו' מש\"ה פי' שמכין עד שיקבל כו'\".\nאבל לכאו' אינו תירוץ מספיק, שהרי אפשר לומר שהציווי למנות \"שוטרים\" הוא ענין כללי (אף שאינו שייך לדיני ממונות)."],["817","20","ראה רש\"י ישעי' (לב, ז) \"משפט משמש שלשה לשונות תחלת הטענות. . וגמר הדין. . ומשטר ששוטרין אותו ביסורין\". וראה באר בשדה (על פרש\"י) כאן."],["818","21","כה, ה. — וראה וירא יט, ט \"וישפוט שפוט\" (אבל ראה רש\"י שם). שמות (ב, יד) \"מי שמך גו' ושופט גו' הלהרגני גו'\"."],["819","22","תצא כה, ב.\nאלא שמובן שהשופט יכול למנות שליח ע\"ז (כמפורש ברש\"י משפטים כא, יד \"שליח ב\"ד שה­מית במלקות\"). אבל זהו מענינם של ה\"שופטים\"."],["820","23","ראה מפרשי רש\"י שם."],["821","24","ולא שישפטו את העם — שזה נאמר רק לקמן בפסוק שלאח\"ז \"ושפטתם צדק\"."],["822","25","וההכרח לפרש כן — ראה לקמן ס\"ד."],["823","26","א, טז."]]],[1301550172,"ולכן פרש\"י כאן<sup data-n=\"824\">27</sup> שהכוונה לאלו \"הרודין את העם אחר מצותן (של השופטים). . עד שיקבל עליו את דין השופט\" — שרודים אלה אינם שייכים לעצם המשפט (לא לההוראה וגם לא להוצאת המשפט בפועל), אלא לרדיית העם שיפחדו מהשופטים ויקבלו עליהם את דינם, כנ\"ל בארוכה.\nד. אלא שעדיין צריך ביאור — ל­אידך גיסא:\nכיון שאפשר לפרש ש\"שוטרים\" הם \"הרודין את העם\" — מנ\"ל לרש\"י לפרש בפ' דברים ש\"שוטרים\" שם היינו \"אלו הכופתין והמכין. . על פי הדיינין\"? ובפרט שמצינו בכמה מקומות (כנ\"ל) שהשופטים עצמם עושים את הדין בפועל, ומנ\"ל לרש\"י שהי' מינוי מיוחד על שוטרים כאלו?\nויש לומר, שרש\"י מרמז ההכרח לפירושו, ביתור לשונו שם \"ושוטרים — מניתי עליכם לשבטיכם אלו הכופתין כו'\", דלכאורה, החידוש בפרש\"י שם הוא<sup data-n=\"820\">23</sup> שהשוטרים הם מינוי בפ\"ע (ולא שהדיינים שנתן \"ראשים עליכם\" הם הם השוטרים), והול\"ל \"ושוטרים — מניתי לשבטיכם\", ומהי כוונתו בתיבת \"עליכם\" — והרי פשוט שהמינוי הוא על בנ\"י?\nאלא שבזה מרמז רש\"י ההכרח להמשך פירושו \"אלו הכופתין כו' על פי הדיינין\":\nאם ה\"שוטרים\" הם \"הרודין את העם. . עד שיקבל עליו את דין ה­שופט\", הרי אין תוכן מינוי זה — שררה על בנ\"י<sup data-n=\"826\">28</sup>, כ\"א סיוע להשופטים [דהיות שהמדובר בבעל דין שאינו מציית אליו, זקוק הוא לשוטרים שיאיימו על הבעל דין שיקבל את דין השופט] — וא\"כ הול\"ל בפסוק \"ושוטרים ל(סייע) שופ­טיכם\"?\nולכן פרש\"י שהכוונה ל\"אלו הכופתין והמכין. . על פי הדיינין\" — שעפ\"ז מובן שזהו מינוי על בנ\"י (\"עליכם\"), כי הם שני חלקים במינוי השופטים (על בנ\"י): א) אנשים חכמים גו' — שמורים לבנ\"י את הדין, ב) השוטרים שמוציאים ועושים את הדין בפועל<sup data-n=\"826\">28</sup>.\nויש לבאר הטעם שבימי משה רבינו לא מצינו שימנו \"שוטרים\" לרדות את העם שיקבלו עליהם את דין השופט — כי (ע\"ד הפשט<sup data-n=\"828\">29</sup>) בימי משה ממנה השופטים, לא הוצרכו לזה, לפי שבנ\"י היו יראים מן השופטים ולא היו צריכים לשוטרים לאיים עליהם כו'; משא\"כ בפרשתנו, שהוא ציווי לדורות, בכל מצב שיהי', לכן נצטוו למנות \"שוטרים\" — \"הרודין את העם. . עד שיקבל עליו את דין השופט\" (שיהיו מוכנים אם המצב דורש הנהגה של כפי').",[["824","27","ולהעיר שרש\"י מביא גם \"שופטים\" (ומ­פרשו) — ראה הערה 4 — והרי תיבת \"שופטים\" היא היסוד לפירושו ב\"שוטרים\"."],["820","23","ראה מפרשי רש\"י שם."],["826","28","ולהעיר מהשקו\"ט ברא\"ם (וגו\"א ועוד) כאן אם ביד השוטרים הכח והממשלה להכות ולרדות, או שהם הנערים העומדים לפני דיינים (ואין להם שום כח וממשלה אלא מצוואת השופטים). ע\"ש, ובדינא דחיי (לבעל כנה\"ג) על הסמ\"ג ריש הל' סנהדרין (עשין צז). ולהעיר מבאר שבע לסוטה מב, א ד\"ה מה שוטר."],["826","28","ולהעיר מהשקו\"ט ברא\"ם (וגו\"א ועוד) כאן אם ביד השוטרים הכח והממשלה להכות ולרדות, או שהם הנערים העומדים לפני דיינים (ואין להם שום כח וממשלה אלא מצוואת השופטים). ע\"ש, ובדינא דחיי (לבעל כנה\"ג) על הסמ\"ג ריש הל' סנהדרין (עשין צז). ולהעיר מבאר שבע לסוטה מב, א ד\"ה מה שוטר."],["828","29","בסנהדרין (ז, ב. הובא לקמן ס\"ה) ש\"בעת ההיא\" (דברים א, טז) היו צריכים \"מקל ורצועה\", וראה חדא\"ג מהרש\"א שם, שרק \"באותו הדור הי' צריך לזירוז הזה על המקל ורצועה שהיו סרבנים ובעלי מריבות\". אבל ע\"ד הפשט, זה שהיו טרחנין ובעלי מריבות אינו טעם שלא יקבלו פסק השופטים. וכמובן מרש\"י דברים (א, יב) \"הי'. . רואה. . בעל דינו נוצח בדין אומר כו'\" (ע\"ש). ולהעיר מרש\"י שם, יג שהשופטים היו \"ראשים ומכובדים עליכם שתהיו נוהגין בהם כבוד ויראה\"."]]],[1301550173,"ה. ע\"פ כהנ\"ל יש לבאר סוגיית הגמ' במס' סנהדרין<sup data-n=\"829\">30</sup>:\n(ואלה המשפטים) אשר תשים<sup data-n=\"830\">31</sup> אשר תלמדם מיבעי' לי' (אלא). . אלו כלי הדיינין, רב הונא כי הוה נפק לדינא אמר הכי אפיקו לי מאני חנותאי מקל ורצועה ושופרא (לשמתא ונידוי. רש\"י) וסנדלא (לחליצה. רש\"י), ואצוה את שופטיכם בעת ההיא<sup data-n=\"823\">26</sup> אמר ר' יוחנן כנגד מקל ורצועה תהא זריז (שיהו מטילין אימה על הציבור לשם שמים. רש\"י).\nוצריך ביאור — למה הזכיר ר' יוחנן רק \"מקל ורצועה\" והשמיט שאר כלי הדיינים שנזכרו לפנ\"ז — \"שופרא וסנדלא\"?\nבנוגע ל\"סנדלא\" שהוא לחליצה יש לתרץ, כי אינו שייך להטלת אימה על הציבור — אבל אינו מובן למה השמיט \"שופרא\"<sup data-n=\"832\">32</sup>.\nוע\"פ משנת\"ל (בביאור שיטת רש\"י עה\"ת) יש לומר, דב' המימרות בגמ' איירי בשני ענינים שונים:\nהפירוש ב\"כלי הדיינין\", היינו הכלים הנצרכים לפעולות ב\"ד: סנדל לחליצה — בב\"ד דוקא, (ובפרש\"י בש\"ס שם) \"רצועה, למלקות. מקל, למכת מרדות כו'<sup data-n=\"833\">33</sup>. שופר, לשמתא ונידוי\";\nמשא\"כ הא ד\"כנגד מקל ורצועה תהא זריז\", הכוונה להשוטרים<sup data-n=\"834\">34</sup>, שענינם להטיל אימה על הציבור (בל' רש\"י פר­שתנו — \"הרודין את העם. . במקל וברצועה. . עד שיקבל עליו את דין השופט\"), ולכן לא נקט כאן \"שופר\" לנידוי ושמתא, שאינם פעולות השוטרים, אלא דהדיינים.\n[ועד\"ז היא גם דעת הרמב\"ם, שענינם של ה\"שוטרים\" (דפרשתנו) הוא שהעם יקבלו עליהם את הדין, וז\"ל<sup data-n=\"835\">35</sup>: \"שוטרים אלו בעלי מקל ורצועה והם עומדים לפני הדיינין המסבבים בשווקים וברחו­בות ועל החנויות לתקן השערים כו' ולהכות (נ\"א ולתקן) כל מעוות. . וכל שיראו בו עוות דבר מביאין אותו לב\"ד ודנין אותו כפי רשעו\" — הרי שהשוט­רים האלה אינם אלו המבצעים את פסק השופטים, אלא הם \"בעלי מקל ור­צועה<sup data-n=\"836\">36</sup>. . המסבבין בשווקים וברחובות\"",[["829","30","ז, ב."],["830","31","ר\"פ משפטים."],["823","26","א, טז."],["832","32","ראה עיון יעקב לע\"י סנהדרין שם.\nולהעיר מב\"ח לטוחו\"מ ס\"א (ד\"ה בעלי מקל) בטעם מ\"ש רב האי גאון (הובא בטור שם) ש\"ב\"ד צריך שיהא לו מזומן. . מקל לרדות בו ורצועה להלקות בו ושופר לנדות בו\" — ד\"פשיטא דבכלל זה (\"כנגד מקל ורצועה תהא זריז\") גם השופר אע\"ג דלא הזכירו דע\"י הנדוי בשופר איכא הטלת אימה\"."],["833","33","ודלא כפי' הר\"ח (שהובא בפי' ר\"י אלמדארי לסנה' שם. ובר\"ח לפנינו ליתא) \"המטה לאיים בו על המסרבין לקבל הדין\".\nומה שרש\"י מסיים שם \"עד שיחזור בו\" — כי מכת מרדות ענינה שהאדם \"יחזור בו\" (ראה תוספתא מכות ספ\"ג: מכת מרדות. . עד שיקבל עליו כו'). ואכ\"מ."],["834","34","אלא שצע\"ק שזירוז זה נלמד ממש\"נ \"ואצוה את שופטיכם\", וע\"פ הנ\"ל בפנים אין \"שוטרים\" (דהסוג דפרשתנו) בכלל."],["835","35","הל' סנהדרין פ\"א ה\"א. ובסהמ\"צ (מ\"ע קעו) \"שצונו למנות שופטים ושוטרים<sup data-n=\"e42\">*</sup> שיכריחו לעשות מצות התורה ויחזירו את הנוטים מדרך האמת אלי' על כרחם כו' ויעמידו גדרים כו'\". ע\"ש. — ובטור (חו\"מ שם) \"ושוטרים הן בעלי מקל ורצועה העומדין לפני הדיינין לרדות על פי הדיינין\"."],["836","36","ועפ\"ז, מ\"ש הרמב\"ם \"מקל ורצועה\" אינם מ\"כלי הדיינין\" שנמנו בגמ' (שהכוונה לכלי ה­שופטים, כנ\"ל בפנים) — וזהו דלא כפירוש הערוך השלחן (חו\"מ שם אות יז) שכלי הדיינין \"שייך להשוטרים\" והרמב\"ם \"לא השמיטה וכתבה אצל השוטרים\" [ובלאה\"כ לא תירץ מה שהשמיט הרמב\"ם שופר וסנדל. אבל ראה לקו\"ש ח\"ד ע' 1096 הערה 26. ואכ\"מ]."],["e42","*","כ\"ה בסהמ\"צ לפנינו. אבל בתרגום קאפח \"למנות דיינים\"."]]],[1301550174,"לתקן הנהגת העם ולהביא \"עוות דבר\" לפני ב\"ד (והב\"ד \"דנין אותו כפי רשעו\"<sup data-n=\"837\">37</sup>)].\nו. ובדרך זו מתורצת בפשיטות עוד שאלה במצות מינוי \"שופטים ושוטרים\":\nכל מוני המצות מנו מינוי שופטים ושוטרים במצוה אחת, אף שלכאורה הם שני מעשים נפרדים, מינוי שופטים ומי­נוי שוטרים (וכמודגש בלשון הברייתא<sup data-n=\"838\">38</sup> \"מנין שמעמידין שופטים לישראל ת\"ל שופטים תתן, שוטרים לישראל מנין ת\"ל שוטרים תתן\") — ואמאי לא נמנו כשתי מצות?\nי\"מ<sup data-n=\"839\">39</sup> ששופטים ושוטרים מעכבים זא\"ז<sup data-n=\"840\">40</sup>, ולכן נמנו כמצוה אחת (כמ\"ש הרמב\"ם<sup data-n=\"841\">41</sup> דאם חלקי המצוה מעכבים זא\"ז נמנין במצוה אחת), והביאו ראי' ממה שאמרו בספרי<sup data-n=\"842\">42</sup> \"אם יש שוטרים יש שופטים אם אין שוטרים אין שופ­טים\", ובתנחומא<sup data-n=\"843\">43</sup> \"אם אין שוטר אין שופט, כיצד, כיון שנתחייב אדם בב\"ד לחבירו אם אין שוטר שיוציא ממנו כיון שפורש מן הדיין אין ספוק ביד הדיין לעשות לו כלום אא\"כ מוסר ביד השוטר\", ונמצא ש\"על ידי אלו ואלו יחד המשפט נגמר\".\nאבל דוחק לתרץ כן, שהרי להלכה למעשה לא נזכר ברמב\"ם ששופטים ושוטרים מעכבים זא\"ז, ובפשטות גם אם אין יכולים (מאיזו סיבה שתהי') למנות שוטרים, חייבים במינוי שופטים<sup data-n=\"844\">44</sup>.\n[ובפשטות, גם כוונת הספרי (והתנ­חומא) אינה לדינא ש\"אם אין שוטרים אין שופטים\", אלא רק לתועלת הדבר, שבלי שוטרים יתכן שענין המשפט לא יבוא לידי פועל — אבל למעשה חייבים במינוי שופטים גם בלי שוטרים<sup data-n=\"845\">45</sup>. ויתכן שענין המשפט יבוא לידי פועל גם בלי (איום ד)שוטרים<sup data-n=\"846\">46</sup>. ועוד ועיקר יש צורך והכרח ב\"שופטים\" להורות בכל עניני התורה (שרובם אינם קשורים עם עונש וכיו\"ב)].\nלכאורה י\"ל ע\"פ דברי הרמב\"ם<sup data-n=\"841\">41</sup> (לענין תכלת ולבן שנמנו כמצוה אחת, אף שאינן מעכבין זא\"ז) \"שאפילו ה­חלקים שאינן מעכבין זא\"ז פעמים יהיו",[["837","37","ברמב\"ם הל' גניבה ספ\"ח שהשוטר ענינו \"להכותו כפי כחו ולקנסו כפי ראות ב\"ד לחזק הדבר\" — אבל י\"ל, שג\"ז בכלל ענין הרדי' שיקבלו עליהם את הדין, כי מדת הרדי' ע\"י השוטרים צ\"ל ע\"פ הוראת הב\"ד. וראה סוטה מב, א וברש\"י שם. ואכ\"מ."],["838","38","סנהדרין טז, ב. ספרי ריש פרשתנו (בשינוי לשון). — וראה תו\"ת ריש פרשתנו."],["839","39","ביאור הרי\"פ פערלא לסהמ\"צ לרס\"ג פרשיות פרשה א' בסופה. וראה גם מהר\"ם שיק על תרי\"ג מצות מצוה תצא. — וראה גם לקו\"ש ח\"ב ע' 380 הערה 3."],["840","40","ראה גם אוה\"ח ריש פרשתנו."],["841","41","בסהמ\"צ בשרשים — שרש יא."],["842","42","ריש פרשתנו."],["843","43","פרשתנו ב (ובתנחומא באבער ג)."],["844","44","ראה גם לקו\"ש חי\"ט ע' 489 הערה ד\"ה שופטים."],["845","45","אלא שלכאורה פשיטא שאם אין שופטים לפסוק את הדין, אין חיוב למנות שוטרים (כמ\"ש ברע\"ב ריש פרשתנו). אבל י\"ל שחייבים להעמיד שוטרים להכריח את העם לקיים מצות המפורשות בתורה (שאין צריכים ע\"ז פסק השופטים). וראה ל' הרמב\"ם בסהמ\"צ דלעיל הערה 35."],["846","46","וראה אוה\"ח שם: וכל שהעם נשמעים ל­דייניהם בלא שוטרים חייבין למנות השופטים (אלא מסיים \"וקוראים אנו בשופט זה שופט ושוטר\")."],["841","41","בסהמ\"צ בשרשים — שרש יא."]]],[1301550175,"מצוה אחת כשיהי' הענין אחד\" — והרי גם בנדו\"ד (בלשון המפרשים הנ\"ל<sup data-n=\"839\">39</sup>) \"ודאי שופטים ושוטרים ענינם אחד הוא\".\nאבל עדיין יש לדון בזה, כי הכלל הנ\"ל שברמב\"ם לא נאמר וקיים בכל מקום, וכמו שהאריכו במפרשים<sup data-n=\"849\">47</sup> להק­שות עליו ומהם — מהא דתפילין של יד ושל ראש נמנו בשתי מצות, ו\"הרי התפילין יחשבו יותר ענין אחד (מתכלת ולבן)\" — ותירצו שבתפלין הם \"שני מעשים\" (שתי לבישות)<sup data-n=\"850\">48</sup>, וכן \"סידורן ותמונתן אינן אחד אך יש בהן שינוי רב ועל הכל שינוי מקומם אלו בראש ואלו ביד\"<sup data-n=\"851\">49</sup>,\nועפ\"ז גם בנדו\"ד — הרי מינוי השופ­טים ומינוי השוטרים הם \"שני מעשים\", וכן בתוכנם \"יש בהם שינוי רב\" — והדרא קושיא לדוכתא, מדוע לא נמנו כשתי מצות?\nוע\"פ משנת\"ל בגדר השוטרים — מתורץ הענין בפשיטות:\nאם ענינם של השוטרים הוא לקיים ולבצע את פסק השופטים בפועל, ו­\"שופטים\" היינו רק אלה המורים ופוס­קים את הדין — הרי נמצא שענין ה­משפט נחלק (בתורה) לשני חלקים שונים — הוראת ההלכה (ע\"י השופטים), וביצוע הפסק (ע\"י השוטרים); ואזי יש מקום למנות את מינוי השוטרים כמצוה ב­פ\"ע<sup data-n=\"852\">50</sup>, כי אע\"פ שענינם אחד (משפט) הרי הם \"שני מעשים\", שני מינויים (כנ\"ל ס\"ד);\nאבל ע\"פ הנ\"ל שתפקידם של ה­שופטים כולל (לא רק הוראה, אלא) גם ביצוע הדין, וכל ענין השוטרים אינו אלא סיוע להשופטים, דאם אין השופט יכול להוציא את משפטו לפועל, אזי צריך להשתמש ב\"בעלי מקל וזרוע\" שהם יכריחו את הבע\"ד \"שיקבל עליו את הדין\" — פשוט מדוע לא נמנה מינוי השוטרים כמצוה בפ\"ע, כי (א) זהו פרט בענין של הוצאת המשפט בפועל ע\"י השופטים<sup data-n=\"853\">51</sup>. (ב) ועיקר: אינו ענין הכרחי כלל לתוכן ענין המשפט, שהרי אפשר להוציא המשפט לאור (גם בפועל) בלי שוטרים.\nז. מיינה של תורה שבפירוש רש\"י:\nידועים דברי הש\"ך עה\"ת<sup data-n=\"854\">52</sup>, ש\"שופ­טים ושוטרים תתן לך בכל שעריך\" קאי נמי על \"שערי הגוף\", העינים והאזנים וכו', \"ללמד לאדם שיהי' לו שוטר ו­מושל על כל אחד ואחד מאלו האיברים כו'\".\nוהנה בפשטות, החילוק בין \"שופטים\" ל\"שוטרים\" בענין זה הוא, שמינוי \"שופ­טים\" (דיינים) מתקיים ע\"י לימוד הלכות התורה, לדעת את המעשה אשר יעשון ואלה אשר לא תעשינה; ומינוי \"שוטרים\" מתקיים ע\"י קיום הלכות התורה במעשה בפועל.\nאבל ע\"פ משנת\"ל מובן, שגם עניני ה\"מעשה\" נכללים במינוי \"שופטים\" גופא",[["839","39","ביאור הרי\"פ פערלא לסהמ\"צ לרס\"ג פרשיות פרשה א' בסופה. וראה גם מהר\"ם שיק על תרי\"ג מצות מצוה תצא. — וראה גם לקו\"ש ח\"ב ע' 380 הערה 3."],["849","47","רמב\"ן בהשגות לסהמ\"צ שורש ט' בסופו."],["850","48","רמב\"ן שם (אלא שדחה חילוק זה). לב שמח לשרש יא."],["851","49","לב שמח שם. קנאת סופרים לשורש ט' שם."],["852","50","ובפרט להסברא שביד השוטרים הכח והממשלה כו' (והשופטים אין להם כח לעשות רק להורות) — ראה הנסמן בהערה 28."],["853","51","היינו ש\"שופטים\" הוא הכלל (שכולל כל עניני משפט עד לביצוע המשפט בפועל), וא\"כ שוטרים הם רק פרט ב\"שופטים\" (וראה סהמ\"צ שם שרש י\"ב)."],["854","52","ריש פרשתנו. וראה בארוכה אוה\"ת ריש פרשתנו. ועוד."]]],[1301550176,"(כמו \"שופטים\" בפשטות שתפקידם גם להוציא לפועל משפטם, כנ\"ל). והטעם י\"ל, כי \"תכלית חכמה תשובה ומעשים טובים\"<sup data-n=\"855\">53</sup>, ואם אין התלמוד מביא לידי מעשה, חסר (לא רק במעשה, אלא) גם בהתלמוד עצמו, כמשנ\"ת במק\"א<sup data-n=\"856\">54</sup>.\nולפירוש זה צ\"ל, שענין ה\"שוטרים\" הוא<sup data-n=\"857\">55</sup> כאשר יצרו של אדם מתגבר עליו ויש צורך לבטש אותו שלא יבלבלו מתורה ועבודה, שאז צריך ל\"שוטר\" — להרגיז יצרו הטוב על יצרו הרע<sup data-n=\"858\">56</sup>, ו­\"להכותו\" (בהכאת דברים) \"לומר לו אתה רע ורשע ומשוקץ ומתועב ומנוול כו'\"<sup data-n=\"859\">57</sup>, שעי\"ז מתבטלת שליטת היצר כו'.\nועפ\"ז מובן לשון היעוד \"ואשיבה שופטיך כבראשונה גו'\"<sup data-n=\"860\">58</sup> — ולא נזכר \"שוטרים\" — כי אז יתבטל הרע ולא יהי' צורך ב\"שוטרים\", כי אם רק \"שופטים\" — לימוד התורה וקיום המצות, \"ילכו מחיל אל חיל\" בקדושה גופא<sup data-n=\"861\">59</sup>.\n<span data-k=\"q\">(משיחת ש\"פ שופטים תשכ\"ה)</span>",[["855","53","ברכות יז, א. וראה רש\"י שם."],["856","54","לקו\"ש חט\"ו ע' 139. חי\"ז ע' 306 ואילך."],["857","55","ראה גם אוה\"ת פרשתנו ע' תתכא. ולהעיר ממאמרי אדהאמ\"צ דברים ח\"ג ס\"ע תשמ­מא."],["858","56","ברכות ה, רע\"א."],["859","57","ל' התניא פכ\"ט (לז, א)."],["860","58","ישעי' א, כו. וראה בארוכה סה\"ש תנש\"א ח\"ב ע' 780 ואילך."],["861","59","ראה אגה\"ק סו\"ס כו (קמה, א)."]]],[1301550177,"<h3>שיחה ב</h3>\nא. כתב הרמב\"ם<sup data-n=\"862\">1</sup>: גזירת הכתוב היא שאין ממיתין בית דין ולא מלקין את האדם בהודאת פיו אלא על פי שנים עדים<sup data-n=\"863\">2</sup>. היינו, דאף שקיי\"ל דהודאת בעל דין כמאה עדים דמי<sup data-n=\"864\">3</sup>, ה\"ז רק לחייבו ממון, אבל לא להתחייב (ע\"י הודאת עצמו) במיתה או במלקות.\nוברדב\"ז שם: ואפשר לתת קצת טעם<sup data-n=\"865\">4</sup> לפי שאין נפשו של אדם קניינו אלא קנין הקב\"ה<sup data-n=\"866\">5</sup> שנאמר<sup data-n=\"867\">6</sup> הנפשות לי הנה הלכך לא תועיל הודאתו בדבר שאינו שלו ומלקות פלגו<sup data-n=\"868\">*6</sup> דמיתה הוא אבל ממונו הוא שלו ומש\"ה אמרינן הודאת בעל דין כמאה עדים דמי. . ועם כל זה אני מודה שהיא גזירת מלכו של עולם ואין להרהר.\nולכאורה יל\"ע בדברי הרדב\"ז, דמאי שנא נפשות שהם קניינו של הקב\"ה, מזה שכל העולם כולו הוי \"קנין הקב\"ה\" כמ\"ש<sup data-n=\"869\">7</sup> \"לה' הארץ ומלואה\" — ובלשון החינוך<sup data-n=\"870\">8</sup> \"הכל ברשות אדון הכל\" — כולל ממונו של אדם, ובלשון הכתוב<sup data-n=\"871\">9</sup> \"לי הכסף ולי הזהב נאום ה'\"?\nועכצ\"ל, שהגם שכל העולם הוא ב­בעלותו של הקב\"ה, מ\"מ, ביחס לרשות האדם יש הבדל עיקרי בין נפשו ו­ממונו<sup data-n=\"872\">10</sup>.\nב. וי\"ל הביאור בזה:\nנפשו וחייו של אדם נמסרו מהקב\"ה להאדם רק בתור פקדון, ולא לבעלות שלו. וכפסק רבינו הזקן בשלחנו<sup data-n=\"873\">11</sup> ד\"אין לאדם רשות על גופו כלל להכותו כו'\". ועפ\"ז, זה שאדם מוזהר שלא להזיק את גופו אינו רק ענין של איסור, אלא זהו גם מדיני קנינים — שאין לו רשות (בעלות<sup data-n=\"874\">12</sup>) על גופו (כי הגוף קניינו של הקב\"ה שנמצא אצל האדם בתור פקדון).",[["862","1","הל' סנהדרין ספי\"ח."],["863","2","ל' הכתוב — פרשתנו יז, ו."],["864","3","גיטין מ, ב. וש\"נ."],["865","4","ברמב\"ם שם ממשיך בטעם \"שמא נטרפה דעתו כו' מן העמלין מרי נפש הוא כו'\", אבל הרי מסיים \"וכללו של דבר גזירת מלך היא\". וראה רדב\"ז ד\"הטעם שכתב רבינו לא שייך גבי מלקות ולפיכך כתב וכללו של דבר גזירת מלך היא\".\nולהעיר מרש\"י יבמות (כה, ב ד\"ה ואין), דלא אמרינן הודאת בע\"ד כו' \"לקנסא ולעונש מלקות וליפסל\" כי אין אדם משים עצמו רשע. ואכ\"מ."],["866","5","ראה גם רמב\"ם הל' רוצח פ\"א ה\"ד."],["867","6","יחזקאל יח, ד."],["868","*6","כ\"ה בדפוס ווארשא­ווילנא (וצילום ממנו) — שם נדפס פי' הרדב\"ז לראשונה. ולכאורה צ\"ל \"פלגי\", או \"פלגא\" וכיו\"ב."],["869","7","תהלים כד, א. וראה ברכות לה, סע\"א (ו­לקמן בפנים סעיף ג)."],["870","8","מצוה שכח. ועד\"ז בכמה מצות."],["871","9","חגי ב, ח. וראה מפרשים שם."],["872","10","בפשטות יש לחלק, שע\"י העברת ממון מרשות אדם אחד לשני אין זה היזק רכושו של הקב\"ה (כי באיזה רשות שיהי' הממון, כל היכא דאיתא הוא ברשותו ית'), משא\"כ ע\"י מיתה או מלקות גורמים היזק בקניינו של הקב\"ה.\nאבל מפשטות ל' הרדב\"ז משמע, שיש חילוק בין נפשות וממון בבעלות האדם, ד\"נפשו של אדם. . קנין הקב\"ה. . אבל ממונו הוא שלו\"."],["873","11","חלק חו\"מ הל' נזקי גוף ונפש ס\"ד."],["874","12","דלכאורה הול\"ל בקיצור \"כי אסור לאדם להכות את גופו כו'\", ומאריכות לשונו כי \"אין לאדם רשות על גופו כלל להכותו כו'\" מוכח, שזהו מפני שאין לו רשות ובעלות על גופו, כבפנים."]]],[1301550178,"משא\"כ ממונו של אדם, נמסר להאדם באופן שהוא נעשה בעליו של ממון זה (וע\"ד שנאמר<sup data-n=\"875\">13</sup> \"והארץ נתן לבני אדם\"). וזה ש\"צריך<sup data-n=\"876\">14</sup> להזהר במאודו שלא ל­אבדו ולא לקלקלו ולא להזיקו\" אינו מפני שהממון אינו שלו<sup data-n=\"877\">15</sup>, אלא זהו איסור<sup data-n=\"878\">16</sup>, שעובר על לאו דבל תשחית.\nואין זה סתירה למש\"נ \"לי הכסף ולי הזהב נאום ה'\" (וכיו\"ב) — כי בעלותו של הקב\"ה, שהיא מסובבת מזה שהוא ית' ברא את העולם ומנהיגו כו', הרי היא בעלות כללית, וגם לאחרי שהממון ניתן להאדם אינו יוצא מבעלותו של ה­קב\"ה<sup data-n=\"879\">17</sup>, ועד שיכול ליטלו ממנו<sup data-n=\"880\">18</sup>. [וע\"ד ובלשון רש\"י<sup data-n=\"881\">19</sup> (בנוגע לארץ, ולארץ יש­ראל בפרט) \"כל הארץ של הקב\"ה היא, הוא בראה ונתנה לאשר ישר בעיניו, ב­רצונו נתנה להם וברצונו נטלה מהם ו­נתנה לנו\" — דאף שלכתחלה \"נתנה להם\" בנתינה גמורה<sup data-n=\"882\">20</sup>, הנה אח\"כ \"ברצונו נטלה מהם ונתנה לנו\"]<sup data-n=\"883\">21</sup>.\nוכיון שיש לאדם בעלות בממונו — ל­כן הדין בו (בהממון) ש\"הודאת בעל דין כמאה עדים דמי\"; משא\"כ בכל דבר הנוגע לגופו ונפשו, שנשארו לגמרי ב­בעלותו של הקב\"ה ונמצאים אצל האדם רק בגדר פקדון — הרי אין האדם \"בעל\" עליהם ולכן אין מחייבים אותו על פיו מלקות וכיו\"ב.\nג. ויש להביא ראי' לחילוק זה בין נפשו (וגופו) של אדם וממונו — מדין ברכות הנהנין:\nאמרו חז\"ל<sup data-n=\"884\">22</sup> (והובא להלכה<sup data-n=\"885\">23</sup>) \"אסור לו לאדם שיהנה מן העוה\"ז בלא ברכה וכל הנהנה מן העוה\"ז בלא ברכה מעל. . כאילו נהנה מקדשי שמים שנאמר<sup data-n=\"886\">24</sup> לה' הארץ ומלואה\",\nאבל אין חייבין בברכת הנהנין אלא על דבר שגופו נהנה ממנו (אכילה שתי' וכו')<sup data-n=\"887\">25</sup>, משא\"כ כשיש לאדם הנאת ממון",[["875","13","תהלים קטו, טז. אבל ראה לקמן סעיף ג (והערה 37)."],["876","14","ל' אדה\"ז — שו\"ע שם הל' שמירת גו\"נ ובל תשחית סי\"ד."],["877","15","להעיר מהתחלת ל' אדה\"ז שם \"כשם שצריך להזהר בגופו כו' כך צריך להזהר במאודו כו'\", דמשמע ששווים הם. אבל י\"ל שההשוואה היא רק בנוגע לאופן הזהירות. וראה לקו\"ש חי\"ח ע' 466 (חידושים וביאורים ברמב\"ם הל' בית הבחירה ע' קד)."],["878","16","אף שי\"ל שטעם האיסור הוא מפני הבעלות הכללית שבו — ראה לקמן בפנים."],["879","17","ראה ראב\"ע תהלים שם."],["880","18","כלשון הרד\"ק חגי שם \"וברשותו היא לנטלו מזה ולתתו לזה\". וראה גם רש\"י ברכות (לה, ריש ע\"ב ד\"ה בזמן)."],["881","19","בראשית א, א."],["882","20","ראה לקו\"ש ח\"ה ע' 5 הערה 22."],["883","21","ולהעיר מבעלות המלך על מדינתו, דאף שכל הארץ היא ברשות המלך (ראה רמב\"ם הל' מלכים ספ\"ד. הל' עבדים פ\"ט ה\"ד. שו\"ע אדה\"ז חו\"מ הל' הפקר ס\"ג), ועד שבאופנים מסויימים מותר לו ליטול מרכושם של בני המדינה [ראה רמב\"ם הל' גזילה ואבידה פ\"ה הי\"א ואילך (ובסיום הפרק שם, שצ\"ל מלך \"שהסכימו עליו בני אותה הארץ וסמכה דעתן שהוא אדוניהם כו'\". וראה קו\"א בשו\"ע אדה\"ז שם). הל' מלכים פ\"ד] — מ\"מ, אין בעלות (הכללית ד)המלך שוללת בעלותו הפרטית של כאו\"א מבני המדינה על רכושו הפרטי. וראה לקו\"ש ח\"ל ע' 85."],["884","22","ברכות לה, סע\"א."],["885","23","רמב\"ם הל' ברכות פ\"א ה\"ב. טאו\"ח סמ\"ו. שו\"ע אדה\"ז או\"ח סקס\"ז ס\"א. סדר ברכת הנהנין לאדה\"ז בתחלתו [ולהעיר, שהרמב\"ם (והטור) מביא \"מעל\", ואדה\"ז — \"כאילו נהנה מקדשי שמים\". וראה רש\"י ברכות שם ד\"ה מעל. צל\"ח שם (הובא גם בעץ יוסף לע\"י שם). לקו\"ש חכ\"ד ע' 67 הערה 8. ואכ\"מ]."],["886","24","תהלים כד, א."],["887","25","תוד\"ה אין (פסחים נג, ב). וראה רמב\"ן ברכות רפ\"ח \"שלא תקנו ברכה בהנאות שאינן נכנסות לגוף. . וריח נמי דבר הנכנס לגוף וסועד הוא וכאכילה ושתי' דמי\". ועד\"ז במג\"א סרט\"ז סק\"א. וראה לקו\"ש חי\"ד ע' 149 הערה *8."]]],[1301550179,"(קבלת ממון וכו') לא תקנו ברכה ע\"ז<sup data-n=\"888\">26</sup>.\nולכאורה אין זה מובן: מאי שנא הנאת הגוף מהנאת ממון — הרי בשניהם נהנה האדם מן עוה\"ז, עליו נאמר, כנ\"ל \"לה' הארץ ומלואה\", ולמה אינו מועל ע\"י ש\"נהנה מקדשי שמים\" כשהוא נהנה הנאת ממון בלא ברכה<sup data-n=\"889\">27</sup>?\n[ועם היות שמצינו כו\"כ מצות הנע­שות בנכסי האדם, ומטרתן היא (כמבואר בספרי טעמי המצות) להחדיר בהאדם את ההכרה ד\"לה' הארץ ומלואה\" (וכמו מצות שמיטה (שנה זו<sup data-n=\"e3\">*</sup>), שענינה \"שיראה ממעשה האדם. . כאילו אין דבר מיוחד ברשותו רק שהכל ברשות אדון הכל\"<sup data-n=\"890\">28</sup>; וכן מתנות כהונה, מעשרות וכו' — שתוכנם \"למען דעת שהכל שלו\"<sup data-n=\"891\">29</sup>) — מ\"מ מובן ופשוט שאין הענין דומה כלל לברכת הנהנין, שהרי המצוה היא שהאדם ברצונו יפקיר שדהו בשמיטה וכו'.\nולהעיר אשר מצות אלו הן בנוגע חלק מנכסי האדם<sup data-n=\"892\">30</sup>, משא\"כ דין ברכות הנהנין הוא — שאסור ליהנות שום הנאה (ואפילו כל שהוא<sup data-n=\"893\">31</sup>) בלא ברכה. ולכ­אורה אינו שייך לנדו\"ד].\nוע\"פ משנת\"ל — בההבדל בגדר בעלות האדם על ממונו או על נפשו וגופו — יש לומר:\nבנוגע לנפשו וגופו של אדם, שהם \"קנין הקב\"ה\" באופן שאין לאדם בעלות עליהם, הרי גם הנאות שלהם הן כמותם<sup data-n=\"894\">32</sup> — קניינו של הקב\"ה, ולכן הן \"קדשי שמים\" שאסור ליהנות מהם בלא ברכה.\nוהא דאיתא בגמ'<sup data-n=\"884\">22</sup> שרק קודם ה­ברכה הם \"קדשי שמים\", אבל לאחרי הברכה ה\"ה במצב ד\"והארץ נתן לבני אדם\"<sup data-n=\"896\">33</sup> (\"הרי היא לבני אדם\"<sup data-n=\"897\">34</sup>) — אין הכוונה בזה שע\"י הברכה נשתנו להיות קניינו של האדם (שהרי גם אח\"כ אומ­רים \"ברוך שאכלנו משלו\"<sup data-n=\"898\">35</sup>), אלא שע\"י",[["888","26","ואף שחייב אדם לברך על כל טובה שהגיעה לו (ברכות נט, ב. רמב\"ם הל' ברכות פ\"י ה\"ז. סדר ברה\"נ לאדה\"ז רפי\"ב: כל שמחת לבב כו') — הרי אין זו ברכת הנאה, להתיר לו הנאה זו, אלא רק מברכות הודאה \"דרך שבח והודי' להקב\"ה\" (רמב\"ם שם בריש הפרק. וראה שם פ\"א ה\"ג­ד). וצע\"ק בס' כד הקמח להבחיי (אות זיי\"ן), דמשמע דגם ברכות הראי' כו' הן מטעם דאסור ליהנות מן העוה\"ז בלא ברכה. ע\"ש. וראה לקמן הערה 64."],["889","27","בפשטות י\"ל הטעם שתיקנו ברכה רק על אכו\"ש, מפני דכעין דאורייתא תיקנו — ברכת המזון (וראה ל' הרמב\"ם ול' אדה\"ז (בשו\"ע וסדר ברה\"נ) דלעיל הערה 23)."],["890","28","ל' החינוך מצוה שכח (ועד\"ז בעוד מצות השייכות לשמיטה)."],["891","29","ל' החינוך מצוה יח (בכור)."],["892","30","וראה לקו\"ש חי\"ז ע' 230 ואילך. חי\"ח ס\"ע 221 ואילך."],["893","31","ראה ברכות שם בתחלת הסוגיא: אסור. . שיטעום כלום. רמב\"ם הל' ברכות פ\"א ה\"ב. טאו\"ח ר\"ס רי. סדר ברכת הנהנין לאדה\"ז פ\"ח ס\"י."],["894","32","ראה רמב\"ן ומג\"א שבהערה 25, שההנאה צ\"ל \"דבר הנכנס לגוף\"."],["884","22","ברכות לה, סע\"א."],["896","33","תהלים קטו, טז."],["897","34","רש\"י ברכות שם (לה, סע\"א). וראה בהערה 37."],["898","35","ברכות נ, א (וראה סוטה י, ריש ע\"ב. ועוד). וראה חינוך שבהערה 37. עיון יעקב לע\"י ברכות שם.\nומ\"ש בירושלמי (ברכות רפ\"ו) שע\"י הברכה \"כביכול כאילו משלך אכלת\" (ובפי' מבעל ס' חרדים שם \"שקנית אותה בברכתך\") — הרי מדייק \"כביכול כאילו\" [אלא שביל\"ש תהלים (רמז תרסז — ממדרש ילמדנו) \"משלך אכלת\" — בלי \"כביכול כאילו\"]."],["e3","*","תשמ\"ז — שנת הדפסת השיחה. המו\"ל."]]],[1301550180,"הברכה נפקע מהם דין \"קדשי שמים\" (ש­אסור בהנאה)<sup data-n=\"899\">36</sup> ומותר ליהנות מהם, אבל אין הוא נהנה משלו אלא משל הקב\"ה<sup data-n=\"900\">37</sup>, והקב\"ה נותנם לו באופן שיהי' שלו<sup data-n=\"901\">38</sup>, גם ע\"מ שיאכלם (יאבדם) וכו'.\nמשא\"כ נכסי האדם וממונו (מצד עצמם) מלכתחילה אינם בגדר \"קדשי שמים\", כי נמסרו לבעלותו של האדם, ולכן אין צריך ברכה להתיר הנאת ממון [אלא שכדי שהאדם יכיר שאין בעלותו מפקיעה ח\"ו בעלות (הכללית של) הקב\"ה על ממונו, ניתנו לו מצוות בממונו כו' \"למען דעת שהכל שלו\" (כנ\"ל)].\nד. אלא שלכאורה הא גופא טעמא בעי: מאי שנא ממונו של אדם שניתן לו באופן שיש לו בעלות עליו, ואילו נפשו וגופו נשארים \"קנין הקב\"ה\", ועד \"שאין לאדם רשות עליהם כלל\"?\nלכאורה י\"ל שזוהי כוונת הרדב\"ז בסיום דבריו \"ועם כל זה אני מודה ש­היא גזירת מלכו של עולם ואין להרהר\", כי ההבדל הנ\"ל בין נפשו של אדם וממונו אינו ענין שכלי, אלא כך היא \"גזירת מלכו של עולם\" שנתן רשות ובעלות לאדם על ממונו ולא על נפשו וגופו.\nאבל, בלשון הרדב\"ז \"אפשר לתת קצת טעם\" גם לזה:\nמצד הקב\"ה אין חילוק כלל בין נפשו וגופו של אדם לממונו, כי כל העולם ומלואו של הקב\"ה הוא בשווה ממש, אבל יש נפק\"מ ביניהם מצד האדם:\nבנוגע לגופו ונפשו — ניתנו לו באופן שניכרת בהם בעלותו של הקב\"ה, כי בכל יום אומר \"נשמה שנתת בי\" מח­דש<sup data-n=\"902\">39</sup>, מחוייב בתומ\"צ<sup data-n=\"903\">40</sup> וכו' וכו' ונרגשת בגופו קדושתה של הנשמה, וגם בגופו<sup data-n=\"904\">41</sup>",[["899","36","ולהעיר גם מירושלמי שם \"הנהנה כו' מעל עד שיתירו לו המצות\" (וראה פני משה שם), \"העולם כולו ומלואו עשוי ככרם ומהו פדיונו ברכה\" (וראה פירוש מבעל ס' חרדים שם)."],["900","37","וי\"ל שזוהי כוונת רש\"י שם ד\"ה לאחר ברכה \"הרי היא לבני אדם\" — דלכאו' מאי קמ\"ל, ומה מוסיף על ל' הש\"ס? — אלא הדיוק, שאין ה­כוונה שע\"י הברכה ניתן הדבר לבעלותו של האדם, אלא שע\"י הברכה \"הרי היא לבני אדם\" — שמותרים ליהנות ממנו.\nוראה חינוך מצוה תל \"עשו הברכה עד\"מ כנטילת רשות מן בעה\"ב לאכול מן הנמצא בביתו\"."],["901","38","ההדגשה כאן הוא לא ענין של בעלות, כ\"א שהקב\"ה נותנם שיהא שלו — בדוגמא שהאדון נותן להעבד מנכסי האדון לאבד (או להעשות דם ובשר העבד)."],["902","39","שנפשו היא \"חלק אלקה ממעל ממש\" (תניא רפ\"ב)."],["903","40","שזה תלוי בגמר כניסת נפש הקדושה בגוף (עיין שו\"ע אדה\"ז חאו\"ח מהד\"ת סוס\"ד). והיינו, שחיוב התומ\"צ הוא לא מצד דגופם קדוש (ראה הערה הבאה), הקדושה שבהגוף מצ\"ע [שמפני קדושה זו דהגוף גם תינוק מישראל (משא\"כ גוי), מיד כשנולד מקבל טומאה כו' (רמב\"ם הל' טומאת מת פ\"א הי\"ד). ועוד], כ\"א מפני שהגוף הוא \"כלי של קדש\" (ל' אדה\"ז בשו\"ע שם) — כלי שנכנס בו קודש (נפש הקדושה).\nלאידך י\"ל דתלוי בהסברת פטור הקטן מתו\"מ — אם זהו מפני תורה לדרדקי בתמי' — שלא ניתנה לקטן מעיקרא (ומושבע ועומד כו' מצד הנשמה, כמו שמשביעין אותו תהא צדיק כו' מלמדין אותו את כל התורה כולה כו') או שגם קודם המילה יש לו שייכות וקשר לתומ\"צ. ולהעיר מדיני הנולד לאחרי שכלו לו חדשיו קודם מילתו ועוד. וכבר האריכו באח­רונים. ואכ\"מ."],["904","41","וכמ\"ש בזח\"ג (ע, ריש ע\"ב) \"גופא דילהון קדישא\". וראה שבת (פו, ב) החילוק בדין בין גופי ישראל וגופי אוה\"ע. ובכ\"מ."]]],[1301550181,"של איש ישראל יש קדושה<sup data-n=\"905\">42</sup>, ומכיון שנבראו באופן שבעלותו של הקב\"ה ניכרת בהם, הרי לא יתכן שיהי' להאדם דין בעלות עליהם;\nמשא\"כ ממונו הוא באופן שאין בו קדושה (זו) ולא ניכרת בו בעלותו של הקב\"ה<sup data-n=\"906\">43</sup> — וכיון שהתורה ניתנה למטה בארץ דוקא<sup data-n=\"907\">44</sup> (במקום שבעלותו של הקב\"ה בהנ\"ל אינה ניכרת בו), לכן, ב­דיני התורה יש להאדם רשות ובעלות על ממונו ונכסיו [אלא שעליו לדעת ולהכיר, שבעלות זו גופא ניתנה לו משמים (הקב\"ה) ד\"לה' הארץ מלואה\", כנ\"ל].\nה. ע\"פ זה יש לבאר עוד חילוק בין דיני ממונות לדיני נפשות:\n\"דבר<sup data-n=\"908\">45</sup> תורה אחד דיני ממונות ואחד דיני נפשות בדרישה וחקירה. . ומה טעם אמרו דיני ממונות לא בעינן דרישה וחקירה כדי שלא תנעול דלת בפני לווין\" (\"שימנעו מלהלוות שמא יכפור והעדים יטעו ולא תהא עדותם מכוונת ויפסיד\"<sup data-n=\"909\">46</sup>).\nוהנה בפשטות — הטעם לזה שע\"פ \"דבר תורה\" גם דיני ממונות בדרישה וחקירה ולא חששה תורה ל\"תנעול דלת בפני לווין\"\nובכללות — הטעם לריבוי הענינים ד­עשו חכמים סייג לתורה, ולגזירות חכ­מים מפני שחששו למכשול וטעות וכו' ומדאורייתא ליכא חששא —\nיש לומר, משום שדיני התורה הם ע\"פ הכלל דכל ישראל בחזקת כשרות<sup data-n=\"910\">47</sup>, והנהגתם כמתאים לזה<sup data-n=\"911\">48</sup> ואין מקום לחשש וכו' ובנדו\"ד לחשש \"שמא יכפור\" הלוה<sup data-n=\"912\">49</sup> ויצטרך המלוה לעדים;\nאבל כשרבו<sup data-n=\"913\">50</sup> הרמאין כו', ויש חשש שמא יכפור הלוה כו', אז ראו חכמים צורך לתקן תקנות כדי \"שלא תנעול דלת בפני לווין\". ועד\"ז בכללות החש­שות והגזירות<sup data-n=\"914\">51</sup> — כשראו שהראשונים<sup data-n=\"915\">52</sup> כמלאכים ואחרונים כבנ\"א ואם הראשו­נים כבנ\"א אחרונים כו'.\nוי\"ל ששינוי המצב מחמת ירידת הדורות הוא (לא רק בזה שרבו הלווין הרמאין כו', אלא) גם מצד המלוה — חשש שהמלוה ימנע מלהלוות כי ירא \"שמא יכפור הלוה\" וכו',\nאבל מצד \"דבר תורה\" (המתייחס למצבו של איש ישראל כפי שהוא כד­בעי, כמלאכים וכבנ\"א) אין מקום לחשש זה.",[["905","42","ובפרט ע\"פ המבואר בתניא (ספמ\"ט) ד\"ובנו בחרת מכל עם ולשון הוא הגוף החומרי\"."],["906","43","דאל\"כ לא הי' ענין של בחירה. ותורה ניתנה בארץ דוקא ש\"יצה\"ר יש ביניכם\" (כבהערה הבאה)."],["907","44","ראה שבת (פט, רע\"א) \"משא ומתן. . קנאה. . יצר הרע יש ביניכם\"."],["908","45","סנהדרין ב, סע\"ב ואילך (וש\"נ). רמב\"ם הל' עדות רפ\"ג."],["909","46","רש\"י סנהדרין ג, רע\"א ד\"ה שלא תנעול."],["910","47","רמב\"ם הל' קדוה\"ח פ\"ב ה\"ח (וראה נו\"כ שם). השגות הראב\"ד הל' גירושין פ\"י הי\"ט. ובכ\"מ. וראה אנציקלופדי' תלמודית בערכו. וראה רמב\"ם הל' גירושין ספ\"ב."],["911","48","באופן ד\"עשה האלקים את האדם ישר\" (קהלת ז, כט)."],["912","49","אף שהבחירה נתונה לכל אדם כו', ולכן אמרה תורה דיני גניבה וגזילה וכו'."],["913","50","ב\"מ כח, ב."],["914","51","ראה לקו\"ת (דרושים לר\"ה נז, ג) \"שרוב הגזירות והחומרות והסייגים היו בזמן בית שני\". וראה אוה\"ת בראשית (כרך ג' תקנא, א ואילך. תקעג, א) בנוגע למאה ברכות שהתקין דוד (במדב\"ר פי\"ח, כא). ועוד."],["915","52","שבת קיב, ב."]]],[1301550182,"וי\"ל הסברת הענין:\nמצד \"דבר תורה\" — אין כל ממונו של אדם ברשותו ובבעלותו לגמרי, אלא רק חלק זה שמשתמש בו לדברי רשות (בל' המשנה<sup data-n=\"916\">53</sup> \"כל מעשיך\"), דכיון שנמסר לו להשתמש בו כפי רצונו (לדברים המותרים ע\"פ שו\"ע) ה\"ה ברשותו ובבעלותו; משא\"כ הממון שבו צריך האדם לקיים מצוות, מלכתחילה לא ניתן לבעלותו של האדם והוא רק בתור פקדון אצלו (כמו נפשו) בכדי שיוכל לקיים בו חפצי שמים. וע\"ד ביאור כ\"ק מו\"ח אדמו\"ר<sup data-n=\"917\">54</sup> בנוגע לצדקה (ולכספי מלוה) \"דזה מה שהעשיר חונן להעני הרי אין<sup data-n=\"918\">55</sup> שלו כלל והוא של ה' הנמצא אצלו בפקדון על עת וזמן קבוע\".\nולכן אין מקום אז לחשש ד\"תנעול דלת בפני לווין\" — כי כאשר באה לידו אפשרות של קיום מצות גמ\"ח (ע\"י הלוואה), בודאי יזדרז לקיים את ציווי הקב\"ה להלוות את העני, ולא ימנע א\"ע מלהלוות משום חששא<sup data-n=\"919\">56</sup> ד\"שמא יכפור\", מאחר שהוא יודע ומכיר שאין הממון שלו כ\"א של הקב\"ה שציווהו להלוות לעניים (וזימן לידו עני זה).\nוי\"ל שזהו הרמז בזה שאמרו \"דבר תורה אחד דיני ממונות ואחד דיני נפשות כו'\": כאשר מעמדו של האדם הוא כדבעי (\"דבר תורה\"), ה\"ה מרגיש שבאמת אין חילוק בין עניני נפשו וממונו, בידעו שגם הממון שניתן לרשותו הוא של הקב\"ה.\nאבל לאחרי ירידת הדורות כו' (שגם העולם \"ירד\" ונעשה חומרי יותר), נשתנה מצב האדם (והעולם) באופן שיש חילוק בין \"דיני נפשות\" ו\"דיני ממונות\", אינו מרגיש שממונו אינו שלו כ\"א של הקב\"ה, ולכן אז \"אמרו דיני ממונות לא בעינן דרישה וחקירה כדי שלא תנעול דלת בפני לווין\".\nו. עפ\"ז יומתק עוד פרט בהלכה זו:\nההלכה שבדיני ממונות לא בעינן דרישה וחקירה היא, לכמה דיעות<sup data-n=\"920\">57</sup>, לא רק בהלוואות והודאות (שבהן שייך החשש ד\"תנעול דלת בפני לווין\"), אלא גם \"גזילות<sup data-n=\"921\">58</sup> וחבלות וכתובת אשה וירושות ומתנות בכולהו נמי לא בעינן דרישה וחקירה, כדי שתנעול דלת בפני גזלנין\" (שיגזלו על סמך שלא ימצאו עדים המכוונים עדותם<sup data-n=\"922\">59</sup>).\nולכאורה לדיעות אלו צע\"ק: למה נקט הש\"ס הטעם ד\"לא תנעול דלת בפני לווין\" (השייך רק בהלוואות והודאות), ולא (גם) הטעם ד\"תנעול דלת בפני גזלנין\" (ובפרט שטעם זה שייך גם ב­הלואות והודאות — לנעול דלת בפני הרוצה לכפור במלוה על סמך שלא ימצא עדות מכוונת)?\nוע\"פ הנ\"ל יש לומר, שבזה משמיענו חידוש בנוגע ל\"דבר תורה\" — שבהנהגה הדרושה מצד \"דבר תורה\" הנה לא זו בלבד שאז אין מקום לחשש של גזל וכפירה כו', אלא עוד זאת, שאין חילוק",[["916","53","אבות פ\"א מי\"ב."],["917","54","סה\"מ קונטרסים ח\"א (קיט, א). וראה טור יו\"ד ריש הל' צדקה."],["918","55","כ\"ה בהנדפס. ולכאורה צ\"ל \"אינו\" (או: אין זה)."],["919","56","ע\"ד ציווי התורה (פ' ראה טו, ט ואילך) \"השמר לך פן. . ולא תתן לו. . נתון תתן לו ולא ירע לבבך בתתך לו\" (אף שחושש שלא יקבל את ממונו בחזרה)."],["920","57","פי' הא' בתוד\"ה שלא — סנהדרין שם. וכ\"כ הר\"ן שם. וראה בפרטיות אנציקלופדי' תלמודית ערך דרישה וחקירה (ע' תרנג) וש\"נ."],["921","58","ל' התוס' שם."],["922","59","ראה ר\"ן שם."]]],[1301550183,"אצל האדם (המלוה) בין \"דיני נפשות\" ו\"דיני ממונות\", כי מכיר שממונו אינו שלו כ\"א של הקב\"ה,\nוזה מודגש בהטעם ד\"לא תנעול דלת בפני לווין\" (שאינו נועל דלת מפני הלוה מחמת חשש כו'), כנ\"ל בארוכה.\nז. כתיב<sup data-n=\"923\">60</sup> \"אתם עדי נאום ה'\", שבנ\"י מעידים, כביכול, על מציאותו יתברך שבעולם.\nענין<sup data-n=\"924\">61</sup> העדות הוא לגלות דבר הס­תום. שהרי בדבר הנגלה לעין כל, אין צורך לעדות, וגם במילתא דבעתיד עבי­דא לגלויי<sup data-n=\"925\">62</sup> לא הצריכה התורה עדות, אלא העדות הוא על \"דבר הנעלם ל­גמרי\".\nוכן בעניננו: זה שבנ\"י נק' \"עדי\" (של הקב\"ה) הוא לפי שתפקידם הוא לגלות מציאות השם גם בעניני העולם, שגם ב\"עולם\" (לשון העלם<sup data-n=\"926\">63</sup>) המעלים ומסתיר על בעלותו של הקב\"ה — ועד שע\"פ תורה ניתנו עניניו לרשותו ובעלותו של האדם — צריך לגלות שהכל<sup data-n=\"927\">64</sup> נמצא רק \"מאמיתת המצאו\"<sup data-n=\"928\">65</sup>, ולכן באמת אין שום מציאות (אמיתית) זולתו יתברך, \"אין עוד מלבדו\"<sup data-n=\"929\">66</sup>.\nוכידוע הסיפור מאחד מגדולי חסידי אדמו\"ר הזקן (ר' בנימין קלעצקער), בעל עסקים במסחר עצים, שפעם כשעשה חשבון במו\"מ הסחורות כו', הרי בהגיעו לכתיבת ה\"סך­הכל\" של כל החשבון — כתב: \"אין עוד מלבדו\".\nמובן וגם פשוט, דזה שהחסיד הנ\"ל כתב כן הוא מפני שככה הרגיש באמת, שזהו הסה\"כ של העסק שעשהו בפו\"מ, והיינו,\nשהענין ד\"אין עוד מלבדו\" הי' חדור בכל מציאותו ובכל עניניו, ולכן בשעה שהגיע לה\"סך הכל\" בעניני מסחרו — כתב האמת (לאמיתו) \"אין עוד מלבדו\".\nובעומק יותר — ובהקדם השאלה: מאחר שהענין ד\"אין עוד מלבדו\" הי' חקוק תמיד על לבו של החסיד הנ\"ל — מדוע כתב זה רק בשורה האחרונה של החשבון, ואילו בשורות הקודמות רשם פרטי המספרים והסחורות כו' כרגיל? — הי' לו לכתוב זאת בכל שורה ושורה (במקום מספרי הסחורות כו')!\nוהביאור בזה<sup data-n=\"930\">67</sup> — דאדרבה, זהו ה­חידוש (בסיפור הנ\"ל):",[["923","60","ישעי' מג, י. שם, יב. וראה זח\"ג פו, א. ביאוה\"ז בהוספות (קלט, א ואילך). אוה\"ת שמות ע' לט ואילך. ס' הליקוטים­דא\"ח צ\"צ ערך עדות. וראה בארוכה לקו\"ש חי\"ט ע' 190 ואילך."],["924","61","ראה בכ\"ז לקו\"ת פקודי ד, סע\"א ואילך. ד\"ה ויקם עדות ה'ש\"ת פ\"א (סה\"מ ה'ש\"ת ע' 51 ואילך)."],["925","62","ר\"ה כב, ב. וש\"נ."],["926","63","לקו\"ת במדבר ה, ג (ע\"פ קה\"ר פ\"ג, יא (ג)). שלח לז, ד. ועוד. וראה תקו\"ז תמ\"ב. ס' הבהיר ס\"י (ח) (הובא בשל\"ה מס' שבועות קפה, סע\"ב). ובביאוה\"ז להצ\"צ ע' שנה: עולם ל' העלם כמארז\"ל (פסחים נ, א) ע\"פ (שמות ג, טו) זה שמי לעלם (לשון העלם ש)לא כמו שנכתב כו'."],["927","64","ולהעיר מתנחומא (ס\"פ ברכה) \"הצדיקים מברכין על כל דבר ודבר שאוכלין ושותין ושרואין וששומעין\" (ובתנחומא באבער שם סתם \"על כל דבר ודבר\"). וי\"ל שזהו מפני שמרגישים שהכל הוא בבעלותו של הקב\"ה, וע\"ד הנ\"ל (סוס\"ו) בפירוש \"דבר תורה אחד דיני ממונות ואחד דיני נפשות כו'\"."],["928","65","רמב\"ם ריש הל' יסוה\"ת."],["929","66","ואתחנן ד, לה. וראה בארוכה תניא ח\"ב פ\"ג."],["930","67","נוסף על הביאור שע\"פ תורה צ\"ל (שבת לא, סע\"א) נשאת ונתת באמונה (בפשטות — הנהג בהם מנהג ד\"א — ברכות לה, ב) אלא שהסה\"כ וה­מסקנא צ\"ל — (בכל דרכיך) דעהו וע\"ד: שש שנים תזרע גו' ובשביעית — הסה\"כ — שבת לה'."]]],[1301550184,"ודאי הדבר שכאו\"א מבנ\"י (שבחזקת כשרות הם) ביכלתו להרגיש ש\"אין עוד מלבדו\", ע\"י שיתבונן היטב איך ש\"כל הנמצאים כו' לא נמצאו אלא מאמתת המצאו\"<sup data-n=\"928\">65</sup> וכיו\"ב. אמנם להכרה זו יכול הוא להגיע בשעה שהוא מתבונן כו', ב­זמן התפלה והלימוד, בהיותו פרוש ו­מובדל מעניני העולם; אבל כאשר האדם עסוק בעניני מסחר כו', שע\"פ טבע העו­לם הם מעלימים ומסתירים על מציאותו יתברך, קשה לו להרגיש אז את הענין ד\"אין עוד מלבדו\".\nוזוהי ההדגשה בסיפור הנ\"ל<sup data-n=\"932\">68</sup>, שה­חסיד הי' אז, ע\"פ הציווי להתעסק בפרנ­סתו, במצב שכתב כל פרטי חשבונותיו בדיוק כו', היינו שעיסוקו אז לא הי' בעניני התבוננות בגדלות הא­ל כו', אלא בעניני מסחר, אלא שלהיותו כולו חדור בההכרה ד\"אין עוד מלבדו\", הרי גם תוך עשיית חשבון זה באה ההכרה לגילוי גמור במסקנת החשבון, שה\"סך­הכל\" וה­תכלית של כל מסחרו ועניניו הוא — \"אין עוד מלבדו\"<sup data-n=\"933\">69</sup>.\nוע\"י עבודה זו, לגלות בכל העולם כולו שיש מנהיג לבירה זו, עד לההכרה ש\"אין עוד מלבדו\" — זוכים למעמד ומצב שלא יהי' צורך בענין של \"עדות\" האמורה, כי יקויים היעוד<sup data-n=\"934\">70</sup> ד\"ונגלה כבוד ה' וראו כל בשר יחדיו כי פי ה' דבר\", בגאולה האמיתית והשלימה על ידי משיח צדקנו, ובמהרה בימינו ממש.\n<span data-k=\"q\">(משיחות י\"ט אדר וש\"פ ויק\"פ תשמ\"ה)</span>",[["928","65","רמב\"ם ריש הל' יסוה\"ת."],["932","68","וזהו החידוש שבסיפור זה אודות ר\"ב קלעצקער, לגבי המסופר אודותו במכתב כ\"ק מו\"ח אדמו\"ר (אגרות קודש שלו ח\"ו ע' שלג), שבאמצע עסקיו עמד כשבע שעות תפוס ברעיונותיו כו'. ע\"ש."],["933","69","והיינו שהסך­הכל של \"חשבון\" המסחר הוא — ש\"אין עוד מלבדו\"."],["934","70","ישעי' מ, ה."]]],[1301550185,"<h3>שיחה ג</h3>\nא. כתב הרמב\"ם בהל' מלכים<sup data-n=\"935\">1</sup>: \"ה­מלך המשיח עתיד לעמוד ולהחזיר מל­כות בית דוד ליושנה וכו' וכל מי שאינו מאמין בו או מי שאינו מחכה לביאתו לא בשאר נביאים בלבד הוא כופר אלא ב­תורה ובמשה רבינו שהרי התורה העידה עליו שנאמר<sup data-n=\"936\">2</sup> ושב ה' אלקיך את שבותך ורחמך ושב וקבצך וגו' אם יהי' נדחך בקצה השמים וגו' והביאך ה'. ואלו הדברים המפורשים בתורה הם כוללים כל הדברים שנאמרו על ידי כל הנבי­אים. אף בפרשת בלעם נאמר ושם נבא בשני המשיחים, במשיח הראשון שהוא דוד כו' ובמשיח האחרון שעומד מבניו כו'\" (ומביא כמה פסוקים מפרשת בלעם ומפרשם על דוד ועל מלך המשיח).\nובהלכה שלאח\"ז ממשיך הרמב\"ם: \"אף בערי מקלט הוא אומר<sup data-n=\"937\">3</sup> אם ירחיב ה' אלקיך את גבולך ויספת לך עוד שלש ערים וגו' ומעולם לא הי' דבר זה ולא צוה הקב\"ה לתוהו<sup data-n=\"938\">4</sup>, אבל בדברי נביאים אין הדבר צריך ראיי' שכל הספרים מלאים בדבר זה\".\nויש לעיין, מה חסר בראיות הראשו­נות (מהכתוב \"ושב גו'\" (שבפ' נצבים) ומפרשת בלעם), שהוזקק הרמב\"ם להו­סיף הראי' גם מהכתוב ב\"ערי מקלט\"?\nהצורך בשני ראיות הראשונות מובן, כי כוונת הרמב\"ם כאן (בהלכות מלכים) היא על האמונה במלך המשיח, היינו שנוסף על החיוב להאמין בכללות ענין הגאולה, שהקב\"ה עתיד לגאול את ישר­אל (באיזה אופן שהוא), חייבים להאמין במלך המשיח<sup data-n=\"939\">5</sup> (עם פרטי עניניו ומעלו­תיו המפורטים ברמב\"ם בפרק זה), כ­דיוק לשון הרמב\"ם \"וכל מי שאינו מאמין בו\"; ודבר זה אינו מפורש בפסוק \"ושב ה\"א את שבותך גו' וקבצך וגו' והביאך ה'\", אלא רק ב\"פרשת בלעם\" ש\"שם נבא בשני המשיחים\", דוד ומלך המשיח<sup data-n=\"940\">6</sup> [ומטעם זה מביא גם אריכות הראי', עם כו\"כ פסוקים המדברים בהם, כי בפסוקים אלה נרמזים גם פרטי עניניו ומעלותיו של מלך המשיח (ש­חייבים להאמין בהם), כמשנ\"ת במ\"א<sup data-n=\"941\">7</sup>].\nולאידך לא הסתפק בהראי' מפרשת בלעם, ועוד זאת, שהביאה רק כראי' שני' — כי אין כוונת הרמב\"ם כאן רק להביא ראיות מתורה שבכתב על ביאת",[["935","1","פי\"א ה\"א."],["936","2","נצבים ל, ג­ה."],["937","3","פרשתנו יט, ח­ט. וראה ספרי עה\"פ. תוספתא מכות ספ\"ב. ירושלמי שם פ\"ב ה\"ו."],["938","4","צע\"ק ממחז\"ל (סנהדרין עא, א) דבן סורר ומורה ועיר הנדחת \"לא הי' ולא עתיד להיות. . (אלא) דרוש וקבל שכר\". ואולי יש לחלק. ואכ\"מ."],["939","5","ולהעיר מדעת ר' הלל (סנהדרין צט, א) \"אין להם משיח לישראל\", ובפרש\"י (וראה גם חידושי הר\"ן) שם \"אלא הקב\"ה ימלוך בעצמו ויגאלם לבדו\" (ובראש אמנה לאברבנאל פי\"ד פירש זה באו\"א). ודברי הרמב\"ם הם לאחרי שהכריעו חכמים שלא כ­דבריו, שלכן האומר עתה כדעת ר' הלל הרי הוא כופר בכלל התורה (שו\"ת חת\"ס יו\"ד סשנ\"ו). וראה לקמן הערה 42."],["940","6","ולהעיר שבפיה\"מ הקדמה לפ' חלק (יסוד הי\"ב) הקדים הרמב\"ם הראי' מפרשת בלעם להא דפ' נצבים — \"ומי שהסתפק בו. . כפר בתורה שיעד בו בתורה בפירוש בפרשת בלעם ופרשת אתם נצבים\" (וי\"ל שנקט ע\"פ סדרם בקרא משא\"כ בהי\"ד שהוא ס' הלכות הלכות)."],["941","7","לקו\"ש חי\"ח ע' 281 ואילך."]]],[1301550186,"המשיח, אלא להוכיח ד\"מי שאינו מאמין בו. . כופר. . בתורה ובמשה רבינו ש­הרי התורה העידה עליו\", והעדות הזו אינה רק ע\"פ פירוש פסוקי התורה שב­תורה שבע\"פ [שגם \"הכופר בפרושה והוא תורה שבעל פה\" הוא בכלל \"כופר בתורה\"<sup data-n=\"942\">8</sup>], אלא \"אלו הדברים (ה)מפו­רשים בתורה\"<sup data-n=\"943\">9</sup> — ואילו נבואות בלעם נאמרו בדרך משל וחידה, בלשון שאי אפשר לומר ש\"הדברים (ה)מפורשים ב­תורה\"<sup data-n=\"944\">10</sup>; משא\"כ בפסוק הראשון שמפו­רש בו ע\"ד גאולה, קבוץ גליות וכו'.\nאבל צריך ביאור (כנ\"ל) — מה נוסף ע\"י הראי'<sup data-n=\"945\">11</sup> מהכתוב בערי מקלט<sup data-n=\"946\">12</sup>?\nגם יש לדייק, שהרמב\"ם כתב ראי' זו בהלכה בפ\"ע, ולכאורה הו\"ל לכללה בהלכה הקודמת ביחד עם ב' ראיות הראשונות<sup data-n=\"947\">13</sup>.\nב. ונראה לומר, שבראי' זו מערי מקלט יש חידוש עיקרי לגבי ב' ראיות הראשונות: בזה שציוותה תורה \"אם ירחיב גו' ויספת גו'\" (שבימות המשיח חייבים להוסיף בערי מקלט, בלשון הרמב\"ם<sup data-n=\"948\">14</sup> \"בימי המלך המשיח מוסיפין שלש אחרות על אלו השש\") — נעשה הענין דביאת המשיח א' מתנאי מצוה שבתורה.\nכלומר: אע\"פ שענין הגאולה העתידה מפורש בתורה (והרמב\"ם (בפירוש ה­משניות<sup data-n=\"949\">15</sup>) מנה האמונה בזה בין עיקרי ויסודי התורה), מ\"מ אין זה חלק ממצוות התורה, שהרי לא מצינו בתורה ציווי להאמין בהגאולה<sup data-n=\"950\">16</sup> (ורק כי כיון שזהו ענין המפורש בתורה, לכן כל שאינו מאמין בה, הרי הוא \"כופר. . בתורה וב­משה רבינו\"); אבל ע\"י הציווי ד\"אם יר­חיב גו' ויספת גו'\", נעשה ענין הגאולה אחד מפרטי מצוה בתורה.\nוע\"י שנעשה חלק ממצוה בתורה, יש בו גם התוקף שבענין המצוות. וכמ\"ש",[["942","8","רמב\"ם הל' תשובה פ\"ג ה\"ח."],["943","9","וראה בית אלקים (להמבי\"ט) שער היסודות פנ\"ב."],["944","10","ובראב\"ע בלק (כד, יז) פירש כל הכתובים רק על דוד. ע\"ש."],["945","11","ובפיה\"מ שם לא הביא ראי' זו. — ולכאורה אין כוונת הרמב\"ם בס' היד (ספר הלכה) להביא כל המקומות שבתושב\"כ שמפורש בהם ע\"ד הגאולה (ובפרט שלכאורה ישנם עוד — ראה ס' הגאולה להרמב\"ן שער א' \"ויותר חזק מזה בסוף התורה. . פ' האזינו\". וראה ויחי מט, י וברש\"י ורמב\"ן שם. ועוד)."],["946","12","בלקו\"ש שם (ע' 280) נת' שכוונת הרמב\"ם בראי' זו היא להוכיח עוד יותר שגדרו של משיח הוא שאז יהי' קיום התומ\"צ בשלימותן, שהרי מצוה זו תהי' בשלימות רק אז. ובמ\"א (לקו\"ש חכ\"ד ע' 109 ואילך) נת', שראי' זו היא גם הקדמה לדברי ה­רמב\"ם בהלכה שלאח\"ז, שמלך המשיח א\"צ \"לעשות אותות ומופתים ומחדש דברים בעולם\", שזהו בהתאם לדברי הרמב\"ם להלן שם (רפי\"ב) שבימות המשיח \"עולם כמנהגו נוהג\" — שהראי' לזה מתושב\"כ היא מערי מקלט לעת\"ל, שגם אז אפשרי ויהי' הורג נפש בשגגה (אבל ראה המשך השיחה שם).\nאבל פשטות ל' הרמב\"ם היא, שכוונתו להביא ראי' מתושב\"כ על עצם ביאת המשיח, כהמשך לשונו \"ומעולם לא הי' דבר זה ולא צוה הקב\"ה לתוהו, אבל בדברי הנביאים אין הדבר צריך ראי' שכל הספרים מלאים בדבר זה\"."],["947","13","ראה במקומות שנסמנו בהערה הקודמת."],["948","14","הל' רוצח פ\"ח ה\"ד (וראה הל' שמיטה ויובל רפי\"ג)."],["949","15","בהקדמה לפ' חלק."],["950","16","שזהו אחד מהטעמים שלא הביאו הרמב\"ם בס' היד בהל' יסודי התורה — כי \"בס' משנה תורה. . כוונתו. . לבאר המצות אשר בספר תורת האלקים. . הביא. . הלכות יסודי התורה לבאר אותם היסודות שיש בכללם מצות. . לא. . כל יסודי התורה\" (ראש אמנה פי\"ט)."]]],[1301550187,"הרמב\"ם בהלכות יסודי התורה<sup data-n=\"951\">17</sup> \"דבר ברור ומפורש בתורה שהיא מצוה עומ­דת לעולם ולעולמי עולמים אין לה לא שינוי ולא גרעון ולא תוספת\", ש\"מצוה\" פירושו ציוויי התורה, וכהמשך דברי ה­רמב\"ם \"שכל דברי התורה מצווין אנו לעשותן עד עולם\". וכן כתב גם בהלכות מלכים שם<sup data-n=\"952\">18</sup>, בהמשך הענין אודות ה­מלך המשיח, \"עיקר הדברים ככה הן, שהתורה הזאת חוקי' ומשפטי' לעולם ולעולמי עולמים ואין מוסיפין עליהן ולא גורעין מהן (וכל<sup data-n=\"953\">19</sup> המוסיף או גורע או שגילה פנים בתורה והוציא הדברים של מצות מפשוטן, הרי זה ודאי בדאי<sup data-n=\"954\">20</sup> ורשע ואפיקורוס)\".\nולכן, כיון שענין הגאולה הוא פרט במצות ערי מקלט, הרי כשם שערי מקלט \"היא מצוה עומדת לעולם כו' אין לה לא שינוי כו'\", כך אי אפשר להיות שינוי ח\"ו בהבטחה זו.\nועפ\"ז מובן גם דיוק לשון הרמב\"ם בראי' זו \"ולא צוה הקב\"ה לתוהו\"<sup data-n=\"955\">21</sup> — שכוונתו להדגיש, דכיון שזהו ענין של מצוה (\"צוה הקב\"ה\"), הרי זה מחייב שאי אפשר להיות שינוי ח\"ו בזה, כי \"לא צוה הקב\"ה לתוהו\".\nג. ליתר ביאור:\nבנוגע להבטחות הקב\"ה (ע\"י נביא) ישנם אופנים מסויימים ששייך שיחול בהם שינוי, כמו \"דברי הפורענות שה­נביא אומר\" שאפשר שיבטלו, מפני \"ש­הקב\"ה ארך אפים ורב חסד כו' [או כי] אפשר שעשו תשובה ונסלח להם\"<sup data-n=\"956\">22</sup>, וכן גם בהבטחה לטוב אם היתה רק \"בין הקב\"ה ובין הנביא\" אפשר שלא תתקיים אם \"יגרום החטא\"<sup data-n=\"957\">23</sup>;\nומזה מובן, שגם כאשר ברור ש­הבטחת הנביא תתקיים [כמ\"ש הרמב\"ם<sup data-n=\"958\">24</sup> \"שכל דבר טובה שיגזור הא­ל אפילו על תנאי אינו חוזר\", וכמו שביאר ב­פיהמ\"ש שלו<sup data-n=\"959\">25</sup> שכ\"שיאמר הקב\"ה לנביא להבטיח לבני אדם בבשורה טובה\" מוכ­רח הדבר להתקיים, ואין שייך שיתבטל מחמת חטא] — אין זה מפני שהבטחה שע\"י נביא בעצם אינה ניתנת לשינוי<sup data-n=\"960\">26</sup>, אלא מפני שהבטחות אלו אין בהם שינוי בפועל (וכמבואר ברמב\"ם שם, שזהו כדי שיוכלו לבחון אם נביא אמת הוא<sup data-n=\"961\">*26</sup>).",[["951","17","רפ\"ט. וראה גם הל' תשובה פ\"ג סוף ה\"ח (והל' מעשה הקרבנות ספ\"ב). פיה\"מ שם היסוד הט' (ובתרגום קאפח שם). וכן בהקדמתו לפיה\"מ (שמציין בפ' חלק שם). — וראה בארוכה סה\"ש תשנ\"ב ח\"א ע' 27 ואילך."],["952","18","סוף ה\"ג."],["953","19","כ\"ה בדפוסים שלא שלטה בהם בקורת הצנזור."],["954","20","בכת\"י תימן \"ה\"ז בודאי רשע כו'\"."],["955","21","ובפרט שלכאורה הי' אפשר להביא ראי' מעצם ההבטחה ד\"ירחיב ה\"א את גבולך\", שקאי על ארץ \"הקיני והקנזי והקדמוני שנכרת לאברהם אבינו ברית עליהן ועדיין לא נכבשו\" (רמב\"ם הל' רוצח שם)."],["956","22","רמב\"ם הל' יסוה\"ת פ\"י ה\"ד. וראה גם הקדמת הרמב\"ם לפיה\"מ. וראה ירושלמי סנהדרין פי\"א ה\"ה. תענית פ\"ב סה\"א. ב\"ר פנ\"ג, ד."],["957","23","פיה\"מ להרמב\"ם שם, ע\"פ ברכות ד, א. וראה הנסמן בהערה 25."],["958","24","הל' יסוה\"ת שם (מברכות ז, סע\"א). וראה הנסמן בהערה 22."],["959","25","בהקדמה שם. וראה גם מאירי לברכות ד, א. שו\"ת הרדב\"ז ח\"ג סי' א'סג. רא\"ם לפרש\"י וישלח (לב, ח), הובא בלח\"מ להל' יסוה\"ת שם. — וב(רא\"ם ו)גו\"א שם (וכן בצל\"ח ברכות שם) הקשו על חילוק זה ממחז\"ל עה\"פ \"עם זו קנית\" (ברכות שם. הובא לקמן בפנים ס\"ד). וכבר האריכו במפר­שים בחילוקים שונים. ואכ\"מ."],["960","26","ולהעיר מפסק הרמב\"ם (סוף הל' מגילה) ש\"כל ספרי הנביאים. . עתידין ליבטל לימות ה­משיח\". וראה הנסמן בהערה 34."],["961","*26","וראה דרשות הר\"ן דרוש ב."]]],[1301550188,"משא\"כ נצחיות התורה, ש\"עומדת ל­עולם ולעולמי עולמים\", הוא מפני שהיא למעלה מגדר שינוי, היינו שאי אפשר שישתנה, דכמו ש\"אני ה' לא שניתי\"<sup data-n=\"962\">27</sup>, שאין שייך בו ית' שינוי ח\"ו, כן גם בתו­רתו של הקב\"ה (שהיא חכמתו ורצונו של הקב\"ה), שאין שייך בה גדר שינוי<sup data-n=\"963\">28</sup>.\nומזה מובן לענין הבטחת הגאולה, דאף שלהיותה הבטחה לטוב ומה שאמר הקב\"ה לנביא \"להבטיח לבני אדם בבשורה טובה\" אי אפשר שיתבטל מפני גרימת החטא, כנ\"ל<sup data-n=\"964\">29</sup> [ועוד זאת, שמעיקרא לא שייך בנדו\"ד שיגרום החטא, שהרי (בלשון הרמב\"ם<sup data-n=\"965\">30</sup>) \"כבר הבטיחה תורה שסוף ישראל לעשות תשובה בסוף גלותן ומיד הן נגאלין שנאמר<sup data-n=\"966\">31</sup> והי' כי יבואו עליך כל ה­דברים וגו' ושבת עד ה\"א ושב ה\"א וגו'\", היינו שהובטחנו על זה גופא, שישראל יעשו תשובה (ולא יהי' מצב של \"יגרום החטא\")] — מ\"מ, הוודאות שבזה היא רק מצד גדרי הנבואה ואופנה; משא\"כ עי\"ז שהבטחת הגאולה היא חלק ופרט ממצוה בתורה, חל עלי' גדר נצחיות התורה — שהיא נצחיות שאין שייך בה שום ביטול.\nד. אלא שלכאורה עדיין יש מקום לשאלה:\nהרי הכלל של נצחיות התורה הוא בכל חלקי התורה<sup data-n=\"967\">32</sup>, ובפרט בחמשה חומשי תורה, וכמ\"ש הרמב\"ם<sup data-n=\"968\">33</sup> ש\"חמשה חומשי תורה. . אינן בטלין לעולם\", שכל הנכתב בתורת משה הוא נצחי וקיים לעולם; וא\"כ, כיון שהבטחת הקב\"ה על הגאולה מפורשת בתורת משה, כבר חל ע\"ז גדר הנצחיות של \"חמשה חומשי תורה\", ומה נתוסף בזה עי\"ז שהיא גם פרט ממצות התורה?\nוי\"ל כי יש חילוק עיקרי בין הנצחיות שבמצות התורה להנצחיות שבשאר חלקי תורה (שבכתב)<sup data-n=\"969\">34</sup>: בשאר חלקי ה­תורה אפשר שענין הנצחיות שבהם ית­קיים (לא כפשוטו, אלא) רק בתוכנם הרוחני (וע\"ד \"דברי הימים והסיפורים\"<sup data-n=\"970\">35</sup> שבתורה שבכתב, שהנצחיות שבהם היא ב\"חכמות ופלאים\"<sup data-n=\"970\">35</sup> הנרמזים בהם, ולא",[["962","27","מלאכי ג, ו."],["963","28","ראה בארוכה בזה — לקו\"ש חי\"ט ע' 182 ואילך. חכ\"ג ע' 33 ואילך."],["964","29","ובפרט שהגאולה אינה רק הבטחה (בתורה) אלא גם (בלשון) נבואה, כדיוק לשון הרמב\"ם \"ושם נבא בשני המשיחים\" — ראה גו\"א וישלח שם (וב­ספרו גבורות ה' פ\"ז), שיש חילוק בין הבטחה (סתם) ונבואה, שהבטחה אפשר שלא תתקיים מפני החטא, משא\"כ נבואה.\n[ועפ\"ז הי' אפשר לתרץ אריכות ל' הרמב\"ם \"אף בפרשת בלעם נאמר ושם נבא\"<sup data-n=\"e43\">*</sup>. אלא שהרמב\"ם לא ס\"ל כחילוק הגו\"א (שלכן הוצרך לחלק בין הב­טחת הקב\"ה לנביא עצמו או מה שמבטיח לאחרים). וראה לקו\"ש חי\"ח ע' 274 הערה 23 ובשוה\"ג שם. וראה לקמן סעיף ו]."],["965","30","הל' תשובה פ\"ז ה\"ה."],["966","31","נצבים ל, א­ג (הבטחת הגאולה שברמב\"ם הל' מלכים שם)."],["967","32","דכל אות ואות שבתורה, הן בתושב\"כ (גם נביאים וכתובים) והן בתושבע\"פ (גם אגדות שבה) היא חלק מתורת אמת ותורה הנצחית — ראה בארו­כה לקו\"ש חכ\"ג שם. וש\"נ."],["968","33","סוף הל' מגילה."],["969","34","שהרי כמה אופנים ודרגות ישנם בענין הנצחיות. וראה גם לקו\"ש חכ\"ו ע' 225, החידוש בנצחיות שבתורה שבכתב. ע\"ש. וראה הערה 36."],["970","35","ל' הרמב\"ם בפיה\"מ בהקדמה לפ' חלק היסוד השמיני."],["970","35","ל' הרמב\"ם בפיה\"מ בהקדמה לפ' חלק היסוד השמיני."],["e43","*","ולהעיר מקרית ספר (להמבי\"ט) להל' מלכים שם \"וכשם שנתקיימה נבואתו במשיח ראשון תתקיים באחרון\" (היינו שכוונת הרמב\"ם להדגיש הוודאות שתתקיים נבואה זו)."]]],[1301550189,"בהענינים כפשוטם, שהרי הם מאורעות שבעבר); משא\"כ זה שהתורה \"היא מצוה עומדת לעולם ולעולמי עולמים\", היינו, שציוויי התורה כפשוטם קיימים \"לעולם ולעולמי עולמים\" בלי שינוי גרעון או תוספת<sup data-n=\"972\">36</sup>.\n[וכדיוק לשון הרמב\"ם הנ\"ל \"וכל המוסיף כו' והוציא הדברים של מצות מפשוטן הרי זה ודאי בדאי ורשע ואפיקורוס\", דרק כאשר אומר על מצות התורה שאינן כפשוטן יש עליו גדר זה ד\"בדאי ורשע ואפיקורוס\"<sup data-n=\"973\">37</sup> (כי אז הוא כופר ביסוד של נצחיות התורה), משא\"כ כשמוציא שאר המקראות מידי פשוטן<sup data-n=\"974\">*37</sup> אין עליו גדר זה].\nוכשם שהוא בסיפורי התורה, כ\"ה גם בענין הבטחות הקב\"ה שנכתבו בתורה, שקיומן בפועל תלוי באופן ההבטחה לפי התנאים וגדרים שפירשו בחז\"ל, ואם נכתבה ההבטחה בלי תנאים אלה אינו ודאי שתתקיים לפי פשוטה דוקא.\n[וכדמצינו בפירוש, שהכלל שהבטחת הקב\"ה אפשר שלא תתקיים בפועל מפני \"שמא יגרום החטא\" חל גם על הבטחות המפורשות בתורה, כדאיתא בברייתא<sup data-n=\"975\">38</sup>: \"עד יעבור עמך ה' עד יעבור עם זו קנית<sup data-n=\"976\">39</sup>, עד יעבור עמך ה' זו ביאה ראשונה (שבאו (לארץ) בימי יהושע. רש\"י), עד יעבור עם זו קנית זו ביאה שני' (כשעלו מגלות בבל בימי עזרא. רש\"י), מכאן אמרו חכמים ראוים היו ישראל ליעשות להם נס בימי עזרא, כדרך שנעשה להם בימי יהושע בן נון אלא שגרם החטא\".\nולכאורה, כיון שהבטחה זו (\"עם זו קנית\") נכתבה בתורה שבכתב (לפני הזמן ד\"ביאה שני'\")<sup data-n=\"977\">40</sup>, והתורה הזאת לא תהי' מוחלפת ו\"אין לה לא שינוי ולא גרעון",[["972","36","ומובן, שזה מורה על סוג נעלה יותר בענין הנצחיות: ענינים שהנצחיות שבהם היא רק בתוכנם הרוחני (ואילו בגשמיות בטל הדבר), ה\"ז הוראה שיש איזו הגבלה בנצחיות עצמה, שה\"אמת\" שבהם היא ברוחניות ולא בגשמיות; משא\"כ במצוות והל­כות התורה, שהנצחיות היא (גם) בגשמיות כפשוטו, ה\"ז מפני שהנצחיות קשורה עם \"אמת ה'\" כפי שהיא למעלה מכל גדר שינוי כלל, שאין שום הגבלה וחילוקים בנצחיות זו (לחלק ולומר שהדבר נשאר קיים רק ברוחניות), אלא הוא מוכרח להת­קיים גם בעולם הזה, כפשוטו.\nוכמשנ\"ת במ\"א (לקו\"ש חכ\"א ע' 114 ואילך) ב­מעלת הלכות התורה<sup data-n=\"e44\">*</sup>, שדוקא הן נק' \"אמת ל­אמיתו\" דתורה (ראה סה\"מ תרכ\"ז (ע' רפב. רצא) והמשך תרס\"ו (ע' תלא), ע\"פ שבת י, א. וש\"נ), כי ה\"אמת\" שבהם היא (עד) למעשה בפועל."],["973","37","אף שי\"ל שהרמב\"ם מדייק כן, כי עיקר כוונתו בזה היא למ\"ש אח\"כ ע\"ד אותו האיש (בדפוסים ששלטה בהם בקורת הצנזור נשמט), שגרם \"להחליף התורה\", וכן ע\"ד ה\"ערלי לב. . (ש)נושאים ונותנים. . במצות התורה. . אמת היו וכבר בטלו בזמן הזה. . דברים נסתרים יש בהן ואינן כפשוטן\"."],["974","*37","וראה ברייתא דל\"ב מדות (מדה כו) \"אתה מוצא בנביאים ובכתובים שדברו במשל, בד\"א ב­דברי קבלה אבל בדברי תורה ומצוה אי אתה יכול לדורשן בלשון משל כו'\". וראה פי' מדרש תנאים (להמהרז\"וו) שם, שהכוונה שלא נדרוש לשנות פשוטה של הלכה (\"מצוה\"). ע\"ש."],["975","38","ברכות ד, א. סנהדרין צח, ב."],["976","39","בשלח טו, טז."],["977","40","משא\"כ בהא דיעקב הי' ירא שמא לא תתקיים הבטחת הקב\"ה כי יגרום החטא — שעדיין לא נכתבה אז בתורה."],["e44","*","והרי היסוד דנצחיות התורה שבהל' יסוה\"ת שם הוא גם בנוגע לפירוש המצות דתושבע\"פ (ראה שם ה\"א. וראה הל' תשובה פ\"ג ה\"ח. פיה\"מ ב­הקדמה לפ' חלק יסוד הט'). אלא שבסוף הל' מגילה, משווה הנצחיות ד\"הלכות של תורה שבע\"פ\" לחמשה חומשי תורה (בכלל). ואכ\"מ."]]],[1301550190,"ולא תוספת\", איך אפשר לומר שיחול שינוי בהבטחה זו ולא תתקיים בפועל (מאיזו סיבה שתהי')? וע\"כ צ\"ל, כי הגדר של נצחיות התורה אינו שייך בכלל ללימוד פי' הכתובים (האם זהו בגשמיות או ברוחניות, בכל אופן או בתנאי וכו')].\nוזהו החידוש בעניננו, שכיון שהבטחת הגאולה היא פרט ממצות ערי מקלט, חל עלי' גדר נצחיות מצות התורה, אשר (א) מוכרח להתקיים בפשטות ובגשמיות<sup data-n=\"978\">41</sup>, (ב) ובאופן שאין שייך בזה שינוי, כנ\"ל.\nה. ע\"פ כל הנ\"ל יש לבאר הטעם שהרמב\"ם מוסיף הראי' על מלך המשיח מהא ש\"אף בערי מקלט הוא אומר אם ירחיב. . ויספת. . ומעולם לא הי' דבר זה ולא צוה הקב\"ה לתוהו\":\nאין כוונת הרמב\"ם (רק) להביא עוד הוכחה מתורה שבכתב (חמשה חומשי תורה) על מלך המשיח, אלא בא להוסיף ענין חדש בחומר הדבר של \"מי שאינו מאמין בו\", דנוסף לזה ש\"כופר. . בתורה ובמשה רבינו\" מפני ש\"התורה העידה עליו\" — הרי הוא גם \"גורע\" א' ממצות התורה, שהרי לדעתו פרט זה של מצות ערי מקלט לא יתקיים, וחל עליו מ\"ש הרמב\"ם (בהלכה שלאח\"ז) \"הרי זה ודאי בדאי ורשע ואפיקורוס\".\n[ולכן כתב הרמב\"ם ראי' זו בהלכה בפ\"ע — כי בשתי הראיות הראשונות כוונתו להוכיח ד\"מי שאינו מאמין בו. . כופר. . בתורה ובמשה רבינו שהרי התורה העידה עליו\", ובראי' זו בא לרמז על חומר נוסף בענין זה, שהוא גורע ממצות התורה].\nאלא שלכאורה אם הוא \"כופר. . ב­תורה ובמשה רבינו\" מה מוסיף זה שהוא גורע ממצות התורה?\nאבל ע\"פ הנת\"ל יש לומר שיש נפק\"מ לדינא — ובהקדים ביאור דינו של ה­אומר שאינו מאמין בגאולה העתידה לבוא מפני שסובר שאף שהובטחנו על הגאולה, חל בזה שינוי ונתבטלה הבטחה זו (מפני החטא וכיו\"ב)<sup data-n=\"979\">42</sup>, שלכאורה אי אפשר לומר עליו ש\"כופר. . בתורה וב­משה רבינו שהרי התורה העידה עליו\" (שהכוונה בזה שכופר בדבר המפורש ב­תורה שבכתב, כנ\"ל בתחילת השיחה) — שהרי אינו כופר בהבטחה הכתובה בתורה, אלא ס\"ל שגם על הבטחה כזו שייך ענין החרטה (וצ\"ע אם יש לו דין כופר בתורה שבע\"פ);\nאבל כיון שהגאולה היא פרט וגדר במצות התורה, אשר \"היא מצוה עומדת",[["978","41","אלא לכאורה, כיון שפשטות המקראות דה­הבטחה דפ' נצבים קאי על הגאולה העתידה [משא\"כ בנבואות בלעם שאינו מפורש בפשט, כנ\"ל בתחילת השיחה. וכן הא ד\"עם זו קנית\"], א\"כ צריכה להתקיים בפשטות, כהכלל ד\"אין מקרא יוצא מידי פשוטו\" (יבמות כד, א. וראה שבת סג, א. וראה ב­פרטיות אנציקלופדי' תלמודית בערכו).\nאבל: (א) צ\"ע (ובפרט לדעת הרמב\"ם<sup data-n=\"e45\">*</sup>) אם כלל זה אמור גם בהבטחות התורה. (ב) ראה לקמן בפנים (סוף סעיף ה) נפק\"מ להלכה בזה שהיא תנאי ופרט במצוה. ועצ\"ע."],["979","42","וע\"ד דעת ר' הלל שאין להם משיח ליש­ראל שכבר אכלוהו בימי חזקי' (כנ\"ל הערה 5), שסבר שגרם החטא, אף ש\"התורה העידה עליו\" ו\"בדברי הנביאים. . כל הספרים מלאים בדבר זה\". — וראה שו\"ת הרדב\"ז (ח\"ד סי' א'רנח) ועיקרים בתחילתו."],["e45","*","שמדגיש (כנ\"ל) שרק אם \"הוציא הדברים של מצות מפשוטן ה\"ז כו'\". וראה רמב\"ם הל' מלכים רפי\"ב ובמגדל עוז שם. ולהעיר ממו\"נ (ח\"ב פכ\"ט­ל.ובכ\"מ). וידועות תשובות הרשב\"א בזה (ח\"א סתי\"ד­תיח. וראה שם ס\"ט \"באמת הרבה כתובים דברו דרך משל כו'\". ע\"ש). ואכ\"מ."]]],[1301550191,"לעולם ולעולמי עולמים\", שזה מכריח שאי אפשר להיות שינוי ח\"ו בהבטחת הגאולה, הרי באמרו היפך מזה, יש עליו דין כופר בתורה (כי אף שמאמין שה­ציווי \"ואם ירחיב גו' ויספת גו'\" הוא מן השמים, הרי באמרו שיתבטל פרט זה דהמצוה — \"כבר בטלה תורה זו\" — הרי הוא \"כופר בתורה\"<sup data-n=\"980\">*42</sup>).\nויש לומר עוד נפק\"מ — באומר שאינו מאמין בגאולה העתידה לבוא מפני ש­מפרש המקראות של הבטחת התורה שלא כפשוטם (שאומר שהגאולה תהי' רק ברוחניות וכיו\"ב), שלכאורה אי אפשר לומר עליו ש\"כופר. . בתורה וב­משה רבינו\", שהרי מודה דמה שכתוב בתורה הוא אמת, אלא שסובר שכוונת התורה אינה לפשטות הענין אלא שלא כפשוטו. וגם את\"ל שזהו היפך הכלל<sup data-n=\"981\">43</sup> ד\"אין מקרא יוצא מידי פשוטו\", צ\"ע אם אפשר לומר שחל עליו שם \"כופר בתו­רה ובמשה רבינו\" משום שמפרש מק­ראות שלא כפשוטם.\nאבל מצד זה שהגאולה היא פרט וגדר במצות התורה, אז באמרו שה­גאולה לא תהי' כפשוטה הרי הוא מוציא \"דברים של מצות מפשוטן\" וחל עליו הדין ד\"הרי זה ודאי בדאי ורשע ואפי­קורוס\".\nו. והנה בדרך זו יש לבאר עוד דיוק בלשון הרמב\"ם — שבהראי' מ\"פרשת בלעם\" אומר \"אף בפרשת בלעם נאמר ושם נבא בשני המשיחים\", שלכאורה אינו מובן טעם הדגשה זו ד\"ושם נבא\"<sup data-n=\"982\">44</sup> (שנאמר בדרך נבואה).\n[ודוחק גדול לומר, שכיון שמקדים שזהו \"בפרשת בלעם\", צריך להוסיף \"ושם נבא\" דאל\"כ מנא לן שיש אמת בדברי בלעם — שהרי כיון ש\"פרשת בלעם\" נכתבה בתורת משה<sup data-n=\"983\">45</sup>, מובן, ופשוט, שדברים אמיתיים הם<sup data-n=\"984\">46</sup>].\nויש לומר, שגם בזה כוונת הרמב\"ם היא להשמיענו חומרא נוספת במי שאינו מאמין במלך המשיח, שנוסף ע\"ז שהוא \"כופר. . בתורה ובמשה רבינו\", הרי הוא כופר גם בדברי נבואה.\nדאף שדברי תורה חמורים מדברי נביאים<sup data-n=\"985\">47</sup> — מ\"מ מצינו גם חומר בדברי נביאים לגבי דברי תורה, שהעונש על דברי תורה תלוי בסוג העבירה, אם היא עבירה קלה או חמורה כו', משא\"כ ה­עובר על דברי הנביא, אין נפק\"מ באיזה ענין עבר, ואפילו אם הוא בדברי ה­רשות, חייב מיתה בידי שמים<sup data-n=\"986\">48</sup>.\nויש לומר הטעם, משום שאע\"פ שה­תוקף של דברי תורה גדול הרבה יותר מהתוקף שבדברי נבואה — מ\"מ לגבי בני אדם, יש חומרא בדברי נבואה. כי הנבואה הוא מה ש\"הא­ל מנבא את בני האדם\"<sup data-n=\"987\">49</sup>, \"מדע שמגיע מהבורא ללב בני האדם\"<sup data-n=\"988\">50</sup>, וכיון שזהו גילוי דברו ל­בנ\"א<sup data-n=\"989\">51</sup>, לכן, בנוגע לפעולה לבני אדם יש בדברי נביאים תוקף וחומר לגבי",[["980","*42","הל' תשובה פ\"ג ה\"ח."],["981","43","נסמן לעיל הערה 41. וראה שם בשוה\"ג."],["982","44","ראה לעיל הערה 29."],["983","45","ובפרט ע\"פ הדגשת חז\"ל (ב\"ב יד, ב) \"משה כתב ספרו ופרשת בלעם\"."],["984","46","ראה גם ספר הגאולה להרמב\"ן שם."],["985","47","ראה חגיגה י, ב. וש\"נ. וראה אנציקלופדי' תלמודית ערך דברי קבלה."],["986","48","רמב\"ם הל' יסוה\"ת פ\"ט ה\"ב."],["987","49","ל' הרמב\"ם שם רפ\"ז. ע\"ש ובפיה\"מ הקדמה לפ' חלק היסוד הו'."],["988","50","שם הל' תשובה פ\"ג ה\"ח."],["989","51","ראה בארוכה בזה לקו\"ש חכ\"ג ס\"ע 85 ואילך."]]],[1301550192,"דברי תורה<sup data-n=\"990\">52</sup>. ומשום הכי, כששומע אדם ציווי מפי הנביא, הרי זה כאילו שומע הציווי מפי הקב\"ה, ובמילא לא משנה תוכן הציווי, ואם עובר עליו הרי הוא מורד במלך, שחייב מיתה<sup data-n=\"991\">53</sup> (ללא נפק\"מ באיזה ענין מרד).\nומזה מובן, שיש חומרא בענין הנבו­אה בכלל (לגבי דברי תורה), גם במקום שלא חל בפועל האיסור של עובר על דברי הנביא (כי לא שמע מפי הנביא וכו'). וזוהי כוונת הרמב\"ם כאן במ\"ש \"ושם נבא\", לרמז שמי שאינו מאמין במלך המשיח, יש בו גם משום חומרא זו<sup data-n=\"992\">54</sup>.\nועפ\"ז נמצא, שבשלש הראיות שהביא הרמב\"ם, מלמדנו, שענין מלך המשיח נאמר ונכתב בכל חלקי תורה שבכתב — הן בסיפורי (והבטחות) התורה, כמפורש בפ' נצבים; הן בנבואות שבתורה, כ­מפורש ב\"פרשת בלעם\" ש\"שם נבא\"; והן במצות שבתורה, כמפורש במצות ערי מקלט,\nולכן מי שאינו מאמין במלך המשיח, נוסף ע\"ז שהוא \"כופר. . בתורה ובמשה רבינו\", הרי הוא כופר גם כן בנבואות שבתורה, וכן כופר במצוות התורה, \"ה­עומדת לעולם ולעולמי עולמים\".\nז. ועדיין צריך ביאור — מאי טעמא נבחרה מצות ערי מקלט, שהענין דביאת המשיח הוא פרט במצוה זו דוקא?\nויש לומר בזה<sup data-n=\"993\">*54</sup>:\nענינם של ערי מקלט בפשטות הוא — מקום שמירה והגנה מגואל הדם, שב­היות האדם (שהרג בשגגה או גם בזדון) בעיר מקלט, לא יוכל לנגוע בו לרעה;\nוכשם שישנו ענין ה\"מקלט\" במקום, כן הוא בזמן, והוא \"אותו הזמן\"<sup data-n=\"994\">55</sup>, ש\"לא יהי' שם לא רעב ולא מלחמה ולא קנאה ותחרות\"<sup data-n=\"994\">55</sup>, שתהי' \"קליטה\" מכל הענינים הבלתי רצויים של זמן הגלות, וישראל יושבים בטח על אדמתם.\nועד\"ז ברוחניות הענינים — ובפרט ע\"פ הידוע<sup data-n=\"996\">56</sup> שהענין ד\"ערי מקלט\" מורה על הקליטה מהיצר הרע (שנקרא \"גואל הדם\"), וכמחז\"ל<sup data-n=\"997\">57</sup> \"דברי תורה. . קול­טין\". וכמו שעיר מקלט בפשטות היא גם כפרה<sup data-n=\"998\">58</sup> להורג נפש, כן הוא גם ברוח­ניות, שהורג נפש מרמז על כל מעשה",[["990","52","ראה גם לקו\"ש חי\"ט שם (ע' 184 ואילך), בטעם שהרמב\"ם מקשר ענין התורה עם נבואת משה. ע\"ש. וראה מו\"נ (ח\"ג פמ\"ה) \"אמונת הנבואה קודמת לאמונת התורה כי אם אין נביא אין תורה\"."],["991","53","ראה רמב\"ם הל' מלכים פ\"ג ה\"ח."],["992","54","דאע\"פ דזה ש\"כופר. . במשה רבינו\" היינו בפשטות שכופר \"בנבואתו של משה\"<sup data-n=\"e46\">*</sup> — ה\"ז מפני שהכופר בתורה כופר בדרך ממילא בנבואת משה (ראה רמב\"ם הל' יסוה\"ת פ\"ט ה\"א. שם ה\"ה. וראה בארוכה לקו\"ש חי\"ט שם), ומובן, שאינו דומה לענינים אלה שבתורה, שהם דברי נבואה באופן גלוי."],["993","*54","ראה בארוכה גם סה\"ש תנש\"א ח\"ב ע' 573 ואילך."],["994","55","רמב\"ם סוף הל' מלכים."],["994","55","רמב\"ם סוף הל' מלכים."],["996","56","ראה ל\"ת וש' הפסוקים להאריז\"ל פ' משפטים (בטעם שאלול ר\"ת \"אנה לידו ושמתי לך\" — משפטים כא, יג). וראה בארוכה לקו\"ש ח\"ב (ע' 380 ואילך. ע' 623 ואילך). ח\"ט ע' 297 ואילך. ועוד."],["997","57","מכות י, א."],["998","58","ראה מכות ב, ב. תוד\"ה מידי — שם יא, ב. ובכ\"מ. וראה רש\"י עה\"ת נח ט, ה."],["e46","*","עפמ\"ש בשו\"ת חת\"ס (נסמן בהערה 5) שפרשת בלעם היא הדבר היחידי שאין שום עד ראי' בדבר ואנו מאמינים בה אך ורק מפני נבואת משה — מובנת עוד יותר הדגשת הרמב\"ם \"כופר בתורה ובמשה רבינו\", כיון שהבטחת הגאולה היא \"בפרשת בלעם\"."]]],[1301550193,"עבירה, שעל ידה פוגם בנפשו, שדברי תורה שלומד פועלים קליטה וכפרה לנפשו.\nוזוהי השייכות של מצוה זו לביאת המלך המשיח<sup data-n=\"999\">59</sup>, כי אז תוגמר קליטתן וכפרתן של ישראל<sup data-n=\"1000\">60</sup> — במהרה בימינו ממש.\n<span data-k=\"q\">(משיחות ש\"פ דברים ור\"ח אלול תשמ\"ו; מוצאי ש\"פ פינחס תשל\"ח) </span>",[["999","59","ובאוה\"ת מסעי (ס\"ע א'תטו) שהוספת ערי מקלט לעת\"ל ענינה (ברוחניות) התגלות טעמי תורה ע\"י משיח צדקנו."],["1000","60","ויומתק יותר ע\"פ המבואר בכתהאריז\"ל (ל\"ת, ש' המצות וספר הליקוטים פרשתנו) ששייך לתיקון חטא הבל כו' (ע\"ש בארוכה. ונת' במאמרי אדה\"ז — תקס\"ה ח\"ב ע' תתא ואילך. ע' תתמט ואילך) — שמובן שזהו ענין כללי ביותר, הנוגע לתיקון כל העולם כולו."]]],[1301550194,"<h3>שיחה א</h3>\nא. באיסור \"לא תלבש שעטנז\"<sup data-n=\"1001\">1</sup>, שפירשו חז\"ל ד\"שעטנז\" היינו \"עד שיהא שוע טווי ונוז\"<sup data-n=\"1002\">2</sup>, מצינו פלוגתא בין רש\"י ורבינו תם:\nלרש\"י<sup data-n=\"1002\">2</sup> \"דבר<sup data-n=\"1004\">3</sup> תורה לא הוי כל­אים. . אלא א\"כ עירב הצמר והפשתן יחד וסרקם יחד במסרק (\"שוע\") וטוום וארגם (\"נוז\") ביחד, ולר\"ת<sup data-n=\"1005\">4</sup> הוי כלאים מדאורייתא אפילו סרק כל אחד ואחד לבדו וטוואו לבדו ושזרו לבדו (\"נוז\"<sup data-n=\"1006\">5</sup>) ואח\"כ חיברן ביחד על ידי אריגה או כו'\".\nוהיינו, דלר\"ת התנאי \"עד שיהי' שוע טווי ונוז\" תכנו רק הגדרת צמר ופשתים כאלה שכל אחד מהם הוה (\"שעטנז\" —) שוע טווי ונוז, \"ועל שעטנז של צמר לבד ושל פשתים לבד הזהיר הכתוב שלא יעשה מהם בגד ביחד ומיחדיו נפקא\"<sup data-n=\"1007\">6</sup>; ואילו לרש\"י (דנוז היינו ארוג, כנ\"ל), ה­תנאי דשעטנז, צמר ופשתים שהם באופן דשוע וטווי ונוז ביחד.\nולכאורה יש לומר, שפלוגתתם תלוי' בגדר כלאי בגדים.\nדהנה איסור שעטנז בא בפרשה בהמשך לכלאי הכרם ולכלאי בהמה — \"לא תזרע כרמך כלאים גו' לא תחרוש בשור ובחמור יחדיו\"<sup data-n=\"1008\">7</sup>, ובהמשך לזה \"לא תלבש שעטנז גו'\". ושני אופני כלאים אלה — כלאי הכרם וכלאי בהמה — הם סוגים שונים: בכלאי הכרם, פעולת הכלאים היא שהמינים השונים, חטה ושעורה וחרצן<sup data-n=\"1009\">8</sup>, מתערבים יחד באופן שנעשית מציאות חדשה (במה שצומח מהם) — \"פן תקדש המלאה הזרע אשר תזרע ותבואת הכרם\"<sup data-n=\"1010\">9</sup>; ואילו כלאים דחרישה, \"לא תחרוש בשור וחמור יחדיו\", אינו תערובה, שניהם נשארים כמציאות בפ\"ע, אלא שביחד עושים פעולה בעולם, מחוץ להם.\nועפ\"ז יל\"ע בכלאי בגדים, באיזה סוג הוא — אם הוא ע\"ד כלאי הכרם, ש­עיקרו הוא תערובת פעולת מציאותם, או שהוא ע\"ד כלאים דחרישה, שהוא מחוץ להם.\nויש לומר, שבזה פליגי רש\"י ורבינו תם: לדעת רש\"י כלאי בגדים הוא מעין כלאי הכרם, שגדרם הוא יצירת חפצא שהיא תערובת שני מינים, ולכן ס\"ל שהאיסור הוא כאשר מתחילת עשייתן נעשו ביחד<sup data-n=\"1011\">10</sup>, מסריקתם עד",[["1001","1","פרשתנו כב, יא."],["1002","2","יבמות ה, ב. נדה סא, ב."],["1002","2","יבמות ה, ב. נדה סא, ב."],["1004","3","ל' הטור יו\"ד ר\"ס ש."],["1005","4","יבמות שם תוד\"ה עד שיהא. נדה שם ד\"ה שוע. וכן בתוס' הרא\"ש שם."],["1006","5","דלר\"ת \"נוז היינו שזור\", ולא כפרש\"י דנוז היינו ארוג (מקומות שבהערה הקודמת)."],["1007","6","ל' התוס' יבמות שם."],["1008","7","כב, ט. יו\"ד."],["1009","8","רש\"י שם, ט (מברכות כב, א. וש\"נ). וראה מפרשי רש\"י."],["1010","9","ל' הפסוק שם."],["1011","10","ראה פרש\"י על התורה עה\"פ \"שעטנז — ל' עירוב\"<sup data-n=\"e47\">*</sup>, ולא כפי' מנחם שהביא בפ' קדושים (יט, יט) \"ול' שעטנז פי' מנחם מחברת צמר ופשתים\"<sup data-n=\"e48\">**</sup>. וי\"ל שזהו מה שממשיך רש\"י בפרשתנו \"ורבותינו פירשו שוע טווי ונוז\", ד\"ורבותינו פירשו\" אינו פי' שני, אלא שע\"פ \"רבותינו\" מתבאר מה שגדרו של שעטנז הוא \"עירוב\"."],["e47","*","וראה רש\"י תמורה לד, א ד\"ה ליבטל (וראה הגהת השטמ\"ק שם) בהטעם דלא שייך ביטול ברוב בכלאים. ולהעיר עד\"ז מתוד\"ה בגד — נדה שם (ועד\"ז בתוס' ע\"ז סה, ב), אבל אינו מוכרח שזהו לשיטת ר\"ת (בתוד\"ה שוע נדה שם). ולהעיר גם שמדגיש (וכן בעוד ראשונים) ש\"שניהם היתר\" משא\"כ ברש\"י. וראה ש\"ך יו\"ד ר\"ס רצט ובשו\"ת חת\"ס שצוין בפ\"ת שם. בית האוצר מערכת ב כלל יח אות ח (מ, סע\"ב ואילך). ואכ\"מ."],["e48","**","ראה באר מים חיים (לאחי המהר\"ל) לפרש\"י קדושים שם, שני אופנים בפרש\"י (הובא בסוף הערה הבאה)."]]],[1301550195,"אריגתם<sup data-n=\"1012\">11</sup>; ולפי ר\"ת, כלאי בגדים הוא ע\"ד כלאים דחרישה, שענינם הוא ש­שני מינים שונים הנשארים שונים זה מזה מצטרפים יחד בפעולה מיוחדת, וזהו גדר לבישת ב' הסוגים דצמר ופשתים יחדיו — ולכן ס\"ל שאין צורך שיהיו מסורקים וטוויים יחד, ודי<sup data-n=\"1013\">12</sup> שהם ארוגים יחד.\nב. לפי הסברה זו יש לומר, ששיטת ר\"ת היא בהתאם למשמעות המשך הכתו­בים, ש\"לא תלבש שעטנז\" נאמר בהמשך ל\"לא תחרוש גו'\", שמזה משמע שאיסור שעטנז הוא אותו הגדר דכלאים דחרי­שה. ומה גם שהכתוב שלפנ\"ז \"לא תזרע כרמך כלאים\", נאמר בפרשה בפ\"ע, וה­איסורים ד\"לא תחרוש גו' לא תלבש גו'\" הם בפרשה בפ\"ע, ומדחילקם הכתוב לב' פרשיות, משמע שהם שני סוגים שונים. ולכן פי' ר\"ת, דכלאי הכרם (וכלאי זרעים), \"לא תזרע גו'\", גדרם הוא האי­סור לערב מינים באופן שנעשים מציאות אחת, משא\"כ כלאים דחרישה וכלאי בגדים — \"לא תחרוש גו' לא תלבש גו'\" — גדרם רק חיבור חיצוני, שגם זה אסרה תורה (בבהמה ובגד).\nויש לבאר טעמו של רש\"י, שס\"ל שגם גדרם של שעטנז — כלאי בגדים — הוא תערובת פנימית באופן שנעשה מצי­אות חדשה, אף שאיסור זה נאמר בתורה בהמשך ל\"לא תחרוש גו'\" — כי ס\"ל שזה שאסרה תורה כלאים דחרישה (\"לא תחרוש גו'\") הוא כעין סייג לאיסור הרבעה (\"בהמתך לא תרביע כלאים\"<sup data-n=\"1014\">13</sup>), וכמבואר ברמב\"ן<sup data-n=\"1015\">14</sup> דאיסור כלאים ד­חרישה \"היא מצוה מבוארת מן בהמתך",[["1012","11","וביישוב קושיית התוס' ד\"א\"כ כלאים בציצית היכי משכחת לה דאצטריך קרא למישרי, והלא חוטי תכלת חלוקין במסרק וטווי לבדם\" — ראה מהר\"י קורקוס לרמב\"ם הל' כלאים פ\"י ה\"ב, מה שהביא מרש\"י מהדו\"ק. ולכמה מפרשים גם לרש\"י ישנו עוד דין וגדר בהאיסור דלמדין מ\"צמר ופשתים יחדיו\"<sup data-n=\"e49\">*</sup>, גם בלא שוע טווי ונוז ביחד — ראה רא\"ם לפרש\"י קדושים שם (קרוב לסופו). צ\"צ בחידושים על ש\"ס כלאים פ\"ט מ\"ח אות ב (וראה שו\"ת הצ\"צ שער המילואים סל\"ח). ערוך לנר לתוס' יבמות שם. צפע\"נ להל' כלאים שם (יד, ב ואילך). ובכ\"מ.\nוכבר שקו\"ט בדברי רש\"י בפירושו עה\"ת קדו­שים שם דהעתיק דברי התו\"כ, דמשמע דגם לבדים אסורים, ונוז הוא לשון הנמלל ושזור כו', אם מתאים עם שיטתו בפירושו על הש\"ס, או שפי' שם שלא אליבא דהלכתא — ראה בארוכה מפרשי רש\"י שם. ולפי' באר מים חיים (וכ\"ה בפנים יפות ובאר בשדה) מ\"ש \"לרבות לבדים\" היינו שאינם בכלל שעטנז מה\"ת. ולפ\"ז ה\"ז כשיטתו בפירוש הש\"ס. ואכ\"מ."],["1013","12","וכלשון הטור שם \"ולר\"ת כו' אפילו סרק כ\"א מהם לבדו כו'\". וראה משנה ראשונה לכלאים פ\"ט מ\"ח בסופו מ\"ש בפי' הרע\"ב."],["1014","13","קדושים שם. ואולי י\"ל אסמכתא לשיטת רש\"י מהפסוק שם \"ובגד כלאים שעטנז לא יעלה עליך\" בכתוב אחד בהמשך ל\"שדך לא תזרע כל­אים\", וגם דשם נאמר בהכתוב \"לא תרביע כלאים\" ולא כלאים דחרישה."],["1015","14","ובבחיי כאן. וכן ברמב\"ן ובחיי קדושים שם. פענח רזא כאן."],["e49","*","או מהסמיכות ל\"גדילים תעשה לך\" — ראה ראב\"ד לתו\"כ קדושים שם."]]],[1301550196,"לא תרביע כלאים שדרך כל עובד אדמתו להביא צמדו ברפת אחת וירכיב אותן\"<sup data-n=\"1016\">15</sup>. וא\"כ אין האיסור דכלאים ד­חרישה גדר חדש בכלאים, דכללות איסור כלאים הוא רק גדר אחד, דהיינו תערובת פנימית באופן שנעשה מציאות חדשה (וכלאים דחרישה הוא רק סייג ל­איסור הרבעה), ולכן גם באיסור שעטנז ס\"ל לרש\"י שגדרו הוא תערובת פנימית, כנ\"ל.\nג. והנה הרמב\"ם<sup data-n=\"1017\">16</sup> כתב \"כיון שנת­חבר הצמר עם הפשתן צד חיבור בעולם הרי זה כלאים מן התורה, כיצד צמר ופשתים שטרפן זה עם זה ושע אותן ועשה מהן לבדין הרי אלו כלאים, טרפן וטוה אותן כאחד וארג בגד מטווי זה הרי זה כלאים\".\nוהיינו, ששיטת הרמב\"ם היא כמו שיטה ממוצעת בין רש\"י ור\"ת, שמחד גיסא ס\"ל להרמב\"ם ש\"שוע טווי ונוז\" הוא החפצא דשעטנז (ולא כפי' ר\"ת ש­זהו רק תיאור סוג הצמר ופשתים שעליו חל האיסור לערבם יחד, והתערובות ד­שעטנז הוא רק בהאריגה); אבל לאידך, לא ס\"ל כרש\"י שצ\"ל חיבורם בכל שלשת הדברים ד\"שוע טווי ונוז\", אלא מספיק \"צד חבור בעולם\", דגם שוע לבד הוי כלאים, ו(לכמה דיעות) גם טווי לחוד הוי כלאים (וכמו שהאריכו בנו\"כ ובמפרשים<sup data-n=\"1018\">17</sup> בביאור דעת הרמב\"ם).\nוע\"פ הנ\"ל שגדרם של כלאי בגדים נלמד מכלאים דחרישה (כיון שנאמרו בקרא בהמשך זל\"ז), י\"ל, ששיטת ה­רמב\"ם בגדר כלאי בגדים היא בהתאם לשיטתו בגדר האיסור ד\"לא תחרוש גו'\".\nדהנה הרמב\"ם במו\"נ<sup data-n=\"1019\">18</sup> כתב שטעם כלאים דחרישה הוא \"כי אם יקבץ בין שניהם, פעמים ירכיב אחד מהם על חבירו\", ולפום ריהטא נראה שזהו ע\"ד דברי הרמב\"ן הנ\"ל שאיסור כלאים ד­חרישה הוא רק סייג לכלאים דהרבעה, אבל יש לומר, שלדעת הרמב\"ם, האיסור דלא תחרוש גו' הוא סייג לאיסור רביעה, לא רק מפני שבפועל מעשה ד­חרישה יחדיו יכול להביא לרביעה, אלא גם מצד הדמיון בתוכן שיש בשתי ה­פעולות דהרבעה וחרישה יחד (ומשום הכי נאסרה חרישה יחדיו אגב רביעה).\nדהנה איסור הרבעה עצמו, יש ל­פרשו בשני אופנים:\nא) עיקר האיסור הוא בגלל התוצאה מזה — הולדת מין אחר חדש, הנעשה מהרכבת שני המינים, ולפ\"ז, כלאים ד­הרבעה הם בדוגמא ובסוג<sup data-n=\"1020\">19</sup> כלאי הכרם (כלאים דזריעה), שעיקרם הוא מצד התערובת — דמין אחר חדש הנצמח מזה, וכמו שהאריך ברמב\"ן עה\"ת<sup data-n=\"1021\">20</sup>.\nולאופן זה, כלאים דחרישה הוא בסוג וגדר אחר, שהרי אין בזה מעשה תערו­בת רק בהפעולה דשני המינים יחדיו (ולפ\"ז, זה שאיסור דחרישה הוא סייג",[["1016","15","להעיר שעפ\"ז מצינו עוד מצוה דאורייתא מטעם סיג — ראה לקח טוב (להר\"י ענגל) כלל ח."],["1017","16","הל' כלאים פ\"י ה\"ב."],["1018","17","לרמב\"ם שם. וכן בנו\"כ ומפרשי הטושו\"ע יו\"ד ר\"ס ש. ורוב מפרשים פירשו בדעת הרמב\"ם דכ\"א לבדו הוי כלאים, וכמ\"ש הרמב\"ם בהל' עדות פ\"י ה\"ג ובלח\"מ שם. וראה גם חידושי הצ\"צ שם. ועוד."],["1019","18","ח\"ג פמ\"ט (הובא בחינוך מצוה תקנ)."],["1020","19","אף שהולד הנולד אינו אסור בהנאה ככלאי הכרם (כדלקמן בפנים). ולהעיר מדעת איסי בן עקבי' (ירושלמי כלאים פ\"ח ה\"ב)."],["1021","20","קדושים שם בתחלתו. ומ\"ש להלן שם \"וה­מינים בבע\"ח לא יולידו כו'\" הוא עוד טעם, כמפורש שם בההמשך בנוגע לכלאי זרעים."]]],[1301550197,"לאיסור רביעה, הוא רק מצד זה שב­פועל יכולה החרישה להביא לידי הרבעה).\nב) גם איסור כלאים דהרבעה אינו מצד התערובת שבמין החדש הנוצר אז, אלא ענין ההרבעה הוא מצד הפעולה של תערובת שני מינים. וכמשנ\"ת ב­מק\"א<sup data-n=\"1022\">21</sup>, שנפסקה הלכה — כמ\"ש ה­רמב\"ם — \"מותר להכניס שני מינין לסהר אחד ואם ראה אותם רובעים זה את זה אינו זקוק להפרישן\"<sup data-n=\"1023\">22</sup>, \"מי שעבר והרכיב בהמתו הרי הנולד מהם מותר בהנאה\"<sup data-n=\"1024\">23</sup>, ולוקה מה\"ת רק כשהכניס בידו כו'<sup data-n=\"1025\">24</sup>, משמע, דגדר איסור כלאים הרבעה ע\"ד ההלכה, אינו בגלל התול­דות שנולדים מהם, אלא מצד עצם מעשה ההרכבה וההרבעה.\nולאופן זה יש לומר, דכלאים ד­חרישה הוא באותו הסוג ומעין הגדר דכלאי הרבעה, כי זה שנאסרה החרישה יחדיו הוא משום שזהו כעין התחלה של פעולת החיבור של שני המינים (כי קיבוץ שני המינים מביא לידי כך ש­\"פעמים ירכיב אחד מהם על חבירו\").\nוהיינו, שלשיטת הרמב\"ם, זה שאסרה תורה כלאי חרישה הוא לפי שהאיסור הוא בפעולת החיבור. אבל לאידך, אין זה מפני שהתורה אסרה חיבור זה מצד עצמו, אלא לפי שהם בגדר דכלאים ד­הרבעה, וזהו עיקר האיסור, כאשר פעו­לת החיבור יש בה ההרכבה — הרבעה דשני מינים.\nד. ועפ\"ז יש לומר, שלשיטתו אזיל גם בכלאי בגדים (שהוא בגדר וסוג זה), שיש בזה ב' הקצוות:\nגדר האיסור אינו רק צירוף (כדעת ר\"ת) אלא צ\"ל חיבור שני המינים ב­עשייתן; אבל לאידך אין החיבור צ\"ל באופן ששניהם נעשים חפצא אחת מ­תחלת הוייתן דצמר ופשתים, עד שנעשו לבגד אחד שאינה ניכרת חלוקתן (כדעת רש\"י), אלא די שיהי' איזה \"צד חיבור\" ביניהם (ע\"ד שהתורה אסרה פעולת ה­חרישה יחדיו, אף שאין כאן הרכבה ממש, כיון שזוהי כעין התחלה של הרבעה, כנ\"ל).\nוזה מדוייק בדברי הרמב\"ם, שאף ש­כתב בתחילה<sup data-n=\"1017\">16</sup> \"כיון שנתחבר הצמר עם הפשתן צד חיבור בעולם הרי זה כלאים מן התורה\", מ\"מ ממשיך<sup data-n=\"1017\">16</sup> \"כיצד צמר ופשתים שטרפן זה עם זה ושע אותן ועשה מהן לבדין הרי אלו כלאים, טרפן וטוה אותן כאחד וארג בגד מטווי זה הרי זה כלאים\", ולכאורה, כיון דמן ה­תורה נאסר בכל צד חיבור בעולם [וכפי שהאריך בהלכה שלאח\"ז<sup data-n=\"1028\">25</sup> \"תפר בגד צמר בשל פשתן ואפילו תפרן במשי או שתפר בגד צמר בחוטי פשתן או בגד פשתים בחוטי צמר או קשר חוטי צמר בחוטי פשתים או גדלן אפילו נתן צמר ופשתים בשק או בקופה וכרכן הרי אלו כלאים, ואפילו קשר גדיל של צמר בגדיל של פשתן אע\"פ שהרצועה ב­אמצע, וכן אם כפל בגדי צמר ופשתן וקשרן הרי אלו כלאים שנאמר צמר ופשתים יחדו מכל מקום כיון שנתאחד נאסר\"] — למה מודגש בכתוב \"שוע טווי ונוז\", וכדוגמא הראשונה באופן החיבור שתפס ברמב\"ם שם ד\"טרפן זה עם זה ושע אותן<sup data-n=\"1029\">26</sup> ועשה מהן לבדין\"<sup data-n=\"1030\">27</sup> (שב­",[["1022","21","לקו\"ש חכ\"ד ס\"ע 149 ואילך."],["1023","22","הל' כלאים פ\"ט ה\"ב."],["1024","23","שם ה\"ג."],["1025","24","שם ה\"א. ועד\"ז בסה\"מ מל\"ת ריז."],["1017","16","הל' כלאים פ\"י ה\"ב."],["1017","16","הל' כלאים פ\"י ה\"ב."],["1028","25","ה\"ג (בפ\"י)."],["1029","26","ולהעיר ש\"שוע\" נאמר בתורה בפירוש (ברמז) בתיבת \"שעטנז\" — \"שע\". וראה כס\"מ לרמב\"ם שם."],["1030","27","ולהעיר ממאירי (ביצה טו, א. יבמות ה, ב בפסקיו — הובא בשעה\"מ הל' כלאים פ\"י ה\"א) בטעם הרמב\"ם דלבדים אסורים מה\"ת, \"מפני שגמר עשייתן בכך ולא הוצרכו לשוע טווי ונוז אלא בבגד שלא נגמרה עשייתו אלא בשלשתם\" (ועד\"ז בתוס' הרא\"ש נדה שם). ולהעיר דלפי' הרמב\"ם בפיה\"מ (כלאים פ\"ט מ\"ח), מעשה הטריפה והמחיקה הוא לאחר שנעשה בגד. וראה חי' הצ\"צ שם בתחלתו. הכתב והקבלה קדושים שם."]]],[1301550198,"דוגמא זו, כללות עשיית הבגד מתחילתו היתה ע\"י תערובת שני המינים).\nאלא כי לדעת הרמב\"ם כלאי בגדים הם בדוגמת כלאי בהמה, וכמו בכלאים דבהמה, אף שהאיסור הוא גם בכלאים דחרישה, שאין כאן חיבור פנימי, מ\"מ עיקר גדרו הוא כלאים דהרבעה כנ\"ל, מעין זה הוא בכלאי בגדים, דאף דאי­סור כלאים מה\"ת הוא כאשר נתחבר בכל צד חיבור בעולם, מ\"מ, עיקרו הוא כאשר יש חיבור פנימי, שזהו כאשר טרפן זה עם זה ושע אותן ועשה מהן לבדין<sup data-n=\"1029\">26</sup>.\nה. ויש לבאר פלוגתת רש\"י ור\"ת הנ\"ל ע\"ד החקירה והדרוש — ובהקדם, שמצינו חילוק עיקרי בין כלאי בגדים לכלאי זרעים וכלאי בהמה, שבהם נאסרה עצם עשיית הכלאים, זריעת הכלאים בקרקע, וכן הרבעת שני מינים (נוסף על איסור החרישה בשור וחמור יחדיו), משא\"כ בכלאי בגדים נאסרה רק לבישת שעטנז ולא עצם עשיית בגד של צמר ופשתים יחדיו.\nויש לבאר טעם החילוק — דכלאי בגדים שונים מכלאי זרעים וכלאי בהמה בזה, שבכלאי בגדים החיבור הוא משני סוגים שונים, סוג החי וסוג הצומח [דצמר הוא מבעל חי ופשתים מצומח]<sup data-n=\"1032\">28</sup>, ומשום זה לא תצוייר תערובת ביניהם בעצם מציאותם, אלא החיבור ביניהם הוא רק חיבור חיצונית שלהם; משא\"כ בכלאי זרעים וכלאי בהמה שהתערובת היא באותו סוג (שני מינים של צומח או שני מינים של חי), הרי שם התערובת היא במציאותם, בכח הצמיחה וכח ה­הולדה שלהם.\nולכן רק בכלאי זרעים וכלאי בהמה נאסרה (גם) עצם עשיית התערובת, כיון שהתערובת היא במציאותם; משא\"כ ב­כלאי בגדים (דצמר ופשתים) שאי אפשר לערבם בעצם מציאותם, לא נאסרה עשיית התערובת אלא רק לבישת בגד הנעשה מתערובת זו.\nויש לומר, שזהו טעמו של ר\"ת שאיסור שעטנז הוא גם כשאין תערובת גמורה ב\"שוע טווי ונוז\", דכיון שהאיסור שעטנז אינו אלא על לבישת השעטנז, ולא על עשיית התערובת דצמר ופשתים יחדיו (שלא שייך שתהי' תערובת אמי­תית בצמר ופשתים כנ\"ל), מסתבר לומר, שמספיק חיבור חיצוני (אריגת הצמר ופשתים) כדי לאסור הלבישה בבגד זה<sup data-n=\"1033\">29</sup>.",[["1029","26","ולהעיר ש\"שוע\" נאמר בתורה בפירוש (ברמז) בתיבת \"שעטנז\" — \"שע\". וראה כס\"מ לרמב\"ם שם."],["1032","28","וכדמוכח גם ממחז\"ל (פדר\"א פכ\"א. זח\"ג פו, ב ואילך. ועוד) דאיסור שעטנז הוא כי אמר הקב\"ה אל יתערבו מנחת קין והבל לעולם — והרי מנחת הבל היא מה שהביא מבכורות צאנו ומ­חלביהן, קרבן ממין החי.\nופשיטא לפי ביאור הבחיי (קדושים שם — ע\"פ זהר שם. וראה גם רמב\"ן שם) שענין הכלאים הוא מפני שמערבב כחות העליונים, שבכחות העליונים הם במין החי ומין הצומח."],["1033","29","ובאופן אחר קצת יש לומר: ר\"ת ס\"ל ש­עיקר גדר איסור כלאים הוא החיבור של שני דברים מנוגדים, וכיון שהתערובת בשעטנז היא משני סוגים, צומח וחי, צמר ופשתים, לכן, גם כאשר החיבור הוא רק בחיצוניות ששוכנים יחד, הרי מצד חילוקי הסוג נעשה כבר גדר של כלאים של ב' דברים מנוגדים<sup data-n=\"e50\">*</sup> [משא\"כ כאשר ב' המינים הם מאותו הסוג וקרובים זל\"ז, הרי כדי שייעשה מצב של כלאים, חיבור דברים המנוגדים, צריך שהחיבור יהי' באופן של תערובת ממש, כי שכינתם יחד אינה בסתירה למציאותם, שהרי הם בגדר וסוג אחד]."],["e50","*","להעיר מלקו\"ש שם ע' 150 ובהערה 40 שם."]]],[1301550199,"ובסברת רש\"י יש לומר, דאע\"פ שאין בכלאי בגדים תערובת בעצם המציאות, מ\"מ, כאשר מתחילת עשייתן נעשו ביחד, מסריקתם עד אריגתם, יש עכ\"פ דמיון לתערובת דכלאי זרעים וכלאי בהמה, ולכן נאסרו גם כלאים אלה, והוא כמו סייג לשאר אופני כלאים (וכמ\"ש ה­רמב\"ן<sup data-n=\"1034\">30</sup> שהאיסור דכלאי בגדים הוא רק להרחקה).\n[ומ\"מ, כיון שבפועל אין בעשיית שעטנז תערובת בעצם המציאות, לא נאסרה עשיית השעטנז, אלא רק הלבי­שה בו].\nו. וע\"פ מ\"ש הרמב\"ם<sup data-n=\"1035\">31</sup> שכל מצוות התורה ניתנו לתקן הדעות כו', י\"ל שיש רמז ולימוד בעבודת האדם בזה שדוקא בכלאי בגדים נאסרה רק הלבישה:\nידוע שכוחות הנפש שבאדם נחלקים לד' סוגים, כנגד דומם צומח חי ומדבר, ד\"צומח\" שבנפש הן המדות, ו\"חי\" הוא השכל (כמבואר בכמה מקומות<sup data-n=\"1036\">32</sup>). וזהו הרמז בכך שלא נאסרה עשיית בגד של שעטנז, כי אדרבה, זהו משלימות ה­אדם<sup data-n=\"1037\">33</sup>, שכוחותיו כלולים זמ\"ז, שהשכל משפיע על המדות והמדות הן לפי ערך השכל [ומה שאסרה תורה תערובת של שני מינים הוא רק כאשר ע\"י תערובת זו מתבטלים הגדרים והתכונות המיוחדות של כל כח (ע\"ד כלאי זרעים וכלאי בהמה, שנוצר מין חדש)<sup data-n=\"1038\">34</sup>].\nאבל מ\"מ אסור ללבוש שעטנז, כי לבוש הו\"ע של מקיף, דהיינו עבודה הבאה מצד הכוחות המקיפים שבנפש<sup data-n=\"1039\">35</sup>, כח הרצון והתענוג, שעבודה זו היא ב­אופן שכל עניני האדם \"מוקפים\" וחדו­רים ברצון או תענוג זה (כמו לבוש ה­אדם, שמקיף את האדם, ועד שישנו לבוש המקיף רובו ככולו בבת אחת). וכאשר העבודה היא באופן כזה, אי אפשר שתהי' \"תערובת\" של שני מיני כחות, כי כאשר האדם בכללותו עסוק ונתפס באופן אחד של עבודת ה' עד שזה מקיפו כולו, אי אפשר שיהי' עסוק בשעת מעשה (וגם כן באופן של \"מקיף\" התופס את כולו) בדבר שני.\nולכן מזהיר הכתוב \"לא תלבש שעטנז\", דבנוגע למדריגת מקיפי הנפש, צ\"ל ההתעסקות בכל סוג עבודה בפני עצמו, ואין לערב \"צמר ופשתים יחדיו\".\n<span data-k=\"q\">(משיחות ש\"פ תצא תשמ\"א, א' דר\"ח אלול תשד\"מ)</span>",[["1034","30","קדושים שם."],["1035","31","סוף הל' תמורה."],["1036","32","תו\"א ד, א ואילך. לקו\"ת חקת נח, א. תו\"ח בראשית יט, סע\"ג ואילך. ד\"ה חביבין ישראל תרצ\"ו פ\"י. ובכ\"מ."],["1037","33","ראה רמב\"ם בהקדמתו לפיה\"מ ד\"ה אחר כן ראה להסתפק."],["1038","34","וראה בארוכה לקו\"ש חכ\"ט ע' 125 ואילך."],["1039","35","כידוע (לקו\"ת ברכה צח, סע\"ד ואילך. ובכ\"מ) החילוק בין מזון לבוש ובית, שהם בחי' פנימי, מקיף ומקיף למקיף. וראה גם עטרת ראש שער יוה\"כ ספ\"ב ואילך."]]],[1301550200,"<h3>שיחה ב</h3>\nא. בפירוש הפסוק<sup data-n=\"1040\">1</sup> \"כי תבא בכרם רעך ואכלת ענבים כנפשך שבעך ואל כליך לא תתן\", אמרו חז\"ל<sup data-n=\"1041\">2</sup> \"בפועל הכתוב מדבר\".\nהיסוד לפירוש זה מצינו בזה שלש דעות:\nא) בבבלי<sup data-n=\"1041\">2</sup> נלמד הדבר מגז\"ש — \"נאמר כאן ביאה ונאמר להלן<sup data-n=\"1043\">3</sup> לא תבא עליו השמש מה להלן בפועל הכתוב מדבר אף כאן בפועל הכתוב מדבר\".\nב) בירושלמי<sup data-n=\"1044\">4</sup> נלמד מהמשך הכתוב — \"כתיב כי תבא בכרם רעך יכול ב­שאר כל אדם הכתוב מדבר ת\"ל ואל כליך לא תתן אבל נותן את לכליו של חבירך ואי זה זה, זה הפועל\"<sup data-n=\"1045\">5</sup>. ועד\"ז בכתוב שלאח\"ז<sup data-n=\"1046\">6</sup> \"כי תבא בקמת רעך — יכול בשאר כל אדם הכתוב מדבר ת\"ל וחרמש לא תניף על קמת רעך את שיש לו רשות להניף ואי זה זה, זה הפועל\"<sup data-n=\"1047\">7</sup>.\nג) הרמב\"ם<sup data-n=\"1048\">8</sup> כתב שמכתוב זה עצמו מוכרח הוא — \"כי תבוא בכרם רעך וגו' וכתוב כי תבא בקמת רעך, מפי השמועה למדו שאין הכתוב מדבר אלא בשכיר וכי אילו לא שכרו מי התיר לו שיבא בכרם רעהו (ומי התיר לו לבא) בקמה שלו שלא מדעתו, אלא כך הוא אומר כי תבא לרשות בעלים לעבודה — תאכל\"<sup data-n=\"1049\">9</sup>.\nויש לומר, שגם רש\"י בפירושו על התורה ס\"ל הכי, שכתב: \"כי תבא בכרם רעך — בפועל הכתוב מדבר\", וכן בכתוב שלאחריו \"כי תבא בקמת רעך — אף זה בפועל הכתוב מדבר\".\nדמזה שרש\"י (א) לא העתיק מהכתוב אלא רק התיבות \"כי תבא בכרם רעך\" (וכן רק \"כי תבא בקמת רעך\"), ולא המשך הכתוב (ואפילו לא רמזו ב\"וגו'\"), וכן (ב) לא הזכיר כלל הגז\"ש מהנאמר להלן \"לא תבא עליו השמש\" — מוכח, שלדעת רש\"י יודעים ש\"בפועל הכתוב מדבר\" מהתיבות \"כי תבא בכרם רעך\" עצמן (וכן מ\"כי תבא בקמת רעך\").\nוהטעם מובן בפשטות, כמ\"ש הרמב\"ם — דכיון שהמדובר בכרם רעהו ובקמת",[["1040","1","פרשתנו כג, כה."],["1041","2","ב\"מ פז, ב."],["1041","2","ב\"מ פז, ב."],["1043","3","פרשתנו כד, טו."],["1044","4","מעשרות פ\"ב ה\"ד."],["1045","5","ולכאורה יל\"פ שזוהי כוונת הספרי כאן, \"כי תבא בכרם רעך יכול לעולם ת\"ל ואל כליך לא תתן בשעה שאתה נותן לכליו של בעה\"ב\", דכוונתו ב\"יכול לעולם\" היינו (כולל) בכל אדם, \"ת\"ל ואל כליך לא תתן כו'\" — שהמדובר בפועל<sup data-n=\"e51\">*</sup>. אבל במפרשי הספרי לא פירשו כן."],["1046","6","כג, כו."],["1047","7","ראה דרשות הספרי עה\"פ ובמפרשים. וגם שם שקו\"ט ע\"ד הנ\"ל בהערה 5. ואכ\"מ."],["1048","8","הלכות שכירות רפי\"ב."],["1049","9","בספרי דבי רב לספרי (שם כג, כו) האריך דמשמע להרמב\"ם מתרי טעמי דהגז\"ש בגמ' לאו גז\"ש גמורה היא. ע\"ש. וצ\"ע."],["e51","*","גם ברא\"ם לפרש\"י כאן מבאר דלמדין שבפועל הכתוב מדבר מדרשת הספרי (ראה שפ\"ח. משכיל לדוד. ועוד). אבל מפרש בספרי כתוכן פרש\"י שלאח\"ז, דהיינו פועל בבציר, לאפוקי פועל בעדור ובקשקוש. אבל ראה אמרי שפר ועוד לפרש\"י כאן, דהספרי בא ללמוד רק שלא דברה תורה אלא בשעת בציר כו', והלימוד דבפועל הכתוב מדבר הוא מגז\"ש כבגמ'. וראה בארוכה במפרשי הספרי."]]],[1301550201,"רעהו — \"מי התיר לו שיבא\" בלי רשות הבעלים? ועכצ\"ל<sup data-n=\"1050\">10</sup> ש\"בפועל הכתוב מדבר\".\nב. ויש לומר, שהחילוק בין שלש דעות אלו אינו רק במקור הפירוש אלא גם בתוכן — שהם ג' אופנים בהגדרת הדין דאכילת פועל בשעת מלאכתו, שיש לבארו בכמה אופנים (ובלשון הצפע\"נ בכמה ענינים<sup data-n=\"1051\">11</sup>: מצד הנפעל, הפעולה, או הפועל):\nא) אכילת הפועל היא כעין שכר על המלאכה (הנפעל) שעושה עבור הבעה\"ב, שנוסף על שכרו שמשלם לו הבעה\"ב עבור מלאכתו, הוא גם אוכל מהפירות כו' שעובד בהם.\nב) אכילת הפועל אינה עבור ה­מלאכה והתועלת שגורם לבעה\"ב, אלא שעבודתו של הפועל, שטורח ומתייגע במלאכת רעהו, נותנת לו זכות לאכול (בשעת מעשה) מפירותיו כו'.\nג) אכילתו אינה בגדר שכר כלל — לא על החפצא דהמלאכה ולא על עבודת הגברא — אלא הוא דין בפני עצמו, דכיון שיש עליו שם \"פועל\", זיכתו התורה לאכול מן הפירות כו' שפועל בהם.\nמהנפק\"מ בין אופנים אלו י\"ל, שהוא ע\"ד האיבעי' בגמ'<sup data-n=\"1052\">12</sup> \"פועל משלו הוא אוכל או משל שמים הוא אוכל\", דפרש\"י שם: \"משלו הוא אוכל — תוספת שכר הוא שהוסיפה לו תורה, או משל שמים במתנת גמילות חסדים כשאר מתנות עניים\".\nלאופן הא' הנ\"ל, שאכילת הפועל היא מחמת המלאכה שעושה עבור הבעה\"ב — י\"ל ד\"משלו הוא אוכל\", שזכות זו היא (בל' רש\"י כנ\"ל) \"תוספת שכר\" עבור מלאכתו, והיינו שהוא באותו הסוג של עיקר שכרו (שהוא תשלום עבור מלאכ­תו), אלא שהיא \"תוספת שכר. . שהוסי­פה לו תורה\".\nלאופן הג' הנ\"ל — שזהו דין מצד עצם שם ותואר \"פועל\" (ולא מצד המלאכה שעושה) — ה\"ז כהצד ד\"משל שמים הוא אוכל\", דכשם שהתורה זיכתה לעניים מתנות שונות בפרי האדמה, כך זכי לי' רחמנא ל\"פועל\" לאכול מפירות האדמה שפועל בה.\nולאופן הב', שזהו מצד עבודת וטיר­חת הפועל — יש מקום לשני צדדי ה­איבעיא: יתכן לומר \"משלו הוא אוכל\", שזהו חלק משכרו, דכשם שמגיע לו (עיקר) שכרו על מלאכתו שנעשית עבור הבעה\"ב, כך מגיע לו \"תוספת שכר\" על עבודתו וטירחתו<sup data-n=\"1053\">13</sup>; ואפשר לומר, שאינו",[["1050","10","ראה ב\"מ (צב, א) פרש\"י ד\"ה ת\"ק לית לי' ותוד\"ה איבעית שם, דהלשון \"פועל\" שולל דעת איסי בן יהודה שם, דמפרש הכתוב \"בביאת כל אדם הכתוב מדבר\" (ולפי פי' ר\"א בגמ' ב\"עושין ב­סעודתם דעבדו ואכלו\") — גם הנכנס בלי רשות בעלים. ולהעיר משו\"ע אדה\"ז חלק חו\"מ (ח\"ו) הלכות שאלה ושכירות כו' סכ\"ב \"כי תבא בכרם רעך כו' ובפועל העובד בכרם הכתוב מדבר כו' ולא בשאר כל אדם וכן כי תבוא בקמת רעך גו' בפועל הכתוב מדבר ולא בשאר כל אדם\". אבל בפי' הר\"ח בשטמ\"ק ב\"מ שם צב, א ד\"ה איבעית, רא\"ש שם, מפרשים דעת הת\"ק במשנה \"הרי אוכל פועל כו'\" כאיסי בן יהודה, ולא כרש\"י ותוס' שם. ובכמה מפרשי הספרי (ראה ספרי דבי רב ועוד כאן) מפרשים דברי הספרי כדעת איסי בן יהודה. וראה בחיי ואמרי שפר כאן. ואכ\"מ."],["1051","11","ראה מפענח צפונות פי\"ב. וש\"נ."],["1052","12","ב\"מ צב, א."],["1053","13","אבל לא עבור המלאכה עצמה כגוף השכירות. — ולפי אופן זה בפי' \"משלו הוא אוכל\" (דאינו דומה לשכר עבור עצם המלאכה) אולי יש ליישב קושיית החכמת שלמה בגליון השו\"ע חו\"מ סשל\"ז סי\"ב."]]],[1301550202,"בגדר \"שכר\" כ\"א רק \"מתנת גמילות חסדים\", אלא שמתנה זו ניתנה לו רק מחמת עבודתו וטירחתו, ע\"ד אי לאו דעביד נייחא לנפשי' לא יהיב לי מתנתא<sup data-n=\"1054\">14</sup>.\nג. וזהו החילוק בין שלשת המקורות לפירוש \"בפועל הכתוב מדבר\"\n— (א) דרשת הירושלמי שנלמד מסיפא דקרא \"ואל כליך לא תתן, אבל נותן את לכליו של חבירך. . זה ה­פועל\", (ב) הגז\"ש שבבבלי מה\"נאמר להלן לא תבא עליו השמש\", (ג) הלימוד מהתיבות \"כי תבא בכרם רעך\" עצמן — \"כי אילו לא שכרו מי התיר לו שיבא בכרם רעהו\" —\nדיש לומר, שתוכן החילוק בין הלי­מודים הנ\"ל, תלוי בתוכן הענין המדובר במקום הנלמד:\nלהירושלמי שלמדין זה ממ\"ש \"ואל כליך לא תתן — אבל נותן את לכליו של חבירך\", שמדובר בגוף המלאכה שעושה לבעה\"ב — י\"ל דס\"ל ד\"משלו הוא אוכל\", ואכילת הפועל היא כעין \"תוספת שכר. . שהוסיפה לו תורה\" עבור מלאכתו;\nלש\"ס דילן, שהלימוד הוא מהגז\"ש ד\"לא תבא עליו השמש\", הנאמר גבי הדין ד\"ביומו תתן שכרו\" — הרי זה דין מצד הגברא העובד, וכהמשך הכתוב (ד\"ביומו תתן שכרו\") \"ואליו הוא נושא את נפשו — אל השכר הזה הוא נושא את נפשו למות, עלה בכבש ונתלה באילן\"<sup data-n=\"1055\">15</sup>, והיינו שהדין ד\"ביומו תתן שכרו\" אינו (כ\"כ) מצד גוף המלאכה שעושה ל­בעה\"ב, כ\"א מצד מסירת נפשו של הפו­על עלי', ועד\"ז בנדו\"ד, דין אכילת הפועל, שהוא מצד טירחתו ועבודתו של הפועל\n[ולכן איבעי' לי' בגמ' אי אכילת פועל<sup data-n=\"1056\">16</sup> \"משלו הוא אוכל או משל שמים הוא אוכל\", וכנ\"ל שלאופן זה יש מקום לשני צדדים אלו<sup data-n=\"1057\">17</sup>;\nולהרמב\"ם<sup data-n=\"1058\">18</sup> ופרש\"י על התורה, ש­מהתיבות \"כי תבא בכרם רעך\" עצמן למדים ש\"בפועל הכתוב מדבר\" — הרי זכות<sup data-n=\"1059\">19</sup> האכילה של הפועל היא מצד",[["1054","14","ראה גיטין נ, ב. ב\"ב קנו, רע\"א. וראה גם מגילה כו, ב. ב\"מ טז, א."],["1055","15","פרש\"י פרשתנו עה\"פ."],["1056","16","ראה בהמשך הדרשות בגמ' שם (פז, ב) \"כנפשך כנפש של בעה\"ב כך נפשו של פועל מה נפשך אוכל ופטור (מן המעשר) אף נפשו של פועל אוכל ופטור\". ופרש\"י שם \"כנפשך — כאילו הן שלך. אף פועל אוכל ופטור — ולא אמרינן הואיל דבאגרי' אכיל על כרחו של בעה\"ב הוי' לי' כמקח כו' כיון דזבני' אחשבי'\". ומשמע דמשלו הוא אוכל.\nוי\"ל בב' אופנים, דהדרשא ד\"כנפשך\" קמ\"ל דאף ד\"באגרי' אכיל\" מ\"מ פטור כהבעה\"ב; או דקמ\"ל, דהוא לא כהקס\"ד דהוי' לי' כמקח וזבני', כ\"א דמשל שמים אוכל. ופשיטא לפי' התוס' ב\"משל שמים\" (הובא בהערה 19) דלא שייך לומר דהוה לי' כמקח.\nולהעיר מתולדות אדם לספרי (כג, כה), דמפרש הדרשה \"רעך ולא של הקדש\" (שבהמשך הדרשות בגמ' שם) דס\"ל דמשל שמים הוא אוכל."],["1057","17","להעיר מב\"מ שם (צב, א), דהגמ' רצה לתלות מחלוקת ר\"א חסמא וחכמים אם פועל אוכל יותר על שכרו, ב\"אם משלו הוא אוכל או משל שמים הוא אוכל\", ודחה \"לא דכולי עלמא משלו הוא אוכל והכא בכנפשך קמיפלגי\", אבל ראה תוד\"ה כן נמצא, השקו\"ט בגי' הגמ' ומפרש דמצי קאי לב' הדיעות. ע\"ש."],["1058","18","דפסק דאוכל \"משל שמים\" (הל' שכירות ספי\"ב)."],["1059","19","להעיר שבפרש\"י על הש\"ס (צב, א) מפרש דלהאופן ד\"משל שמים הוא אוכל\" — יכול ליתן לאשתו ובניו, אלא ד\"כל זמן דלא מטא לידי' לא זכי לי'\"<sup data-n=\"e52\">*</sup>, ולא כפי' התוס' (שם ד\"ה אי אמרת) ד\"אי משל שמים הוא אוכל לא יהבינן להו שלא זיכה לו הכתוב אלא מה שהוא לועס ואוכל ואין לו כח ליתן כלום\" (ראה טור חו\"מ סשל\"ז ובפרישה שם. סמ\"ע שם סקל\"ג. הגהות הגר\"א בגליון הגמ' שם). ולהעיר ממנ\"ח (מצוה תקעו) שלדעת הרמב\"ם אם חסמו בעה\"ב לפועל פטור מתשלומין.\nמדברי הרמב\"ם בהל' שכירות פי\"ב הי\"ג משמע שס\"ל כדברי התוס', דגם לאחרי שמטי לידי' אינו נותן לאשתו ובניו (ומ\"ש בה\"ג שם \"וכן פועל שהוליך בידו ממה שעשה או שלקח יתר על אכילתו ונותן לאחרים עובר כו'\", והרי לדעת התוס' הוא הדין לכאורה גם בלקח רק בכדי אכילתו ולא יתר על אכילתו — ראה מעייני החכמה (למהרא\"ל צונץ) לב\"מ שם. וראה רי\"פ פערלא לסהמ\"צ לרס\"ג ל\"ת רסז (שכד, א ואילך)). אבל י\"ל שלפי פרש\"י עה\"ת ד\"בפועל הכתוב מדבר\" ה\"ז רק זכות אכילה מצד עצם שם \"פועל\", כבפנים.\nולהעיר דברמב\"ם שם הי\"ג כ' \"שלא זכתה תורה אלא לפועל עצמו\", וזה דאוכל \"משל שמים\" כ' בהי\"ד שם רק בנוגע לקטנים שעושין עם אביהם. ואכ\"מ."],["e52","*","ודברי רש\"י שם ע\"ב ד\"ה אי אמרת (וד\"ה משל שמים) אלא כשנותן לתוך פיו, כ' בנוגע לעבדיו הקטנים. ואכ\"מ."]]],[1301550203,"עצם שם ותואר \"פועל\"<sup data-n=\"1060\">20</sup>, שחל עליו מיד כששכרו ובא<sup data-n=\"1061\">21</sup> לכרם רעהו<sup data-n=\"1062\">22</sup>.\nד. והנה ידוע מה שארז\"ל<sup data-n=\"1063\">23</sup>, \"מה שהוא [הקב\"ה] עושה הוא אומר לישראל לעשות\". ומזה מובן, שהלכות התורה בנוגע ל\"פועל\" ו\"בעה\"ב\" כפשוטם, יסודן הוא — \"מה שהוא עושה\", הנהגת הקב\"ה כלפי בני ישראל, שעבודתם של ישראל בקיום התומ\"צ היא בדוגמת עבודתו של \"פועל\", ושכר מצות הוא ה\"תשלום\" שהקב\"ה משלם לישראל עבור פעולתם ועבודתם<sup data-n=\"1064\">24</sup>.\nוכן הוא בהדין דאכילת פועל בעת מלאכתו — שיסודו ושרשו הוא דין \"אכילת\" בני ישראל בעת עבודתם בקיום התורה והמצוות (בלשון המשנה<sup data-n=\"1065\">25</sup> \"שאדם אוכל פירותיהן בעוה\"ז\").",[["1060","20","כן יש לפרש בדרך ההלכה שבפרש\"י, דדברי רש\"י \"בפועל הכתוב מדבר\" אינם רק לשלול דעת איסי בן יהודה \"בביאת כל אדם הכתוב מדבר\" (כבאמרי שפר כאן) — אלא שזכות האכילה היא מצד עצם שם \"פועל\", כבפנים."],["1061","21","אף שפשוט שאינו אוכל לפני התחלת המלאכה. ולהעיר מתוד\"ה תבואת ב\"מ פח, סע\"א מתי מתחיל מקחו של הפועל, אם משעה שעושה מלאכתו או כשאוכל. ואכ\"מ."],["1062","22","עפ\"ז יש לבאר ג\"כ המשך פירוש רש\"י בענין זה:\nא) על \"ואל כליך לא תתן\" פרש\"י \"מכאן שלא דברה תורה אלא בשעת הבציר בזמן שאתה נותן לכליו של בעל הבית אבל אם בא לעדור ולקשקש אינו אוכל\" — דמזה שמדייק \"מכאן שלא דברה כו'\" משמע, שבא לשלול פירוש אחר ולחדש איזה דבר.\nוע\"פ הנ\"ל מובן, כי כיון שלפרש\"י זכות אכילת הפועל באה מצד עצם שם פועל (\"בפועל הכתוב מדבר\"), יש מקום לומר שכן הוא בכל פועל, אלא שמהוספת הכתוב \"ואל כליך לא תתן\" (דלכאורה מיותרים תיבות אלו — דמהיכא קס\"ד שהותר לו) למדין שמדובר בפועל מיוחד — \"מכאן שלא דברה כו' אלא בשעת הבציר כו'\".\nב) \"כנפשך\" פרש\"י \"כמה שתרצה\" (אף שבגמ' (ב\"מ פז, סע\"ב. שם צב, א. וראה גם ספרי עה\"פ כאן) מצינו עוד פירושים בתיבה זו<sup data-n=\"e53\">*</sup>) — דכיון ש(לדעת רש\"י) אוכל מצד עצם שם \"פועל\", אין הגבלה באכילתו, וכל זמן שהוא \"פועל\" אוכל \"כמה שתרצה\"."],["1063","23","שמו\"ר פ\"ל, ט. וראה ירושלמי ר\"ה פ\"א ה\"ג. ויק\"ר פל\"ה, ג. ועוד."],["1064","24","ראה אבות פ\"ב מי\"ד­טז. תו\"כ (ורש\"י) בחוקותי כו, ט. וראה בארוכה הדרן על (משניות) מס' אבות (לקו\"ש חי\"ז ע' 387 ואילך. ביאורים לפרקי אבות בסופו). לקו\"ש חכ\"ט ע' 138 ואילך (ושם נת' באו\"א מהמבואר לקמן בפנים). וראה ש\"ך עה\"ת פרשתנו עה\"פ בפי' כי תבוא בכרם רעך."],["1065","25","פאה רפ\"א."],["e53","*","ובפשטות י\"ל, כי רש\"י מפרש פשש\"מ, ובפשוטו של מקרא כבר ידענו ד\"נפש\" הוא (גם) מלשון רצון, כמו שפירש רש\"י לעיל (ח\"ש כג, ח) \"נפשכם — רצונכם\", ולכן פירש \"כמה שתרצה\"."]]],[1301550204,"ויש לומר, שיסוד דין אכילת פועל בעת מלאכתו בהנהגת הקב\"ה (\"מה שהוא עושה\") — הוא ה\"שכר\" של יעודים גש­מיים שבתורה, ע\"פ ביאור הרמב\"ם ה­ידוע<sup data-n=\"1066\">26</sup>, שאין הם \"סוף מתן שכרן של מצות\" (כי \"מתן שכרן של מצות. . (הוא) חיי העולם הבא\", שהוא שכר רוחני), אלא ענינם הוא, ש\"הקב\"ה נתן לנו תורה. . והבטיחנו בתורה שאם נעשה אותה בשמחה ובטובת נפש ונהגה בחכמתה תמיד — שיסיר ממנו כל הדברים ה­מונעים אותנו מלעשותה. . וישפיע לנו כל הטובות המחזיקות את ידינו לעשות התורה כגון שובע ושלום ורבוי כסף וזהב כדי. . (ש)נשב פנויים ללמוד ב­חכמה ולעשות המצוה כדי שנזכה לחיי העולם הבא\".\nוזהו כענין דין אכילת הפועל מ­הפירות שעובד בהם, שאין זה השכר והתשלום עבור מלאכתו, כי אם, מה ש­אוכל בעת מלאכתו — ע\"ד היעודיים הגשמיים שהקב\"ה נותן לבנ\"י בעולם הזה (זמן העבודה, \"היום לעשותם\"<sup data-n=\"1067\">27</sup>), שאין זה תשלום עבודתם, כי אם, הסרת המניעה (בזמן העבודה) כדי שיוכלו לעבוד עבודתם במנוחה בלי בלבולים כו'.\nה. עפ\"ז יש לבאר הטעם שהכתוב מתחיל בדין \"כי תבא בכרם רעך\" (אכי­לת הפועל \"בכרם\" שעובד בו), ורק אח\"כ מפרש \"כי תבא בקמת רעך וקטפת מלילות גו'\". דלכאורה אינו מובן, שהרי אכילת הפועל בכרם רעך יש בה, לכאו­רה, חידוש יותר גדול מקטיפת מלילות בקמה, וא\"כ הו\"ל להקדים הדין ד\"כי תבא בקמת רעך\" ואח\"כ להוסיף (חידוש יותר גדול) \"כי תבא בכרם רעך\". ולמה מקדים הדין דאכילת הפועל בכרם (ש­ממנו יכולים ללמוד בכ\"ש וק\"ו לענין אכילה בקמה)?\nוע\"פ הנ\"ל י\"ל, כי הדין דאכילת \"פועל\" בהנהגת הקב\"ה עם ישראל — הוא בפשטות יותר גבי \"כרם רעך\" (כמרז\"ל<sup data-n=\"1068\">28</sup> \"רעך זה הקב\"ה\"), מאשר גבי \"קמת רעך\".\nביאור הדבר:\n\"כרם\" ו\"קמה\" רומזים לשני סוגים בגידולי קרקע, שהם דוגמת ב' הענינים שבברכת בורא נפשות — \"חסרונן\", ו­\"להחיות בהם נפש\"<sup data-n=\"1069\">29</sup>: \"חסרונן\" הם ה­דברים המוכרחים לקיום האדם, וכמו תבואות השדה (קמת רעך), \"ארץ ממנה יצא לחם\"<sup data-n=\"1070\">30</sup>, שהלחם מוכרח לקיום ה­אדם, \"לחם לבב אנוש יסעד\"<sup data-n=\"1071\">31</sup>; \"ולה­חיות בהם נפש\" קאי על ענינים שהם לתענוג, וזהו\"ע ה\"כרם\" שמצמיח פירות המוסיפים בתענוג האדם אבל אינם דבר מוכרח כמו לחם.\nוענינם בעבודת ה', ש\"קמה\" שבשדה היא העבודה בפועל כפי המוכרח; ו­\"כרם\" קאי על עבודת ה' באופן של תענוג. כלומר: העבודה ד\"שדה\" (קמה) הוא כאשר מקיים רצון העליון מתוך כפי' וקב\"ע, כעבודת עבד, ואז מעשיו הם (בעיקר) באופן המוכרח ע\"פ שורת הדין — תנו לי חובתי ואעשנה; וכרם היא העבודה שמתוך תענוג, והיינו שאינו צריך לכפות את עצמו לקיים התומ\"צ, אלא יש לו בזה חיות ותענוג, ואז קיומו",[["1066","26","הל' תשובה פ\"ט ה\"א."],["1067","27","ס\"פ ואתחנן."],["1068","28","שמו\"ר ר\"פ יתרו. רש\"י שבת לא, א ד\"ה דעלך. וראה גם זח\"ב נה, ב. ועוד."],["1069","29","טור או\"ח (ודאדה\"ז) סר\"ז. לקו\"ת ואתחנן ד, ג. ובכ\"מ."],["1070","30","איוב כח, ה."],["1071","31","תהלים קד, טו."]]],[1301550205,"ועשייתו הם באופן דהידור מצוה ולפנים משורת הדין.\nולכן התחיל הכתוב בדין אכילת פועל בכרם רעהו, כי זוהי מילתא ד­פשיטא יותר, שכאשר איש ישראל עובד את ה' באופן של \"כרם\", מתוך תענוג, אזי ודאי שהקב\"ה \"יסיר ממנו כל הדב­רים המונעים\" אותו מלעשותה, וישפיע לו \"כל הטובות המחזיקות את\" ידיו לעשות התורה, וכדיוק לשון הרמב\"ם הנ\"ל \"שאם נעשה אותה בשמחה ובטובת נפש כו' (אזי) יסיר ממנו כל הדברים ה­מונעים. . וישפיע לנו כל הטובות ה­מחזיקות כו'\"; ואח\"כ מוסיף הכתוב חידוש גדול יותר, שגם \"כי תבא בקמת רעך\" — העבודה המוכרחת, גם בזה הדין דאכילת \"פועל\", היינו שהקב\"ה מסיר הדברים המונעים ומשפיע כל ה­טובות המחזיקות את הידים כדי שיוכל לעבוד עבודה זו.\nוזהו גם דיוק לשון רש\"י עה\"פ \"כי תבא בקמת רעך\" — \"אף זו בפועל ה­כתוב מדבר\", שכוונתו (ב\"יינה של תורה\" שבפרש\"י) היא לבאר, מדוע באמת מסיר הקב\"ה הדברים המונעים ומשפיע כל הטובות כו', כאשר עבודת האדם היא רק \"בקמת רעך\" (ולא מתוך תענוג, \"בשמחה ובטובת נפש\")? ומתרץ רש\"י, \"אף זו בפועל הכתוב מדבר\", דכיון ש­עבודת ישראל היא באופן של \"פועל\", לכן, הרי הוא אוכל ממלאכתו.\nו. ויובן זה בהקדים ביאור ג' ה­אופנים הנ\"ל בגדר אכילת \"פועל\" — כפי שהם בהנהגת הקב\"ה עם עמו ישראל — דע\"פ הכלל הידוע \"אלו ואלו דברי אלקים חיים\"<sup data-n=\"1072\">32</sup> מובן, שבהנהגת הקב\"ה (\"מה שהוא עושה\"), ישנם כל שלשת אופנים אלו.\nביאור הענין:\nביעודים גשמיים עצמם ישנם, ב­כללות, ג' אופנים:\nא) מילוי צרכי האדם, ענינים הכ­רחיים, \"לחם לאכול ובגד ללבוש\"<sup data-n=\"1073\">33</sup> — כדי שהאדם יוכל לחיות ולהתקיים.\nב) הסרת כל הדברים המונעים אותנו מקיום התומ\"צ כגון חולי ומלחמה ורעב וכיו\"ב, והשפעת כל הטובות כו' — ושני פרטים בזה: (א) זה כולל לא רק כל המוכרח בשביל חיי האדם אלא גם מצב של מנוחה ושלוה, (ב) הסרת כל הדברים המונעים (הנ\"ל) והשפעת כל הטובות באופן שאינו ע\"פ טבע.\nג) השלימות ביעודים גשמיים — \"באותו הזמן (ש)לא יהי' שם לא רעב ולא מלחמה ולא קנאה ותחרות שהטובה תהי' מושפעת הרבה וכל המעדנים מצויין כעפר\"<sup data-n=\"1074\">34</sup> — שאז יהי' כל העולם כולו במצב של שלימות כו', וכמובן בפשטות, דככל שיהי' מצב של מנוחה ושלוה (גשמית) בזמן הזה, אין זה דומה כלל וכלל למצב של שלוה ומנוחה ד­ימות המשיח, וכמ\"ש הרמב\"ם<sup data-n=\"1075\">35</sup> ש\"מפני זה נתאוו כל ישראל נביאיהם וחכמיהם לימות המשיח כדי שינוחו ממלכיות ש­אינן מניחות להן לעסוק בתורה ובמצות כהוגן וימצאו להם מרגוע וירבו בחכמה כו'\". הרי, שאף שהרמב\"ם האריך (ב­הלכה שלפנ\"ז) דכאשר איש ישראל עושה התורה בשמחה ובטובת נפש הבטיחה תורה שהקב\"ה יסיר ממנו כל הדברים המונעים כו' וישפיע לו כל ה­טובות כו' — מ\"מ, נתאוו אז חכמי ישראל לימות המשיח (ואינם מסתפקים בהסרת",[["1072","32","עירובין יג, ב."],["1073","33","ל' הכתוב — ויצא כח, כ."],["1074","34","רמב\"ם סוף הל' מלכים."],["1075","35","הל' תשובה שם ה\"ב."]]],[1301550206,"המניעות והשפעת הטובות שבזמן הזה), כי המרגוע האמיתי יהי' רק באותו הזמן.\nז. ויש לומר, שג' סוגים אלו באופן השכר הם כנגד ג' אופנים בעבודת ה­אדם:\nהשכר על עבודת האדם כשהיא רק למלאות את חובו — הם היעודים ה­גשמיים שבגדר שכר על עבודתו, דכשם ש\"מגיע\" לו תשלום בגמר עבודתו עבור עבודתו בתורה ומצוות (חיי עוה\"ב), כך מגיעה לו \"תוספת שכר\", שיוסרו ממנו מניעות כו' ויושפע לו טובות כו' בעת העבודה גופא — אבל כיון שזהו בגדר \"תשלום\", ה\"ז רק כפי המוכרח לחייו, \"לחם לאכול ובגד ללבוש\"<sup data-n=\"1076\">36</sup>.\nלמעלה מזה — כאשר האדם עובד ה' \"בשמחה ובטובת נפש\", ומקיים המצוות בהידור ולפנים משורת הדין, מתנהג הקב\"ה עמו ג\"כ לפנים משורת הדין, ומסיר ממנו כל הדברים המונעים ומש­פיע לו כל הטובות כו', ובאופן שלמעלה מן הטבע כנ\"ל.\nאמנם, שני אופנים אלו, הם בשביל האדם, דלהיות שהוא עובד השם, אם רק כפי חובתו, או גם לפנים משורת הדין, לכן, נותן לו הקב\"ה מדה כנגד מדה.\nאבל יש אופן שלישי — שהסרת ה­מניעות והשפעת הטובות אינה כדי לזכות את האדם, אלא בשביל העבודה עצמה. דכיון שעבודת השם בשלימות אינה אפשרית כ\"א בהסרת כל המניעות והשפעת כל הטובות, לכן, מביא הקב\"ה מצב זה, כדי שהעבודה תהי' כדבעי<sup data-n=\"1077\">37</sup>. ויש לומר, שזה תלוי בכך, שהאדם עובד השם באופן שמרגיש שכל מציאותו אינה אלא מה שהוא \"פועל\" של הקב\"ה. דלא רק שהוא מקיים תורה ומצוות, או גם עושה לפנים משורת הדין, אלא עוד זאת, שאין לו שום ענין בחייו מלבד עבודת השם, ובלשון הרמב\"ם<sup data-n=\"1078\">38</sup> \"עובד את ה' תמיד\". וכיון שכל מציאותו היא רק מה שהוא \"פועל\" של הקב\"ה, עובד השם, לכן, מביא הקב\"ה המצב שעבודתו תוכל להיות בתכלית השלימות, בלי שום מניעה כלל.\nוזה יהי' מצב בני ישראל באותו הזמן, שאז \"לא יהי' עסק כל העולם אלא לדעת את ה' בלבד\"<sup data-n=\"1074\">34</sup>, והיינו שלא יהי' שום עסק אחר מלבד עבודת השם, \"פנויין בתורה וחכמתה\"<sup data-n=\"1080\">*38</sup> — ולכן אז יהי' המרגוע האמיתי, ועד ליום שכולו שבת ומנוחה לחיי העולמים<sup data-n=\"1081\">39</sup>.\nועפ\"ז י\"ל שזהו החידוש (בפנימיות ה­",[["1076","36","בכללות גם זה נכלל ביעודים גשמיים, אף שאינו מפורש ברמב\"ם שם (ה\"א), כי הרמב\"ם שם א) בא לתרץ \"מהו זה שכתוב בכל התורה כולה אם תשמעו יגיע לכם כך כו', ושאר כל דברי הברית\", שבתוכם מבוארות השפעות מרובות, לא רק לחם לאכול ובגד ללבוש. ב) מבאר שכל השפעות הטובות המחזיקות את ידינו לעשות התורה הוא \"כדי. . (ש)נשב פנויים ללמוד כו' ולעשות כו' כדי שנזכה לחיי העולם הבא\", וכיון \"שלפי גודל מעשיו ורוב חכמתו הוא זוכה\", הרי כדי להגיע להשלימות בחיי עוה\"ב (ש\"נהנין מזיו שכינה שיודעים ומשיגין מאמתת הקב\"ה\" — רמב\"ם שם פ\"ח ה\"ב), הוא כאשר \"יודעו דעה גמורה נכונה\" שהוא דוקא כאשר הוא פנוי \"להתחכם בתורה ולעסוק בה\" (שם פ\"ט ה\"א), ולזה דרוש לא רק לחם לאכול כו' אלא השפעות מרובות כו'."],["1077","37","ראה לקמן הערה 39."],["1078","38","הל' דיעות ספ\"ג."],["1074","34","רמב\"ם סוף הל' מלכים."],["1080","*38","ל' הרמב\"ם הל' מלכים שם ה\"ד."],["1081","39","דמ\"ש הרמב\"ם ד\"נתאוו כל ישראל כו' כדי שינוחו ממלכיות כו' ירבו בחכמה כדי שיזכו לחיי העולם הבא\", אין הכוונה שרוצים ומתאווים לעוה\"ב בתור שכר, כ\"א לענינו שהוא שלימות העבודה — שהיא הדביקות בהשם ע\"י הדעת והאהבה, כמשנ\"ת בארוכה במ\"א — ראה לקו\"ש חל\"ג ס\"ע 87 ואילך."]]],[1301550207,"ענינים) בדיוק לשון רש\"י בפסוק \"כי תבא בקמת רעך\" — \"אף זו בפועל ה­כתוב מדבר\": אף שמדובר בהעבודה של \"קמת רעך\", לא עבודה מתוך תענוג אלא בדרך כפי' וקבלת עול כנ\"ל, מ\"מ, כיון שמציאותו האמיתית של כאו\"א מישראל הוא מה שהוא \"פועל\" של הקב\"ה, וכל דבר שעושה הוא ענין של עבודת השם (כי נצטווינו<sup data-n=\"1082\">40</sup> \"בכל דרכיך דעהו\") — לכן, גם הוא אוכל בעת מלאכתו, ש­הובטחו לו כל היעודים הגשמיים כדי שעבודתו תהי' מתוך מנוחה ומרגוע — בתכלית השלימות<sup data-n=\"1083\">41</sup>.\nאלא, שאם עבודתו היא \"בכרם רעך\", עבודה מתוך תענוג — אזי זוכה ל­\"ואכלת. . כנפשך שבעך\", והיינו אכילה תוך תענוג, עד לשביעה; משא\"כ כש­עבודתו היא רק מתוך קבלת עול, \"קמת רעך\", אזי זוכה רק ל\"וקטפת מלילות בידך\", בלי עונג.\nח. וע\"ד החסידות יש לפרש הענין דאכילת פועל בעת המלאכה בעומק יותר — שזה קאי על העונג מהעבודה גופא. והיינו, משום שעבודת בני ישראל גורמת נחת רוח למעלה, כמחז\"ל<sup data-n=\"1084\">42</sup> \"נחת רוח לפני שאמרתי ונעשה רצוני\", ואכילת הפועל ממלאכת רעהו שעסוק בה, מורה על הנאת האדם מזה שיודע שעבודתו גורמת נחת רוח להקב\"ה.\nובזה יש חילוק בין שני אופני ה­עבודה — \"כי תבא בכרם רעך\" ו\"כי תבא בקמת רעך\":\nכאשר עבודת האדם היא מתוך תענוג, הרי הוא בא ונכנס ל\"כרם רעך\" (זה הקב\"ה), היינו שמרגיש את תענוג הבורא<sup data-n=\"1085\">43</sup>. וזהו הפירוש הפנימי ב\"ואל כליך לא תתן\" — כי תענוג הבורא הוא למעלה ממדידה של \"כלים\", וזהו החי­דוש בכתוב, דאע\"פ שהמדובר באור אלקי שלמעלה מכלים, מ\"מ, כיון שה­אדם עובד השם מתוך תענוג, הרי \"ו­אכלת. . כנפשך שבעך\", שזוכה שאור זה מאיר בו בפנימיות, כמו מאכל ש­נעשה דם ובשר כבשרו, ועד שפועל בו שובע, \"כנפשך שבעך\"<sup data-n=\"1086\">44</sup>.\nוכאשר עבודת האדם היא בדרך כפי', אזי זוכה לבוא \"בקמת רעך\": \"קמה\" מורה על גדולה ורוממות, והיינו, דכיון שבעבודתו נרגש ענין העול וקבלת מלכותו של הקב\"ה, לכן זוכה להרגיש גילוי מלכותו ית', \"קמת רעך\", שאור זה בא ברוממות<sup data-n=\"1087\">45</sup>, ולכן לא נאמר בכתוב ע\"ד אכילת המלילות, כי אור זה אינו מאיר בפנימיות (כ\"כ), אבל מ\"מ גם אור זה משפיע על האדם, עד לעשי' ממש, \"וקטפת מלילות בידך\", דכיון שעבודתו היא בעשי' (ודרך כפי'), לכן נמשך האור עד למטה מטה, עד לכלי העשי' של האדם, \"ידיך\".\nט. ועל ידי עבודת בני ישראל בשני אופנים הנ\"ל, מתוך קבלת עול וכפי'",[["1082","40","משלי ג, ו. רמב\"ם הל' דיעות שם."],["1083","41","ומכיון דשם \"פועל\" חל עליו גם לפני שעובד בפועל ממש (ראה לעיל סוס\"ג), לכן, אף שבנוגע לדין אכילת פועל כפשוטו אינו אוכל לפני העבודה (כפרטי הדינים שבזה), הרי בנוגע לבנ\"י ואביהם שבשמים, משפיע הקב\"ה גם לפני העבודה בפועל — ראה רמב\"ם שם \"יסיר ממנו כו' וישפיע לנו כל הטובות כו' כדי כו' (אח\"כ) ללמוד כו' ולעשות כו'\"."],["1084","42","רש\"י ויקרא א, ט. ספרי שלח טו, ז. ספרי ורש\"י פינחס כח, ח. ועוד."],["1085","43","ראה המשך וככה תרל\"ז פי\"ב­יג."],["1086","44","ראה בארוכה לקו\"ש ח\"ה ע' 245 ואילך. וש\"נ."],["1087","45","ראה בהמשך ההילולא בפי' \"אסתלק יקרא דקב\"ה בכולהו עלמין\", שהגילוי הוא באופן של הסתלקות ורוממות. ע\"ש."]]],[1301550208,"(קמת רעך), ומתוך תענוג (כרם רעך), ובפרט בחודש אלול — משפיע הקב\"ה לבנ\"י כל צרכיהם נוסף על דברים המוכרחים, לחם לאכול ובגד ללבוש, גם כל הטובות המחזיקות את ידינו לעשות התורה, שובע שלום וריבוי כסף וזהב, לכאו\"א מבנ\"י, ופשיטא — כתיבה וחתימה טובה, לשנה טובה ו(גם) מתוקה, בבני חיי ומזונא (וכ\"ז) רוויחי,\nוהוא הכנה מתאימה להעבודה דראש השנה, ש\"מצות היום בשופר\"<sup data-n=\"1088\">46</sup>, שעל ידי השופר פועלים שיהי' תמליכוני עליכם, כמרז\"ל<sup data-n=\"1089\">47</sup> \"תמליכוני עליכם. . ובמה ב­שופר\", המשכת מלכותו של הקב\"ה, וכן \"שופר\" הוא מלשון שפרו מעשיכם<sup data-n=\"1090\">48</sup>, שהו\"ע התענוג, שעל ידי השופר ממשי­כים מפנימיות התענוג בכל סדר השתל­שלות<sup data-n=\"1091\">49</sup>, עד שזוכים לאמיתת התענוג שיתגלה לעתיד לבא, שכל המעדנים (דהעולם) מצויין כעפר, ולא יהי' עסק כל העולם אלא לדעת את השם בלבד<sup data-n=\"1074\">34</sup>, בביאת משיח צדקנו בקרוב ממש.\n<span data-k=\"q\">(משיחת ש\"פ תצא תשמ\"ה)</span>",[["1088","46","ר\"ה כו, ב (במשנה). שם כז, א. רמב\"ם הל' שופר פ\"א ה\"ב."],["1089","47","ר\"ה טז, סע\"א. לד, ב."],["1090","48","ויק\"ר פכ\"ט, ו."],["1091","49","סידור שער ר\"ה (רלה, סע\"א), שער ה­תקיעות (רמד, ג ואילך). ועוד."],["1074","34","רמב\"ם סוף הל' מלכים."]]],[1301550209,"<h3>שיחה ג</h3>\nא. כתב הרמב\"ם בהל' גירושין<sup data-n=\"1093\">1</sup> \"לא ישא אדם אשה ודעתו לגרשה, ולא תהי' יושבת תחתיו ומשמשתו ודעתו לגרשה\". וחזר ושנה דין זה בהל' איסורי ביאה<sup data-n=\"1094\">2</sup>, וז\"ל: אסור לאדם לישא אשה ודעתו לגרשה שנאמר<sup data-n=\"1095\">3</sup> אל תחרוש על רעך רעה והוא יושב לבטח אתך, ואם הודיעה בתחלה שהוא נושא אותה לימים מותר.\nולכאורה יש לעיין, אמאי הוצרך ה­רמב\"ם להביא הדין בב' המקומות — בהל' גירושין ובהל' איסורי ביאה<sup data-n=\"1096\">4</sup>?\nגם צ\"ל השינויים בין ב' המקומות: בהל' גירושין, הביא גם הדין \"ולא תהי' יושבת תחתיו ומשמשתו ודעתו לגרשה\" — שלא כתבו בהל' איסו\"ב; ובהל' איסו­רי ביאה — א) הביא מקור לזה מהפסוק \"אל תחרוש גו'\", ב) הוסיף אופן שלא חל איסור זה — \"ואם הודיעה בתחלה. . מותר\".\nוהנה מקור דינים אלו הוא בב' סוג­יות בש\"ס (כמובא בנ\"כ): במס' יבמות<sup data-n=\"1097\">5</sup> הובאה ברייתא דר\"א בן יעקב \"לא ישא אדם אשתו (אשה<sup data-n=\"1098\">6</sup>) ודעתו לגרשה משום שנאמר אל תחרוש על רעך רעה והוא יושב לבטח אתך\"; ובמס' גיטין<sup data-n=\"1099\">7</sup>: א\"ל ר' משרשיא לרבא אם לבו לגרשה והיא יושבת תחתיו ומשמשתו מהו קרי עלי' אל תחרוש על רעך רעה והוא יושב לבטח אתך.\nומזה שבגמ' הובא הפסוק \"אל תחרוש גו'\" הן על הדין ד\"לא ישא כו' ודעתו לגרשה\" והן על הדין ד\"לבו לגרשה והיא יושבת תחתיו כו'\" מוכח, שגם הדין השני מקורו בפסוק זה. וא\"כ צ\"ל, למה הביא הרמב\"ם פסוק זה רק בהל' איסו\"ב לראי' על הדין הראשון (לא ישא כו') ולא בהל' גירושין (ששם הביא את ב' הדינים הנ\"ל)?\nב. וי\"ל בכל זה: ידוע שאין דרכו של הרמב\"ם בס' היד להביא המקורות בכתוב (שהובאו בגמרא כו') להדינים שכותב באמצע ההלכות והפרקים, אלא כאשר המקור נוגע להגדרת (וכיו\"ב)",[["1093","1","פ\"י הכ\"א."],["1094","2","פכ\"א הכ\"ח."],["1095","3","משלי ג, כט."],["1096","4","גם בטושו\"ע הובא הדין באה\"ע ב\"פ: בהל' פו\"ר ס\"ב סיו\"ד ובריש הל' גיטין סקי\"ט, אבל כן מצינו כמ\"פ בטושו\"ע שהובאו דינים יותר מפ\"א. משא\"כ הרמב\"ם שלכאורה פחות רגיל בזה\nאף שכמה דינים (כללים) חוזר עליהם כמה פעמים, ואפילו בפרקים סמוכים זל\"ז (כגון שהולכין אחר מנהג המדינה)\nובפרט שביד הכלל \"שדרך הרמב\"ם לפרש דבריו במקום אחד בס' היד ובמקום אחד סותם דבריו וסומך. . על מ\"ש כבר במקום אחר הקודם לזה\" (יד מלאכי כללי הרמב\"ם כו' אות ו').\nונת' במ\"א (ראה לקו\"ש חט\"ו ס\"ע 373 ואילך) טעם החילוק, כי השו\"ע כשמו כן הוא דינים ערוכים לידע איך לעשות המצות בזמן חיובם ומתאים שיבא הדין יותר מפ\"א; משא\"כ ספר היד שענינו (כמ\"ש בהקדמתו) \"ויודע ממנו תושבע\"פ כולה\", ידיעת (דיני) התורה, וכאשר נכתב במקום א' (\"הקודם לזה\") — כבר ידוע לו. ורגיל ביד לומר \"כאשר בארנו\" וכיו\"ב. ויש להאריך בכ\"ז (ובעזרת קונקורדנציא דהיד). ואכ\"מ."],["1097","5","לז, ב."],["1098","6","כן הוא ברי\"ף ורא\"ש יבמות שם (ובסוף גיטין). וכן גי' המהרש\"ל ועוד — הובא עה\"ג שם."],["1099","7","צ, א."]]],[1301550210,"ההלכה, אף שבמנין המצוות שבתחלתו דייק להביא הכתוב וכן בתחלת ההל' (שמן התורה).\nולכן הביא הכתוב דוקא בהל' איסו\"ב, כי שם מתבאר עי\"ז המשך ה­הלכה \"ואם הודיעה בתחלה שהוא נושא אותה לימים מותר\", שזהו החידוש בהל' איסו\"ב, כי היתר זה הוא (לדעת ה­רמב\"ם) רק בהדין דתחלת נישואין — \"לא ישא. . ודעתו לגרשה\", ולא כשכבר \"יושבת תחתיו\" — וזה נלמד מהפסוק שהביא, וכדלקמן.\nוהביאור בזה: במ\"ש \"אל תחרוש על רעך רעה והוא יושב לבטח אתך\" (שמו­בן, שכתוב זה מיירי ב\"רעה\" שמצ\"ע היא מותרת ע\"פ תורה<sup data-n=\"1100\">8</sup>), יש לברר — מהו עיקר האיסור בזה, שיש לפרשו בב' או­פנים: א) ההדגשה בהאיסור ד\"אל תח­רוש גו'\" היא — ההנהגה המגונה (ומדה רעה) של האיש החורש רעה, שמרמה את חבירו וחורש עליו רעה כאשר חברו \"יושב לבטח אתך\"; ב) שהעיקר הוא הצער ובזיון חבירו — שישיבתו \"לבטח אתך\" היא באופן בזוי (מאחר שחורש עליו רעה).\nוהנפק\"מ מזה להלכה — כאשר ה­\"חורש רעה\" הודיע לחבירו עד\"ז, אלא שחבירו הוא במצב שבכ\"ז ממשיך הוא לשבת אתו (מאיזה טעם שהוא): לאופן הא', מכיון שהודיעו מזה, ומעתה אין ישיבתו אתו באופן ד\"לבטח\", ואין כאן מרמה, הרי אין זו ההנהגה שאסרתה תורה; משא\"כ לאופן הב' — לא יצא מכלל איסור בהודעה זו, מאחר שסו\"ס (קשה לחבירו לצאת מישיבה זו עם זה שחורש עליו רעה, ו)ה\"ה מצטער מזה, ולכן יש בזה משום \"אל תחרוש. . רעה גו'\".\nועפ\"ז יש לומר טעם מחלוקת ה­פוסקים בנדו\"ד כאשר \"יושבת תחתיו ומשמשתו ודעתו לגרשה\" — אם מהני הודעתו שדעתו לגרשה: י\"א שהודעה מהני רק בתחלת הנישואין, ד\"אם בתחלה נתרצית להיות אצלו לזמן מוגבל סברה וקבלה אבל כשהודיעה אח\"כ לגרשה מה לה לעשות ולבה מצטערת בקרבה וקרינן בי' אל תחרוש על רעך רעה\"<sup data-n=\"1101\">9</sup>, דס\"ל כאופן הב' הנ\"ל; אבל לדעת כמה פוסקים<sup data-n=\"1102\">10</sup>, \"עיקר האיסור\"<sup data-n=\"1103\">11</sup> שחורש רעה הוא דוקא כש\"הוא יושב לבטח\", ולכן \"אי מודיע לה שדעתו לגרשה שפיר דמי וקרא הכי דייק אל תחרוש על רעך רעה והוא יושב לבטח אתך הא אינו יושב לבטח דהיינו שמודיע לה לית לן בה\"<sup data-n=\"1104\">12</sup>, וכאופן הא' הנ\"ל.\nג. וי\"ל, דלדעת הרמב\"ם תרווייהו איתנהו בי', היינו שיש ב' דינים באיסור",[["1100","8","דבהנהגה אסורה מצ\"ע — ה\"ה עובר משום כמה איסורים המפורשים בתורה, אונאת חבירו וכו'."],["1101","9","ל' החלקת מחוקק אה\"ע ר\"ס קיט. וכ\"ה בבאר היטב שם סק\"ב.\nבפרישה אה\"ע סי' כה אות ל' (הובא בב\"ש רסקי\"ט), דאחר הנישואין לא מהני אם מודיע לה. אבל שם הוא מטעם אחר, דהאיסור הוא משום \"בני תשע מדות. . בני גרושת הלב\". [וראה בב\"ש שם, גט פשוט שם אות ג', מל\"מ לרמב\"ם הל' איסו\"ב שם, ועוד — אם הא ד\"יושבת. . ומשמשתו\" איירי דוקא בבא עלי', או גם כשלא בא עלי'. ואכ\"מ]."],["1102","10","פר\"ח שבהערה 12. אופן הא' בח\"מ שם. וראה לקמן שם."],["1103","11","ראה ט\"ז אה\"ע שם (סקי\"ט) סק\"ב."],["1104","12","ל' הפר\"ח אה\"ע שם רסקי\"ט (ומסיים: וכ\"כ בתשובת הגאונים בסימן קפח). וכ\"ה במאירי סוף גיטין. וכ\"ה בהשגות הראב\"ד שעל הרי\"ף סוף גיטין — הובא גם בהגהות רע\"א אה\"ע שם (מכנה\"ג). וכן מפורש בגט פשוט שם אות ד'. וראה יש\"ש יבמות פ\"ד ס\"ו (בדעת הראב\"ד הל' איסו\"ב פי\"א ה\"י. ע\"ש)."]]],[1301550211,"הנ\"ל (דין אחד מצד הנהגת האדם ודין שני מצד צער רעהו), ומקורם בב' סוגיות הש\"ס:\nביבמות (בהברייתא דראב\"י) \"לא ישא אדם אשה ודעתו לגרשה משום שנאמר אל תחרוש גו'\", קאי בדין האיסור מצד הגנאי של החורש רעה, שזוהי פשטות תוכן הכתוב — עשיית רעה לחבירו במצב שחברו \"יושב לבטח אתך\", ואיסור זה חל (להרמב\"ם) דוקא כאשר הישיבה עם רעהו באה מלכתחילה באופן שחורש רעה, והיינו שזוהי כוונתו בתחלת הנישואין — ע\"מ לגרשה לאח\"ז;\nמשא\"כ במס' גיטין מחדש רבא, שגם \"אם לבו לגרשה והיא יושבת תחתיו ומשמשתו\", אין זו הנהגה מתאימה ע\"פ הכתוב \"אל תחרוש גו'\", אמנם זה אינו (כ\"כ) מצד גנות ההנהגה של זה החורש רעה, כ\"א מפני שישיבתו של רעהו אתו \"לבטח\" היא מצב בזוי ומצער, מאחר שחורש עליו רעה, וכנ\"ל.\n[אלא שאין זה פשטות תוכן הכתוב, ולכן דייק בלשונו ולא אמר \"אסור משום אל תחרוש גו'\" וכיו\"ב, כ\"א \"קרי עלי' אל תחרוש גו'\" — שגם על זה יכול אדם לקרות הכתוב \"אל תחרוש גו'\"].\nומובן שמצד דין זה ד\"אל תחרוש\", דהיינו איסור גרימת הצער לרעהו, אינה מועילה הודעה בתחלה כשיושבת תחתיו ומשמשתו ודעתו לגרשה. וכנ\"ל.\nוהם הם שתי ההלכות ברמב\"ם: בהל' גירושין מביא דינו של רבא (שבמס' גיטין) ד\"לא תהי' יושבת תחתיו כו'\" מחמת גרימת צער לחבירו; ואילו בהל' איסורי ביאה מביא (מברייתא דראב\"י) האיסור לישא אשה ודעתו לגרשה. ולכן הוצרך להביא כאן הכתוב \"אל תחרוש גו'\", ולא כתב גם הדין ד\"לא תהי' יושבת. . ודעתו לגרשה\" — כי כוונתו כאן היא להגדרת ההלכה והחידוש דין שבזה, אשר דין זה איסורו הוא משום \"אל תחרוש\" (ולא מטעם גרימת צער כו') ולכן — \"אם<sup data-n=\"1105\">13</sup> הודיעה בתחלה<sup data-n=\"1106\">14</sup>. . מותר\"<sup data-n=\"1107\">15</sup>.\nאבל עדיין אינו מיושב לגמרי, כי מפשטות ל' הרמב\"ם בהל' איסו\"ב \"אסור לאדם לישא אשה ודעתו לגרשה שנאמר כו' ואם כו'\", משמע דבא להודיע לא רק הגדרת ההלכה שכבר כתבה בהל' גירו­שין (והאופן שמותר), אלא גם (ובעיקר) גוף האיסור.\nגם: לפי הנ\"ל דב' ההלכות חלוקות בגדרם — הו\"ל להביא האיסור ד\"לא ישא אדם אשה ודעתו לגרשה\" רק בהל' איסו\"ב, ביחד עם (המקור מהכתוב ו)ההיתר, ובהל' גירושין הו\"ל להביא רק",[["1105","13","וכבר שקו\"ט במקורו דהרמב\"ם ובתירוץ קושית הב\"י אה\"ע ס\"ב על דברי הטור שם, שתלה הדין ד\"אם הודיעה תחלה כו'\" בהרמב\"ם — \"דהרי מבואר הוא בפרק החולץ\" (ראה ב\"ח ודרישה שם. גט פשוט שם אות ב'. מל\"מ הל' איסו\"ב שם. ועוד)."],["1106","14","הדין דאם הודיעה שנושאה לימים מותר, הובא גם בסמ\"ג ל\"ת קכו. רבינו ירוחם נתיב כג ח\"ב בשם הרמ\"ה (\"ואם התנה מותר\"). מאירי יבמות שם. ארחות חיים (להר' אהרן מלוניל) ח\"ב ביאות אסורות סכ\"ה וכל בו סו\"ס עה (ע\"ש). ועוד. וראה במקומות שבהערה הקודמת."],["1107","15","ומה שהרמב\"ם הוצרך להודיע בפירוש אף שלכאורה מובן הוא מעצמו [וראה מל\"מ שם ד\"ה ומ\"מ דברי הטור, דגם להרי\"ף והרא\"ש שלא הביאו ההיתר דמודיעה, שרי כאשר מודיעה \"ומה שלא הביאו הנהו עובדי דרב ור\"נ הוא משום דטעמא דאיסורא הוי משום אל תחרוש. . וממילא נפקא דאם הודיעה שרי שהרי אינה יושבת לבטח עמו כו'\"], כי בספר הלכות צריך לומר ההיתר באופן ברור. והרי לפי הנ\"ל ה\"ז מפורש בש\"ס (ביבמות שם בעובדא דרב ור\"נ). וראה בהנסמן לעיל הערה 13."]]],[1301550212,"הדין (דמס' גיטין) ד\"אם יושבת תחתיו כו'\"?\nד. ויובן בהקדם דיוק בשינוי לשון הרמב\"ם בין הל' גירושין והל' איסו\"ב, דבהל' גירושין כתב \"לא ישא אדם אשה ודעתו לגרשה\", ובהל' איסו\"ב כתב \"אסור<sup data-n=\"1108\">16</sup> לאדם לישא אשה ודעתו לגר­שה\"<sup data-n=\"1109\">17</sup>.\nומסתבר לומר, דלדעת הרמב\"ם יש כאן ב' דינים שונים, דין בהל' אישות וגירושין, ודין באופן ההנהגה בין איש לאשתו, והוא (בהל' איסו\"ב) מהכתוב \"אל תחרוש גו'\".\nוההסברה בזה:\nמהות וגדר נישואין דאיש ואשה (כד­בעי) הוא — בל' הכתוב<sup data-n=\"1110\">18</sup> \"ודבק באשתו והיו לבשר אחד\", קנין ודבקות תמידי, בלי שום פרט המוליך וגורם להפסק [וענין הגירושין הוא דבר שמתחדש אחר הקידושין והנישואין, שמחליש וסותר ועד שכורת הקשר (\"דבק\") הזה].\nאבל כאשר קנין ותוכן הנישואין הוא באופן שיש בו פרט היפך של \"ודבק\", הן בתחלת הנישואין<sup data-n=\"1111\">19</sup> או לאחר זמן, הרי זה חסרון בעצם הנישואין<sup data-n=\"1112\">20</sup>.\nוזהו תוכן ההלכה שבהל' גירושין \"לא ישא אדם אשה ודעתו לגרשה ולא תהי' יושבת תחתיו ומשמשתו ודעתו ל­גרשה\", היינו דאף שאין בזה איסור, מ\"מ אין זה ענין \"נישואין\" לאמיתתו ע\"פ תורה, ולכן \"לא ישא אדם כו' ולא תהי' יושבת כו' ודעתו לגרשה\".\nולכן ממשיך הרמב\"ם באותה ההלכה \"ולא יגרש אדם אשתו ראשונה אלא א\"כ מצא בה ערות דבר שנא' כו' ואין ראוי לו למהר לשלח אשתו ראשונה\", כי תוכן דינים אלו אחד הוא: גדר ענין הנישואין מצד עצמן — \"ודבק\", שאינו נותן מקום להפכו (פירוד) כלל<sup data-n=\"1113\">21</sup>.\nאמנם ישנו דין נוסף — ד\"אל תחרוש על רעך רעה והוא יושב לבטח אתך\", והוא איסור בהנהגות בני אדם זל\"ז, וכן בהנהגת איש ואשה — ד\"אסור לאדם לישא אשה ודעתו לגרשה\". ולכן כתב הרמב\"ם דין זה בהל' איסו\"ב, בפרק שבו מבאר גדרי הנהגות איש ואשה זל\"ז, ביניהם (וכן כלפי בניהם וכו').\nה. וי\"ל, שמקורו של הרמב\"ם הוא מב' המימרות הנ\"ל שבש\"ס — הברייתא דראב\"י במס' יבמות והאיבעי' דר' משרשיא (ומענה רבא ע\"ז) במס' גיטין:\nבמס' יבמות בא מאמר ראב\"י בהמשך לכמה מאמרים ע\"ד איסורי חתנות (מצד חששות ותקלות שיכולים לבוא מזה) —",[["1108","16","לשון \"אסור\" מובא גם בסמ\"ג. ובא\"ח וכל בו שם \"אסור לאדם להשהות עם אשתו ודעתו לגרשה אם לא כו'\". ולהעיר מהשינוי בלבוש אה\"ע סקי\"ט: בס\"ג כתב לא ישא אדם אשה ודעתו לגרשה שהוא מטעה אותה כו', ובס\"ד כ' \"ואם נשאה סתם והיא משמשתו. . והוא יש בדעתו לגרשה עובר על לאו. . לא תחרוש כו'\"."],["1109","17","וראה גט פשוט שם סוף אות ו."],["1110","18","בראשית ב, כד."],["1111","19","להעיר מרמב\"ם הל' גירושין פ\"ג ה\"ו: אמר לסופר כתוב גט לפלונית. . לכשאשאנה אגרשנה בו. . אינו גט מפני שלא היתה בת גירושין ממנו כשנכתב גט זה — ראה צפע\"נ לרמב\"ם שם."],["1112","20","להעיר מט\"ז שם סק\"א, דודאי מיירי (אפילו) שלא גירשה אח\"כ ואפ\"ה איסורא איכא בשעת נישואין להיות דעתו כן."],["1113","21","להעיר מסתימת ל' הרמב\"ם \"ולא יגרש אדם אשתו ראשונה אלא א\"כ מצא בה ערות דבר שנא' כי מצא בה ערות דבר\", ואינו מפרט או ערוה או דבר כדעת ב\"ה שם (וראה ב\"ש אה\"ע שם סק\"ב ואילך. ט\"ז שם סק\"ג). וי\"ל כי אין כוונתו כ\"כ לגדר האיסור שבזה אלא — דאינו מתאים מצד גדר ענין הנישואין והגירושין. וראה גט פשוט שם אות ה'. מל\"מ לרמב\"ם שם."]]],[1301550213,"ודינים אלו כן הביא הרמב\"ם בהל' של­אח\"ז בהל' איסו\"ב שם<sup data-n=\"1114\">22</sup> — ובהמשך לזה בא המאמר בנוגע לאיסור כלפי אשתו ד\"לא ישא אדם אשתו (אשה) ודעתו לגרשה משום שנאמר אל תחרוש על רעך רעה והוא יושב לבטח אתך\";\nאבל בגיטין הוא בהמשך הסוגיא והשקו\"ט בביאור המחלוקת דב\"ש ב\"ה ור\"ע מתי מותר לגרש דילפינן מהכתו­בים בפ' גירושין<sup data-n=\"1115\">23</sup> \"והי' אם לא תמצא חן בעיניו כי מצא בה ערות דבר\"; וב­המשך לתשובת רבא לשאלת ר\"פ \"לא מצא בה ערוה ולא דבר מהו\" — \"מדגלי רחמנא גבי אונס<sup data-n=\"1116\">24</sup> לא יוכל לשלחה כל ימיו כו' התם הוא דגלי רחמנא אבל הכא מאי דעבד עבד\" (ואח\"כ ממשיך (ב­ברייתא דר\"מ) כמה דעות (מדות) בקשר איש ואשה — בשייכות לגירושין).\nולכאו' מה שייך בתוך סוגיא זו — שתוכנה: מתי מותר לגרש, ואם הגירו­שין מהני — שאלת רב משרשיא לרבא \"אם לבו לגרשה והיא יושבת תחתיו ו­משמשתו מהו\" (יש עונש בדבר או לא<sup data-n=\"1117\">25</sup>)? ועוד: הרי מפורש בברייתא דראב\"י ד­לא ישא אדם אשה ודעתו לגרשה משום אל תחרוש גו', ומאי מספקא לי' לרב משרשיא<sup data-n=\"1118\">26</sup>?\nומזה הוכיח<sup data-n=\"1119\">27</sup> הרמב\"ם, דשאלת רב משרשיא היא אם זהו מעצם פרשת נישואין (וגירושין), ולא רק איסור פרטי מטעם \"אל תחרוש גו'\";\nותשובת רבא \"קרי עלי' אל תחרוש גו'\" — אין כוונתו דאסור מצד \"אל תחרוש\" (כי אז הול\"ל \"לא תהי' יושבת. . משום אל תחרוש\", או \"אסור משום אל תחרוש\" וכיו\"ב), כ\"א — דפסוק זה הוי גילוי מילתא שאין אלו נישואין כדבעי, כי בנישואין כאלו \"קרי עלי' אל תחרוש על רעך רעה והוא יושב לבטח אתך\";\nונמצא דהחילוק בין ברייתא דראב\"י ביבמות ומאמר רבא בגיטין הוא: ביבמות בא הכתוב \"אל תחרוש על רעך רעה גו'\" כמקור הדין ד\"לא ישא אדם אשה ודעתו לגרשה\", ובגיטין הרי זה גילוי מלתא בגדרן של נישואין ע\"פ תורה, שכל זמן הנישואין ה\"ודבק באשתו\" הוא בשלימות בלי פרט של הפסק כו'.\nועפ\"ז מובן גם הטעם שלא הביא הרמב\"ם בהל' גירושין הא ד\"אם הודיעה בתחלה כו' מותר\" — כי ההיתר ב\"הודיעה\" הוא רק כלפי האיסור ד\"אל תחרוש על רעך רעה והוא יושב לבטח אתך\", אבל אין זה נוגע ומשנה בשייכות להחסרון בגוף גדר נישואין (וגירושין)<sup data-n=\"1120\">28</sup>, כי גם כאשר מודיעה שדעתו לגרשה, הרי זה גורע בגוף ענין הנישואין (וה­גירושין)<sup data-n=\"1121\">29</sup>.",[["1114","22","הכ\"ט."],["1115","23","פרשתנו כד, א."],["1116","24","שם כב, כט."],["1117","25","פרש\"י גיטין שם."],["1118","26","ראה יש\"ש שם. ט\"ז סק\"ב. פר\"ח שם סק\"א. גט פשוט שם אות ד'. עיון יעקב לע\"י שם. ועוד."],["1119","27","להעיר שברי\"ף גיטין שם, לאחר הסיום \"מכלל דהכא מאי דעבד עבד\" ולפני שאלת רב משרשיא לרבא — הוסיף \"ש\"מ דהיכא דלא מצא בה לא דבר ולא ערוה לכתחלה לא יגרש\"."],["1120","28","אבל אין בזה איסור כ\"א שאי\"ז נישואין בשלימות, ולכן הותר זה כאשר מתכוונים ליר\"ש שיהי' פת בסלם ולא יתאוו כו' כמו רב ור\"נ ביבמות שם — ראה גט פשוט שם אות ב' בסופו."],["1121","29","ע\"פ כהנ\"ל יומתק ביותר מה שהביא הרמב\"ם בהל' איסו\"ב \"ואם הודיעה כו' מותר\" — אף שלכאו' מובן הוא מעצמו מגדר האיסור (כנ\"ל הערה 15 ממל\"מ), כי מצד גדר הנישואין אין לזה מקום (אלא שהאיסור ד\"אל תחרוש גו'\" בטל)."]]],[1301550214,"ו. וי\"ל בפנימיות הענינים:\nאיש ואשה בכל פרטיהם למטה, הם בדוגמת (ובאו ונשתלשלו מ)\"איש ואשה\" — זה הקב\"ה (איש) ובני ישראל (אשה), כמבואר בארוכה בשה\"ש ובמדרז\"ל.\nוכן הוא בנוגע לנדו\"ד — נישואי (וגי­רושי) איש ואשה, הרי זה בא ומסתעף מהנישואין, כביכול, שבין הקב\"ה וכנס\"י. וכנוסח הברכה שאומרים בהאירוסין דכאו\"א מישראל \"מקדש עמו ישראל ע\"י חופה וקדושין\". והיינו שחתונתם (קידו­שין ונישואין) של כאו\"א מישראל, הרי זה פרט, כביכול, ממקדש עמו ישראל, מ\"נישואין\" הכלליים שבין הקב\"ה ועמו (כנס\"י).\nועפ\"ז יומתק ביותר מה שמגדרי הנישואין הוא — שהם בקשר נצחי<sup data-n=\"1122\">30</sup>, לפי שנשואי הקב\"ה וכנס\"י, וכמ\"ש<sup data-n=\"1123\">31</sup> ביום חתונתו (של הקב\"ה עם בנ\"י) זה מ\"ת, הוא קשר נצחי (שא\"א להיות בזה<sup data-n=\"1124\">32</sup> הפסק ח\"ו).\nז. אמנם, ע\"פ משנת\"ל בגדר האיסור ד\"לישא אשה ודעתו לגרשה\" — שזהו (לא רק הנהגה מגונה מצד האיש, אלא) חסרון בעצם הנישואין — צריך ביאור בנישואי הקב\"ה וכנס\"י:\nידוע, שכללות ענין הגלות הוא בדוג­מת ענין הגירושין<sup data-n=\"1125\">33</sup>, וכדאיתא במדרש \"דנתי אותם בגירושין\"<sup data-n=\"1126\">34</sup>. וכדאיתא ב­גמרא<sup data-n=\"1127\">35</sup> \"תשובה נצחת השיבה כנסת ישראל לנביא כו' אשה שגרשה בעלה כלום יש לזה על זה כלום\"; ומכיון שהקב\"ה ידע שיהי' ענין הגלות — הרי נמצא שיש בזה, כביכול, משום \"לא ישא אדם אשה ודעתו לגרשה\"?\nבפשטות י\"ל שאין שייך לומר בזה ש\"דעתו לגרשה\", כי כל ענין הגלות הוא רק תוצאה מהנהגת ישראל, ויש בזה בחירה חפשית בשלימות, ורק \"מפני חטאינו (שלנו) גלינו מארצנו\", ולולא החטאים שלנו לא היו כלל הגירושין.\n[ואף שמפורש בתורה<sup data-n=\"1128\">36</sup> \"כי תוליד בנים ובני בנים ונושנתם בארץ והשחתם וגו' והפיץ ה' אתכם בעמים גו'\", שנאמר בלשון ודאי (שכן יהי' בפועל), והרי התורה קדמה לעולם<sup data-n=\"1129\">37</sup>, ונמצא דכבר בעת מ\"ת הי' כביכול \"בדעתו לגרשה\" לאחר זמן (כאשר \"נושנתם בארץ גו'\") —\nאין זו שאלה, כי (א) פסוקים אלו נאמרו לאחר מ\"ת, בשנת הארבעים, וכל זמן שלא נתגלה בדיבורו של הקב\"ה<sup data-n=\"1130\">38</sup>, עדיין יכול להיות בזה שינוי; וגם (ב) אפילו אם נאמר שנחשבים כ\"דיבור\", ואפילו לאחרי שנאמרו בפועל, הרי כתב הרמב\"ם<sup data-n=\"1131\">39</sup> בנוגע לדברי פורעניות שה­נביא אומר \"אם לא עמדו דבריו אין בזה הכחשה לנבואתו. . שהקב\"ה ארך אפים ורב חסד ונחם על הרעה, ואפשר שעשו תשובה ונסלח להם\"].\nאבל עדיין אינו מיושב כל צרכו, כי מאחר שסו\"ס ידע הקב\"ה בעת מ\"ת",[["1122","30","אלא שאפשר (ולפעמים) מתחדש קנין חדש \"גט ומיתת הבעל\" (ריש קידושין)."],["1123","31","תענית כו, ב (במשנה). וראה במדב\"ר פי\"ב, ח (בסופו)."],["1124","32","משא\"כ בקשר הנעשה ע\"י בנ\"א."],["1125","33","וראה מהר\"ם שי\"ף בסוף מס' גיטין."],["1126","34","ב\"ר פי\"ט, ט. פתיחתא דאיכ\"ר ד (וש\"נ). וראה יפ\"ת השלם ונזר הקדש לב\"ר שם. מהר\"ם שי\"ף שם. וראה ירמי' ג, ח: שלחתי' ואתן את ספר כריתותי' אלי'."],["1127","35","סנהדרין קה, א. וראה בכ\"ז לקו\"ש ח\"ט ע' 146 ואילך. וש\"נ."],["1128","36","ואתחנן ד, כה ואילך (הקריאה דת\"ב)."],["1129","37","ראה פסחים נד, א. ב\"ר פ\"א, ד. וש\"נ."],["1130","38","ראה מדרש תהלים ט, א. תו\"ח תולדות יג, ג ואילך. ועוד."],["1131","39","הל' יסוה\"ת פ\"י ה\"ד."]]],[1301550215,"שיהי' ענין הגלות, א\"כ גם את\"ל שאי\"ז בגדר של \"דעתו (ורצונו) לגרשה\" — כי ניתנה הבחירה לאדם להתנהג באופן שלא יהי' גלות (וזהו רצונו של הקב\"ה) — מ\"מ, הרי סו\"ס לא נעשו הנישואין (מצדו יתברך) באופן של קשר של קיימא, קשר נצחי — ונמצא שיש חסרון ח\"ו בנישואי הקב\"ה וישראל?\nח. והביאור בזה:\nבגמ' שם<sup data-n=\"1127\">35</sup> ממשיך שהקב\"ה משיב לכנסת ישראל \"אי זה ספר כריתות אמכם אשר שלחתי'\", היינו שלא הי' גירושין (\"ספר כריתות\").\nועכצ\"ל, דזה שאיתא בגמ' שם לפנ\"ז \"תשובה נצחת השיבה כנסת ישראל כו' אשה שגרשה בעלה כו'\", ה\"ז מפני שגלות הו\"ע של גירושין (רק) מצד כנסת ישראל, שבזמן הגלות אין בנ\"י מרגישים קירובו של הקב\"ה אליהם, ולכן טוענים שזהו מצב של \"אשה שגרשה בעלה\";\nאבל האמת הוא, שגם בזמן הגלות לא נפסקו ח\"ו הנישואין בין הקב\"ה וכנס\"י (אלא שלא נראים באופן גלוי).\nואדרבה, כל הכוונה של ההסתר פנים דזמן הגלות, \"ואנכי הסתר אסתיר פני גו'\"<sup data-n=\"1133\">40</sup>, היא רק כדי שיהי' \"ובקשתם משם את ה\"א ומצאת כי תדרשנו בכל לבבך ובכל נפשך. . ושבת עד ה' אלקיך ושמעת בקולו\"<sup data-n=\"1134\">41</sup>, שעי\"ז מתגלה קשר \"ודבק\" עמוק יותר, שגם בהיות בנ\"י נפוצים בעמים, הם אשתו של הקב\"ה ודבוקים עמו.\nועל ידי שבנ\"י מתנהגים כ\"אשה כשרה\" ומראים דביקותם בה' (בקיום התומ\"צ) הרי, מדה כנגד מדה, גם הנהגת הקב\"ה עם ישראל היא באופן כזה, ש­(אפילו) כל העמים רואים שאין גירושין בין הקב\"ה ובנ\"י, ורואים בעליל שמירת והשגחת הקב\"ה על ישראל, והוא יתברך ממלא את כל צרכיהם (שארה כסותה ועונתה<sup data-n=\"1135\">42</sup>) באופן שגם ב(סוף) זמן הגלות ישנו \"רב טוב לבית ישראל\"<sup data-n=\"1136\">43</sup> כפשוטו,\nוהולכים תיכף ומיד אל הגאולה האמיתית והשלימה, שאז תהי' בגלוי שלימות הנישואין בין הקב\"ה וכנס\"י \"והי' ביום ההוא נאם ה' תקראי אישי ולא תקראי לי עוד בעלי\"<sup data-n=\"1137\">44</sup>, בביאת משיח צדקנו בעגלא דידן ממש.\n<span data-k=\"q\">(משיחות ש\"פ קרח תשמ\"ה, ל\"ג בעומר תשמ\"ו)</span>",[["1127","35","סנהדרין קה, א. וראה בכ\"ז לקו\"ש ח\"ט ע' 146 ואילך. וש\"נ."],["1133","40","וילך לא, יח."],["1134","41","ואתחנן שם, כט ואילך."],["1135","42","משפטים כא, יו\"ד. וצריך ליזהר מאד כו' שלא לצערה כו' ויהא זהיר בכבודה (שו\"ע אדה\"ז הל' אונאה בסופן)."],["1136","43","ישעי' סג, ז — הפטרה האחרונה ד\"שבעה דנחמתא\"."],["1137","44","הושע ב, יח. וראה שמו\"ר ספט\"ו \"העולם הזה אירוסין. . לימות המשיח יהיו נישואין\"."]]],[1301550216,"<h3>שיחה א</h3>\nא. בספרי ריש פרשתנו נדרש הפסוק \"והי' כי תבוא<sup data-n=\"1138\">1</sup> אל הארץ\" — \"אין והי' אלא מיד\". ומשמעות הדרש, לכאורה, שחיוב מצות ביכורים (שבו מדבר ב­פרשה זו) חל מיד בבואם לארץ<sup data-n=\"1139\">2</sup>.\nולכאורה תמוה (כמו שהקשו במפר­שים<sup data-n=\"1140\">3</sup>) — הרי מפורש בהמשך הכתוב \"ו­ירשתה וישבת בה\", שאין חייבים בבכו­רים עד לאחרי ירושה וישיבה (דהיינו כיבוש וחלוקת הארץ<sup data-n=\"1141\">4</sup>), כמובא בפרש\"י כאן, וכמפורש במס' קידושין<sup data-n=\"1142\">5</sup> דגבי בכורים כו\"ע מודי שלא נתחייבו עד לאחרי ירושה וישיבה<sup data-n=\"1143\">6</sup>.\nיש מפרשים<sup data-n=\"1144\">7</sup> כוונת הספרי \"שמיד יבואו לארץ\", כלומר, שמ\"ש בספרי \"מיד\" לא קאי על חיוב הבאת בכורים, אלא הוא בנוגע (בשורת) הביאה לארץ, ש\"מיד — תבוא אל הארץ\".\n[ולפירוש זה מובן גם המשך הדרשות בספרי, שלאחרי דרשה זו (\"אין והי' אלא מיד\") ממשיך: \"כי תבוא אל הארץ — עשה מצוה האמורה בענין שבשכרה תיכנס לארץ\" — ששתי הדרשות בענין הכניסה לארץ קשורות ובאות בהמשך זל\"ז, והיינו, שהחידוש בהבטחה זו ד­\"תיכנס לארץ\" לגבי ההבטחות הקודמות אודות ביאת הארץ הוא בזה, שבזכות עשיית (קבלת<sup data-n=\"1145\">8</sup>) \"מצוה האמורה בענין\", יכנסו לארץ מיד<sup data-n=\"1146\">9</sup>].",[["1138","1","יש אומרים אשר ע\"פ המסורה חסר כתיב בתורה — וראה (ע\"ז ט, א­ב) תנא תוספאה (ובערוך ע' ספר (הב') — הובא עה\"ג שם, ע\"א. וראה גם רש\"י שם ובסוף הע') כשמעתיקים בתושבע\"פ, ובכתיבת פי' הכתובים."],["1139","2","וראה ראב\"ע כאן."],["1140","3","ראה ספרי דבי רב לספרי (ושם \"כתב מהר\"ח. . דל\"ג לי'\". אבל מסיים \"דוחק גדול למ­חוק כל זה מהספרים\"). זרע אברהם. מלבי\"ם. צפע\"נ (להרגצ'ובי) עה\"ת. ועוד."],["1141","4","ראה לקמן בפנים ריש סעיף ג. וש\"נ."],["1142","5","לז, ב."],["1143","6","בס' בני יצחק (שאלוניקי, תקי\"ז) פי' דל­שיטת הספרי חיוב בכורים הוא מיד בבואם לארץ, ומש\"נ \"וירשתה וישבת בה\" היינו כדרשת הספרי שלאח\"ז — \"עשה מצוה כו' שבשכרה תיכנס לארץ\" (וע\"ד קידושין שם בסוף העמוד), שעשיית מצוה זו (מיד) \"היא הגורמת לך לרשת אותה וישבת בה\" (וראה גם משמרת הקודש על פרש\"י ריש פרשתנו).\nאבל פשטות ל' הספרי \"כי תבוא. . שבשכרה תיכנס לארץ\" משמע שהשכר הוא ביאת הארץ (ולא — ירושה וישיבה). ובפרט שמשנה מל' הספרי לעיל (פ' ראה יא, כט) \"בשכר שתבוא ותירש\" (כ\"ה בספרי שלפנינו. וראה ספרי הוצאת פינקלשטיין שם). וראה השקו\"ט במפרשי הספרי בפי' דרשת הספרי שלאח\"ז \"וירשתה וישבת בה, מה שתירש תכבש ותשב\". וראה לקמן בפנים והערה 8."],["1144","7","זית רענן על היל\"ש כאן (וכ\"פ בתולדות אדם לספרי כאן. ועוד).\nבפי' הב' תי' \"מיד אחר ירושה וישיבה\". וראה גם מלבי\"ם כאן דשולל שא\"צ להיות מנוחה (כבס\"פ תצא). וראה ראב\"ע כאן [ולהעיר מלשון הרמב\"ן כאן \"לאחר שכבשו וחלקו מיד כדברי רש\"י\" (אלא ש­כוונתו — קודם שנבחר הבית)] — אבל פשטות לשון הספרי לכאורה משמע \"מיד\" אחרי הביאה לארץ."],["1145","8","שהרי העשי' בפועל היתה רק לאחרי שנכנסו לארץ (ראה גם ש\"ך עה\"ת כאן). וראה ספרי (הובא בהערה 6) לעיל פ' ראה (יא, כט) \"אין והי' אלא מיד, כי יביאך קבל עליך מצוה האמורה בענין בשכר שתבוא ותירש\". וראה מפרשים שם.\n[ובזית רענן כאן \"בשכרה — פי' בשבילה\", כלומר, עשו מצוה זו לאחרי ירושה וישיבה כי בשבילה אתם נכנסים לארץ]."],["1146","9","ועפ\"ז מתורץ בפשטות מקור דרשה זו \"אין והי' אלא מיד\" — אף שבכ\"מ לשון \"והי'\" הוא דוקא לאחר זמן, כמו \"והי' בהניח גו'\" (הסמוך, ס\"פ תצא), \"והי' באחרית הימים\" (ישעי' ב, ב. ועוד) וכו' וכו' (וראה ספרי דבי רב כאן) — כי \"והי'\" הוא לשון שמחה (ב\"ר פמ\"ב, ג בסופו. וראה אוה\"ח ואו\"ת ל­הה\"מ ריש פרשתנו), ובנדו\"ד (ביאת הארץ) החידוש ושייכת שמחה על ביאת מיד, כי ביאת הארץ בכלל — הובטחה מאז.\nאבל להעיר, שמתו\"כ ויקרא (ה, ה. שם, כג), בהר (כה, כט) מוכח דלשון \"והי'\" כשלעצמו משמעו \"מיד\". וראה פי' הראב\"ד ומלבי\"ם ויקרא שם. ואכ\"מ."]]],[1301550217,"אבל פירוש זה צ\"ע, לכאורה, שהרי כתוב זה נאמר בסוף מ' שנה במדבר, כאשר כבר הגיע ממש זמן כניסת בנ\"י לארץ (כמפורש לפנ\"ז שהגזירה היתה למ' שנה בלבד) — ומהו החידוש ש\"מיד יבואו לארץ\"<sup data-n=\"1147\">10</sup>?\n[בשלמא בכתוב דפ' בא<sup data-n=\"1148\">11</sup> \"והי' כי יביאך אל הארץ גו'\", דאיתא במכילתא דרשב\"י שם<sup data-n=\"1148\">11</sup> \"אין והי' אלא מיד\" — הרי כיון שזה נאמר בהיותם במצרים, מתאים לפרש שהכוונה ב\"והי'\" היא לבשורה ש­\"מיד יבואו לארץ\" (כיון שהוא קודם גזי­רת המרגלים), וכדאיתא בספרי<sup data-n=\"1150\">12</sup> \"אילו זכו ישראל ליום אחד היו נכנסים לארץ שנאמר<sup data-n=\"1151\">13</sup> היום אתם יוצאים בחודש האביב והי' כי יביאך ה\"א אל ארץ הכנעני, מיד\".\nאבל בפרשתנו, בדברי משה בסוף ארבעים שנה, איך שייך לומר<sup data-n=\"1152\">14</sup> שבא לחדש (להבטיחם) דבר שהוא ברור ופשוט אצלם — ש\"מיד יבואו לארץ\"?].\nב. לכאורה יש לתרץ, שלפי דרשת הספרי, הרי כתוב זה (\"והי' כי תבוא אל הארץ גו' וירשתה וישבת בה\") אינו הק­דמה למצות ביכורים שנאמרה בפסוקים שלאח\"ז, אלא הוא ציווי בפ\"ע — על כיבוש הארץ וחילוקה<sup data-n=\"1153\">15</sup>. דאף שכבר נצטוו בפ' מסעי<sup data-n=\"1154\">16</sup> \"והורשתם גו' וישבתם גו' והתנחלתם גו'\", מ\"מ נכפל כאן ה­ציווי עוה\"פ. וזוהי כוונת הספרי \"אין והי' אלא מיד\", שחיוב זה של כיבוש (וחילוק) חל ומתחיל מיד בבואם אל הארץ, ואסור לדחות זה ללאח\"ז<sup data-n=\"1155\">17</sup>.\nועפ\"ז יומתק עוד ענין בהכתובים כאן:\nאם כל כוונת הכתוב כאן היא רק להגיד \"שלא נתחייבו בבכורים עד ש­כבשו את הארץ וחלקוה\"<sup data-n=\"1156\">18</sup> — צ\"ע, מדוע הוצרך הכתוב להקדים האריכות ע\"ד ביאת וכיבוש הארץ — \"והי' כי תבוא אל הארץ אשר ה\"א נותן לך נחלה וירשתה\" — דלכאורה הו\"ל להזכיר רק ישיבת (חלוקת) הארץ (ומובן מעצמו שהיינו",[["1147","10","ולכאורה דוחק לומר שחששו בסוף שנת הארבעים שמא יגרום החטא ותתעכב ביאתם לארץ. וראה פרש\"י מטות לא, ג. ואתחנן ג, כח."],["1148","11","יג, ה. וכן שם, יא."],["1148","11","יג, ה. וכן שם, יא."],["1150","12","ר\"פ דברים (א, ב)."],["1151","13","בא שם, ד­ה."],["1152","14","ודרשת הספרי לעיל פ' ראה שם \"אין והי' אלא מיד\" אפשר לפרשה בפשטות, שקאי על אמירת הברכות על הר עיבל כו', שהיתה מיד בבואם לארץ (ראה יהושע ח, ל ואילך ובפרש\"י רד\"ק ועוד שם) — לאפוקי מדעת ר' ישמעאל (ירושלמי סוטה פ\"ז ה\"ג, הובא בתוס' סוטה לג, ב) שנאמרו לאחרי י\"ד דכיבוש וחילוק — ראה מפרשי הספרי שם."],["1153","15","וצ\"ע אם גם מש\"נ בפ' מלך (פ' שופטים יז, יד) \"כי תבוא גו' וירשתה וישבת בה\" הוא ציווי בפ\"ע. ויש לחלק דשם הוא התחלת (הכתוב ו)הענין \"ואמרת אשימה גו'\", משא\"כ בפרשתנו שבא בפסוק בפ\"ע."],["1154","16","לג, נב ואילך."],["1155","17","וראה רש\"י, רד\"ק ועוד יהושע יא, יח (ולהעיר מלקו\"ש חי\"ד ע' 83. ואכ\"מ).\nולהעיר מפי' הזית רענן בדרשת הספרי כאן \"מה שתירש תכבש ותשב\". אבל מפרשי הספרי פירשו באו\"א."],["1156","18","ל' רש\"י ריש פרשתנו."]]],[1301550218,"לאחר ביאה וכיבוש)<sup data-n=\"1157\">19</sup>; וע\"ד מש\"נ לעיל בפ' ראה<sup data-n=\"1158\">20</sup> \"ועברתם את הירדן וישבתם בארץ גו'\" (וכפרש\"י שם<sup data-n=\"1159\">21</sup> דהיינו \"ש­תחלקוה ויהא כל אחד מכיר את חלקו ו­את שבטו\"), ולא נזכר שם אודות (ביאת<sup data-n=\"1160\">22</sup> ו)כיבוש הארץ, ועד\"ז בסוף הפרשה ה­קודמת — \"והי' בהניח ה\"א לך מכל אויביך מסביב גו'\".\nוע\"פ הנ\"ל מתורץ בפשטות, כי כיבוש וחלוקת הארץ בכתוב כאן אינם (רק) תנאי במצות בכורים, אלא ציווי בפ\"ע על הכיבוש והחלוקה, \"וירשתה וישבת בה\".\n[ואין זה סותר לדברי הגמ'<sup data-n=\"1161\">23</sup> שבזה בא ללמד שלא נתחייבו בבכורים עד לאחרי ירושה וישיבה (וכן פרש\"י עה\"פ \"מגיד שלא נתחייבו בבכורים עד שכב­שו את הארץ וחלקוה\") — כי זה נלמד מסמיכות הציוויים וסדרם — דמזה שה­כתוב חוזר על הציווי דכיבוש וחלוקת הארץ כאן, קודם לציווי מצות בכורים, ילפינן שאין חייבים בבכורים עד לאחרי קיום מצות כיבוש הארץ וחלוקתה].\nאבל דוחק לפרש כן בספרי<sup data-n=\"1162\">24</sup>, כי מ­לשונו בהדרשה שלאח\"ז \"עשה מצוה האמורה בענין\"<sup data-n=\"1163\">25</sup> משמע, שבכתוב זה עצמו אין ציווי (כ\"א ענין), והמצוה היא (רק) \"האמורה בענין\" (בפסוקים של­אח\"ז), מצות בכורים.\nג. ויש לומר הביאור בזה:\nמש\"נ \"כי תבוא גו' וירשתה וישבת בה\" — שהחיוב לא חל אלא \"לאחר ירו­שה וישיבה\" — יש לפרש בשני אופנים:\nא) לאחרי ירושתם וישיבתם של כל ישראל, וכן מפורש בפרש\"י בש\"ס<sup data-n=\"1164\">26</sup> ד\"לאחר ירושה וישיבה\" היינו אחרי י\"ד שנה דכיבוש וחילוק (וכפרש\"י עה\"ת כאן, ד\"לא נתחייבו בבכורים עד שכבשו את הארץ וחלקוה\").\nב) כל יחיד ויחיד, מיד כשכבש (קנה) את חלקו נתחייב במצוה זו.\nוהנה בירושלמי<sup data-n=\"1165\">27</sup> מפורש דלא נתחיי­בו במצות התלויות בארץ \"אלא לאחר ארבע עשרה שנה שבע שכיבשו ושבע שחילקו. . עד שעה שקנו כולה\", ולא אמרינן ד\"ראשון ראשון קונה ומתחייב\"<sup data-n=\"1166\">28</sup> (וכן הובאה בירושלמי<sup data-n=\"1167\">29</sup> ברייתא דר' ישמעאל — \"כל ביאות שנאמרו בתורה לאחר ארבע עשרה שנה נאמרו שבע שכיבשו ושבע שחילקו\"<sup data-n=\"1168\">30</sup>) — כאופן הא' הנ\"ל.",[["1157","19","ראה גם מלבי\"ם כאן.\nבמשכיל לדוד כאן תי', דאם הי' נאמר רק \"וישבת בה\", \"הו\"א דאם חלקו מקצתם קודם כיבוש הכל יהיו חייבים בבכורים מש\"ה כתיב וירשתה דכולה משמע דהיינו אחר גמר כל הכיבוש\". אבל צ\"ע מאי עדיפא לשון \"וירשתה\" מלשון \"וישבת בה\" (שלכאורה ג\"כ \"כולה משמע\"). ועכ\"פ הול\"ל \"וישבתם בארץ\" כבפ' ראה שהובא בפנים. וראה לקו\"ש ח\"ט ע' 152 ואילך (ובהערות 8, 15 שם)."],["1158","20","יב, י."],["1159","21","ד\"ה ועברתם. ושם ד\"ה והניח לכם: לאחר כבוש וחלוק ומנוחה כו'."],["1160","22","ורק נאמר \"ועברתם את הירדן\"."],["1161","23","קידושין לז, ב."],["1162","24","אבל י\"ל שבפשוטו של מקרא כ\"ה, ולכן לא נחית רש\"י לתרץ שאלה זו (שבפנים), למה נאמרה כאן ההקדמה ד\"והי' כי תבוא גו' וירשתה\"."],["1163","25","וכדיוק הספרי דבי רב ותולדות אדם כאן (והם מפרשים \"מצוה האמורה בענין\" — מצות זכירת עמלק שבסוף פרשה הקודמת. וראה בעה\"ט כאן)."],["1164","26","קידושין לז, א ד\"ה אבל חדש, ד\"ה ללמדך, ד\"ה והרי שבת."],["1165","27","שביעית רפ\"ו. וראה תוספתא מנחות ספ\"ו. קידושין מ, ב וברש\"י שם ד\"ה גדול."],["1166","28","ל' הירושלמי שם — בנוגע לכיבוש עזרא."],["1167","29","חלה פ\"ב ה\"א. ערלה פ\"א ה\"ב. סוטה פ\"ז ה\"ג."],["1168","30","משא\"כ בבבלי (קידושין לז, ב) וספרי שלח (טו, ב) איתא רק \"לאחר ירושה וישיבה\" (כלשון הכתוב \"וירשתה וישבת\")."]]]]});
